var QT_DATA={"tp":[{"t":"Mở đầu","n":0,"g":[{"h":"","b":[["p","Học thuộc C2; C3,4: trong luật. C5678 chỉ hỏi trong luật"],["p","- Hiệp định tương trợ tư pháp giữa VN và các nước (hiệp định TTTP VN - Liên Bang Nga)"],["p","- Công ước New York 1958 về công nhận và cho thi hành quyết định của trọng tài nước ngoài; QĐ 453/1995 (có tuyên bố bảo lưu của VN)"],["p","- Bộ Luật Dân sự - Phần thứ 5, chương XXV, từ Điều 663 đến 687"],["p","- Bộ luật tố tụng dân sự 2015 - Chương XXXVI và XXXVIII (432 và 481)"],["p","- Luật trọng tài thương mại 2010 và nghị quyết 01/2014 do HĐTPTANDTC"],["p","- Luật HNGD 2014"],["p","- Luật Hộ tịch 2014 (có hiệu lực 2016)"],["p","- Luật tổ chức tòa án nhân dân"]]}]},{"t":"TỔNG QUAN VỀ TƯ PHÁP QUỐC TẾ","n":1,"g":[{"h":"","b":[["p","- Là một nhánh, một ngành luật của pháp luật quốc gia"]]},{"h":"1. Đối tượng điều chỉnh, phạm vi điều chỉnh Xác định yếu tố nước ngoài trong dân sự như nào? CSPL? Tiêu chí?","b":[["p","Xác định yếu tố nước ngoài mang lại ý nghĩa gì?"],["p","Phạm vi điều chỉnh của TPQT (Bao gồm những vấn đề pháp lý nào?)"],["p","- Có 2 nhóm QHXH:"],["p","+ Quan hệ dân sự theo nghĩa rộng (hôn nhân gia đình, sở hữu, thừa kế, lao động, thương mại...) có yếu tố nước ngoài"],["p","+ Quan hệ tố tụng dân sự có yếu tố nước ngoài"],["p","*NHÓM 1: Quan hệ dân sự có yếu tố nước ngoài"],["p","- Quan hệ dân sự: (Thế nào là quan hệ dân sự? Khi nào quan hệ dân sự có yếu tố nước ngoài)"],["p","+ Quan hệ dân sự: Điều 1 BLDS 2015:"],["p","Chủ thể: cá nhân, pháp nhân"],["p",""],["p","Nội dung: quyền và nghĩa vụ nhân thân (quyền kết hôn, khai  sinh...) và tài sản (hợp đồng, BTTH về hợp đồng, sở hữu...). Vừa nhân thân vừa tài sản là quan hệ thừa kế."],["p","Tiêu chí: Bình đẳng, tự do về ý chí, độc lập về tài sản và tự chịu  trách nhiệm"],["p","+ Yếu tố nước ngoài: Khoản 2 Điều 663 BLDS 2015 Chủ thể:"],["p",""],["p","Cá nhân nước ngoài: Điều 3.1 Luật xuất cảnh, nhập cảnh, quá  cảnh của nnn tại VN 2014: Bao gồm người có quốc tịch nước ngoài và người không quốc tịch Pháp nhân nước ngoài: Điều 4.32 LDN 2020 => là tổ chức có  tư cách pháp nhân được đăng ký thành lập theo pháp luật nước ngoài và có trụ sở đăng ký tại nước ngoài Quốc gia - Chủ thể đặc biệt (có quyền miễn trừ vì đây là chủ  thể có chủ quyền): Điều 97, 100 BLDS Người Việt Nam định cư ở nước ngoài (quy định ở luật cũ  BLDS 2005): (1) người Việt Nam; (2) người gốc Việt Nam. => Phạm vi điều chỉnh của BLDS 2015 không bị hẹp đi dù không còn nhóm người Việt Nam định cư ở nước ngoài, chỉ sửa đổi để phù hợp hơn so với khoản 3, 4 Điều 3 Luật Quốc tịch 2008 (sửa đổi 2014) => Người gốc VN có thể chọn giữ or bỏ quốc tịch Sự kiện pháp lý (chỉ được áp dụng trong trường hợp cá nhân, pháp  nhân VN): hành vi xảy ra ở nước ngoài Đối tượng (chỉ được áp dụng trong trường hợp cá nhân, pháp nhân  VN): đối tượng ở nước ngoài. Không chỉ là tài sản mà còn có thể là các công việc, dịch vụ,... Chỉ được sử dụng khi các bên tham gia đều phải là công dân/pháp nhân Việt Nam."],["p","=> Chỉ cần thỏa mãn 1 trong 3 điều kiện thì quan hệ đó đã được xem là quan hệ có yếu tố nước ngoài (dấu hiệu về sự kiện pháp lý và đối tượng chỉ được sử dụng khi các bên tham gia đều là công dân Việt Nam, pháp nhân Việt Nam. (khi đi thi câu hỏi này có thể là câu hỏi cuối cùng)"],["p","*NHÓM 2: Quan hệ tố tụng dân sự có yếu tố nước ngoài"],["p","Ví dụ: Hà (VN) - Ly hôn - Mary (Anh)"],["p","- Người tham gia tố tụng"],["p","- Người tiến hành tố tụng (Tòa án...)"],["p","=> xác định vấn đề pháp lý: năng lực PLTTDS và NLHVTTDS; thẩm quyền;"],["p","công nhận và cho thi hành án. Nếu được giải quyết ở Tòa nước ngoài thì Tòa Việt Nam có chấp nhận không? => thừa nhận và không xét xử lại Kết luận: Đối tượng điều chỉnh của Tư pháp quốc tế là những quan hệ dân sự theo nghĩa rộng (kinh doanh, lao động, thương mại, sở hữu, hôn nhân gia đình, BTTH ngoài hợp đồng...) có yếu tố nước ngoài và các quan hệ tố tụng dân sự có yếu tố nước ngoài."]]},{"h":"2. Phương pháp điều chỉnh","b":[["p","Gồm những phương pháp nào, khái niệm, dấu hiệu nhận biết mỗi phương pháp Phân biệt sự khác biệt giữa 2 phương pháp, đánh giá ưu nhược điểm của mỗi phương pháp (tính linh hoạt của phương pháp xung đột thì phải giải thích nó linh hoạt như nào)"],["p","- Xác định pháp luật áp dụng đối với quan hệ dân sự có yếu tố nước ngoài"],["p","- Xác định thẩm quyền của tòa án quốc gia đối với vụ việc dân sự có yếu tố nước ngoài"],["p","- Công nhận và cho thi hành bản án, quyết định dân sự của TANN, phán quyết của trọng tài nước ngoài"],["p","- Ủy thác nước ngoài (tách thành môn khác) Các bước:"],["p","+ Tòa VN có thẩm quyền không? Dấu hiệu xác định thẩm quyền? CSPL?"],["p","+ Luật nào được áp dụng? (chỉ nói hệ thống nào, không đi sâu vào luật gì, điều gì)"],["p","+ Bản án, quyết định của TANN, TTNN đáp ứng điều kiện gì để được thi hành tại Việt Nam?"],["p","*Phương pháp thực chất (phương pháp điều chỉnh trực tiếp)"],["p","- Khắc phục hạn chế của phương pháp xung đột là không giải quyết trực tiếp được vấn đề."],["p","- Là phương pháp sử dụng quy phạm thực chất nhằm điều chỉnh trực tiếp các quan hệ dân sự có yếu tố nước ngoài."],["p","- Không thông qua một hệ thống PL trung gian nào."],["p","Ví dụ 1: Công ty A (Việt Nam) ký kết một hợp đồng bán gạo ST25 cho công ty B (Đức). Hai bên chọn giao hàng theo điều kiện CPT (Người mua chịu mọi phí tổn và rủi ro kể từ khi hàng đã được giao cho người chuyên chở). Hàng hóa đã được công ty A giao cho công ty chuyên chở C (Hà Lan) để vận chuyển từ Việt Nam sang Đức, trong quá trình vận chuyển hàng hóa đã gặp một cơn bão và toàn bộ hàng hóa trên đã hư hỏng. Rủi ro thuộc về ai? => Có 3 hệ thống pháp luật được đặt ra để áp dụng giải quyết vấn đề. Tại đây, vì các bên đã thỏa thuận chọn điều kiện CPT nên rủi ro sẽ thuộc về B => Tức là trực tiếp xác định được bên nào có nghĩa vụ đối với hàng hóa trong trường hợp này."],["p","- Quy phạm thực chất: Là loại quy phạm trực tiếp điều chỉnh các quan hệ dân sự có yếu tố nước ngoài. Nội dung các quy phạm này thường quy định về quyền và nghĩa vụ của các bên, về các biện pháp hình thức chế tài có thể được áp dụng."],["p","- Nguồn của quy phạm thực chất (cách thức xây dựng):"],["p","+ Điều ước quốc tế (Quy phạm thực chất thống nhất) => Do các QG thỏa thuận xây dựng nên"],["p","+ Tập quán quốc tế => Điểm khác biệt đối với quy phạm xung đột."],["p","+ Pháp luật quốc gia:"],["p","Do quốc gia thỏa thuận"],["p",""],["p","Do quốc gia thừa nhận"],["p",""],["p","Do quốc gia đơn phương ban hành"],["p",""],["p","*Ưu điểm: Hiệu quả cao, tiết kiệm chi phí"],["p","*Hạn chế: Các quy phạm thực chất (đặc biệt là QPTCTN) hiện không nhiều, việc xây dựng khó khăn, không đáp ứng được yêu cầu thực tiễn của việc điều chỉnh các QHDS có YTNN"],["p","*Phương pháp xung đột (phương pháp điều chỉnh gián tiếp):"],["p","- Khái niệm: Là phương pháp áp dụng quy phạm pháp luật xung đột nhằm lựa chọn hệ thống, không trực tiếp giải uyết các quan hệ pháp luật cụ thể mà chỉ quy định nguyên tắc chọn luật nhằm điều chỉnh quan hệ dân sự có yếu tố nước ngoài."],["p","*Cách thức xây dựng quy phạm xung đột:"],["p","+ Do quốc gia thỏa thuận"],["p","+ Do quốc gia đơn phương ban hành"],["p","- Điều 19 HĐTTTP Việt - Nga"],["p","- Điều 129 Luật HNGD"],["p","*Hạn chế:"],["p","+ Không trực tiếp giải quyết vấn đề, việc vận dụng quy phạm xung đột không đơn giản, có thể dẫn chiếu đến luật nước ngoài"],["p","+ Quy tắc ở mỗi quốc gia là khác nhau"],["p","*Ưu điểm:"],["p","- Áp dụng linh hoạt, mềm dẻo hơn so với QPTC"],["p","- Mnag tính khách quan, đặc biệt khi áp dụng quy phạm xung đột 2 chiều"],["p","- Dễ dàng trong công tác xây dựng, thiết lập QPXĐ"],["p","*Lưu ý:"],["p","- Phương pháp đặc thù: PP xung đột"],["p","- Bổ sung hỗ trợ lẫn nhau"]]},{"h":"3. Nguồn của Tư pháp quốc tế","b":[["p","3 nguồn (ĐƯQT, PLQG, TQQT) => CSPL nào (665,664) Trong 3 nguồn đó thì nguồn nào được ưu tiên và nguồn nào cơ bản và chủ yếu nhất? Thứ tự ưu tiên áp dụng các loại nguồn"]]},{"h":"3.1. Điều ước quốc tế","b":[["p","a) Khái niệm:"],["p","- Điều 2.1.a CƯV 1969"],["p","- Trường hợp áp dụng:"],["p","+ Áp dụng khi VN là thành viên (Điều 664.1 BLDS, Điều 2.3 BLTTDS)"],["p","=> Ưu tiên"],["p","+ Áp dụng khi các bên lựa chọn (chưa là thành viên): quyền chọn luật. Khi quan hệ dân sự xuyên biên giới được chọn luật áp dụng. Nguyên tắc lựa chọn chỉ phát sinh trong một số quan hệ dân sự có yếu tố nước ngoài (sở hữu, thừa kế, hngd thường không được chọn ở VN). Quan hệ tố tụng dân sự có yếu tố nước ngoài không bao giờ được chọn. Điều kiện được chọn: (1) xác định chủ thể chọn quyền"],["p","- Vấn đề pháp lý: ưu tiên áp dụng ĐƯQT trong trường hợp nào"],["p","+ Khoản 2 Điều 665 BLDS, 668 thì sẽ thấy cụm từ “vi phạm quy định về quyền và nghĩa vụ của các bên”"],["p","+ Điều 6.1 Luật Điều ước quốc tế 2016"],["p","=> phải là thỏa thuận bằng văn bản, các bên thỏa thuận với nhau (664.1,2). Một số trường hợp từ chối: ĐƯQT có quy định chấp nhận k thực hiện"]]},{"h":"3.2. Pháp luật quốc gia","b":[["p","- Hệ thống pháp luật quố gia là một hệ thống các nguồn luật được thừa nhận ở quốc gia đó"],["p","- Pháp luật quốc gia là nguồn cơ bản, chủ yếu của tư pháp quốc tế? Xu hướng TPQT trên thế giới và tại Việt Nam? (phải đưa ra dẫn chứng, giải thích cụ thể tại 5đ)"],["p","- Theo anh chị thì Việt Nam có cần thiết phải ban hành một văn bản pháp luật riêng về tư pháp hay không?"],["p","- Các trường hợp áp dụng luật quốc gia?"],["p","- CSPL nào để xác định pháp luật quốc gia là nguồn của TPQT => Điều 664 BLDS"],["p","- Trường hợp áp dụng:"],["p","+ Điều 664.1:"],["p","Quy phạm xung đột thống nhất (trong ĐƯQT) => áp dụng quy  phạm xung đột (665 or 668.2) Cùng quốc tịch => Bên ký kết (quốc tịch)  Khác quốc tịch + thường trú chung => bên ký kết có nơi  thường trú chung Khác quốc tịch + khác nơi cư trú => bên ký kết là nơi nộp đơn  ly hôn (PL của nước có tòa án) Quy phạm xung đột thông thường (trong PLQG) or Luật VN (127  Luật HNGĐ, 470 BLTTDS 2015)"],["p","+ Điều 664.2: Sự lựa chọn của các bên"],["p","Khoản 1 Điều 683 => chọn luật"],["p",""],["p","+ Điều 664.3: PL có mối liên hệ gắn bó mật thiết Ưu tiên 1 là điều ước quốc tế, 2 là pháp luật quốc gia, 3 là tập quán  quốc tế (luật cũ) Áp dụng khi: Nếu không xác định được khoản 1 và khoản 2 Điều  664 => PL có mối liên hệ gắn bó mật thiết phải là pháp luật của một quốc gia nào đó"],["p","687.1 => nguyên tắc chọn luật."],["p",""]]},{"h":"3.3. Tập quán quốc tế","b":[["p","- Tập quán quốc tế là những quy tắc xử sự được hình thành trong một thời gian dài, được áp dụng liên tục và được sự thừa nhận của đông đảo quốc gia (URC 552, Incoterms 2020)"],["p","- Trong các tập quán chỉ tồn tại quy phạm thực chất, không có quy phạm xung đột?"],["p","- Thỏa thuận trên các cơ sở:"],["p","+ Điều 666 BLDS =>Sự lựa chọn"],["p","+ Điều 5.2 Luật TM 2005"],["p","+ Điều 4.4 Luật Đầu tư"],["p","+ Điều 4 BLHH 2015"]]},{"h":"4. Chủ thể của Tư pháp quốc tế","b":[["p","Họ là ai => CSPL, người nước ngoài, phạm nhân nước ngoài và chủ thể đặc biệt là quốc gia (liên quan đến quyền miễn trừ của quốc gia) Bao gồm:"],["p","- Cá nhân nước ngoài"],["p","- Pháp nhân nước ngoài"],["p","- Công dân Việt Nam"],["p","- Pháp nhân Việt Nam"],["p","- Quốc gia - chủ thể đặc biệt"]]},{"h":"4.1. Quốc gia - chủ thể đặc biệt","b":[["p","Tại sao quốc gia là chủ thể đặc biệt? Quyền miễn trừ quốc gia được hiểu ntn?"],["p","Thuyết miễn trừ tương đối và miễn trừ tuyệt đối? Pháp luật VN về quyền miễn trừ?"]]},{"h":"4.1.1. Khái niệm và các quyền miễn trừ","b":[["p","Là quyền bảo đảm cho một quốc gia không phải chịu sự điều chỉnh của thẩm quyền của một quốc gia khác, bao gồm cả thẩm quyền lập pháp, hành pháp và tư pháp./ Miễn trừ quốc gia trong tư pháp quốc tế có nghĩa là quyền của một quốc gia không thể bị xét xử tại tòa án của một quốc gia khác (Điều 5 UNCSI - VN chưa là thành viên)"]]},{"h":"4.1.2. Nội dung quyền miễn trừ","b":[["p","- Cá nhân và pháp nhân nhân danh quốc gia"],["p","a) Quyền miễn trừ xét xử (tư pháp)"],["p","- Là không có bất kỳ một cơ quan tài phán nào (trọng tài or tòa án) được quyền xét xử 1 vụ kiện mà trong đó bị đơn là quốc gia nếu quốc gia đó không đồng ý"],["p","- Điều 5 UNCSI"],["p","b) Quyền miễn trừ đối với các biện pháp đảm bảo vụ kiện"],["p","- Nếu quốc gia đồng ý là bị đơn thì vẫn không được áp dụng các biện pháp bảo đảm nếu quốc gia không đồng ý"],["p","- Điều 18 UNCSI"],["p","c) Quyền miễn trừ về thi hành án"],["p","- Nếu quốc gia đồng ý cả a và b thì cũng không được áp dụng trừ khi quốc gia tự nguyện thi hành"],["p","- Điều 19 UNCSI"],["p","d) Quyền miễn trừ về tài sản"],["p","- Đối với tài sản của quốc gia là bất khả xâm phạm nếu quốc gia không đồng ý or không cho phép"],["p","- Điều 21 UNCSI"],["p","- Mối quan hệ giữa các quyền miễn trừ:"],["p","+ Gắn bó chặt chẽ với nhau nhưng độc lập nhau"],["p","+ Việc từ bỏ quyền miễn trừ của quốc gia cần phải được thể hiện rõ ràng trong pháp luật quốc gia, trong điều ước quốc tế mà quốc gia là thành viên hoặc trong các hợp đồng quốc gia ký kết"]]},{"h":"4.1.3. Quan điểm miễn trừ","b":[]},{"h":"4.1.3.1. Miễn trừ tuyệt đối","b":[["p","- Nội dung: Chủ quyền của quốc gia là tuyệt đối, bất khả xâm phạm"],["p","- Quyền miễn trừ đương nhiên được hưởng trừ khi quốc gia từ chối"]]},{"h":"4.1.3.2. Miễn trừ tương đối","b":[["p","- Chấp thuận quốc gia được hưởng quyền miễn trừ khi tham gia quan hệ dân sự nhưng hạn chế một số trường hợp mà quốc gia không được hưởng quyền miễn trừ."],["p","- Các trường hợp bị từ chối quyền miễn trừ:"],["p","+ Quốc gia từ bỏ quyền miễn trừ minh thị hoặc mặc thị (Điều 7)"],["p","+ Vụ kiện liên quan đến giao dịch thương mại mà quốc gia tham gia với tư cách một bên chủ thể, bên còn lại là cá nhân, pháp nhân (Điều 10)"],["p","+ Vụ kiện liên quan đến hợp đồng lao động giữa quốc gia và thể nhân (Điều 11)"]]},{"h":"4.1.4. Cơ chế hưởng quyền miễn trừ","b":[["p","- CSPL: Điều 100 BLDS, 4.2, 172.1 BLTTDS"],["p","=> Việt Nam theo miễn trừ tuyệt đối, được hưởng quyền miễn trừ trong mọi trường hợp trừ khi từ chối"]]}]},{"t":"XUNG ĐỘT PHÁP LUẬT VÀ ÁP DỤNG PHÁP LUẬT NƯỚC NGOÀI","n":2,"g":[{"h":"","b":[["p","Ví dụ: Công ty B (nguyên đơn) và Công ty L (bị đơn) xác lập với nhau hai hợp đồng. Nguyên đơn là một doanh nghiệp 100% vốn nước ngoài và người ký hợp đồng trong phần của Nguyên đơn là một cá nhân có quốc tịch nước ngoài"],["p","1) Có yếu tố nước ngoài hay không? Đây không phải là vụ án dân sự có yếu tố nước ngoài vì nếu là nước ngoài thì B phải là doanh nghiệp VN"],["p","2) Tại sao phải xác định yếu tố nước ngoài? Để xác định có thể áp dụng PL khác hay không (Điều 14 luật trọng tài thương mại)"],["p","3) Xác định yếu tố nước ngoài như thế nào? Điều 4.3 Luật TTTM, 663.2 BLDS"]]},{"h":"1. Xung đột pháp luật (hệ thống pháp luật cần được áp dụng?) Khái niệm (nội hàm ntn..)?","b":[["p","Nguyên nhân và điều kiện làm phát sinh xung đột pháp luật? (làm rõ 2 nguyên nhân, có cơ sở và căn cứ);"],["p","Phương pháp, cách thức giải quyết xung đột pháp luật?"],["p","Quy phạm xung đột (khái niệm, đặc điểm, cơ cấu, phân loại)?"],["p","Hiểu và nắm rõ kiểu hệ thuộc luật (luật nhân thân của cá nhân, luật quốc tịch của pháp nhân, luật nơi có tài sản, luật tòa án, luật do các bên lựa chọn, luật có mối liên hệ gắn bó mật thiết) => khái niệm, phạm vi áp dụng, CSPL, trường hợp ngoại lệ."]]},{"h":"1.1. Khái niệm","b":[["p","- Khái niệm: là hiện tượng có 2 hay nhiều hệ thống pháp luật của các nước khác nhau cùng có thể được áp dụng để điều chỉnh một quan hệ dân sự có yếu tố nước ngoài Trong cùng 1 quốc gia thì có hiện tượng xung đột này không? => không vì đó chỉ là sự khác biệt chứ không phải xung đột, ưu tiên áp dụng luật chuyên ngành."],["p","Trong các ngành luật khác? => Xung đột chỉ xuất hiện trong tư pháp, các ngành khác xung đột không phát sinh vì đó là các ngành luật công và chịu sự điều chỉnh của 1 hệ thống pháp luật duy nhất của một quốc gia nào đó."],["p","Trong tất cả các đối tượng điều chỉnh của TPQT? => Trong quan hệ tố tụng dân sự thì không phát sinh xung đột, chỉ có quan hệ dân sự"]]},{"h":"1.2. Nguyên nhân phát sinh xung đột pháp luật","b":[["p","- Nguyên nhân phát sinh xung đột pháp luật:"],["p","+ Có quan hệ dân sự có yếu tố nước ngoài"],["p","+ Pháp luật các nước có nội dung khác nhau Vì sao khi xuất hiện quan hệ dân sự có yếu tố nước ngoài thì có xuất hiện xung đột mà các quan hệ khác thì không phát sinh? => Có yếu tố nước ngoài thì áp dụng nguyên tắc bình đẳng tôn trọng chủ quyền giữa các quốc gia. Khả năng áp dụng hệ thống pháp luật cũng ngang hàng nhau. Nguyên tắc thứ hai là nguyên tắc bảo hộ công dân (chủ thể tham gia chủ yếu là cá nhân và pháp nhân). Khả năng áp dụng PL nước ngoài đến từ nguyên tắc thiện chí giữa các quốc gia và các học thuyết."],["p","Vì sao pháp luật các nước không quy định giống nhau?"],["p","Nếu pháp luật các nước quy định giống nhau thì có phát sinh xung đột pháp luật không? => so sánh 2 hệ thống pháp luật chứ không phải giữa các quy phạm pháp luật riêng lẽ"]]},{"h":"1.3. Phương pháp giải quyết xung đột pháp luật:","b":[["p","- Phương pháp giải quyết xung đột pháp luật:"],["p","+ Phương pháp thực chất"],["p","+ Phương pháp xung đột"],["p","Phân biệt sự khác nhau giữa Phương pháp điều chỉnh và phương pháp giải quyết?"]]},{"h":"1.4. Quy phạm xung đột:","b":[["p","- Khái niệm: Quy phạm xung đột là quy phạm pháp luật xác định hệ thống pháp luật cần điều chỉnh một quan hệ dân sự có yếu tố nước ngoài (Điều 667, 680 BLDS) => là một quy tắc xử sự, mang bản chất chuẩn mực về mặt pháp lý"],["p","=> chủ thể được làm gì, như thế nào, làm tới đâu => quy định xác định một vấn đề pháp luật áp dụng"],["p","+ Điều 673 đến 687 BLDS"],["p","- Đặc điểm:"],["p","+ Là quy phạm đặc thù của Tư pháp quốc tế"],["p","+ Chức năng dẫn chiếu (chức năng cơ bản) => không trực tiếp chỉ rõ quyền và nghĩa vụ các bên"],["p","- Cơ cấu: 2 bộ phận"],["p","+ Phạm phạm vi: Nêu một vấn đề pháp luật hoặc một quan hệ dân sự có yếu tố nước ngoài cụ thể (thông thường phần phạm vi nằm ở phần đầu tiên của quy phạm. VD: năng lực pháp luật của cá nhân, định danh tài sản, quyền khác đối với tài sản,...)"],["p","+ Phần hệ thuộc: Thường có nội dung chỉ ra hệ thống pháp luật or nguyên tắc chọn luật để điều chỉnh cho vấn đề được nêu ở phần phạm vi."],["p","+ VD: Điều 673 => 1 phạm vi và 1 hệ thuộc"],["p","+ VD: khoản 2 Điều 678, khoản 1 126 LHNGD => 1 phạm vi và nhiều hệ thuộc (2 nguyên tắc chọn luật)"],["p","- Phân loại:"],["p","+ Căn cứ tính chất dẫn chiếu:"],["p","Quy phạm xung đột mệnh lệnh: Điều 673, 674 => quy định bắt  buộc, chịu sự điều chỉnh của pháp luật cụ thể (sở hữu, kết hôn (trừ trường hợp thuận tình ly hôn thì sẽ được lựa chọn), thừa kế không được lựa chọn luật) Quy phạm xung đột tùy nghi: khoản 1 Điều 683, khoản 2 Điều 678 "],["p","+ Căn cứ kỹ thuật xây dựng quy phạm:"],["p","Quy phạm xung đột một bên: khoản 2 Điều 673, 674 => chỉ ra hệ  thống pháp luật của một quốc gia cụ thể sẽ được áp dụng, đó là pháp luật của nước đã xây dựng và ban hành quy phạm đó đó."],["p","Quy phạm xung đột đa bên (nhiều bên): khoản 1 Điều 673, 674 =>  hệ thống pháp luật được áp dụng có thể là pháp luật VN or pháp luật nước ngoài. => Không chỉ ra hệ thống pháp luật của một quốc gia cụ thể mà chỉ quy định quy tắc chọn luật của nước này hay luật của nước kia. VD: Nguyên tắc luật quốc tịch của cá nhân"],["p","+ Căn cứ nguồn:"],["p","Quy phạm xung đột thông thường: Điều 673, 674  Quy phạm xung đột thống nhất: Điều 39, HĐ TTTP Việt Nga  Quy phạm xung đột thống nhất có thể là quy phạm xung đột 1 bên  hay không? => quy phạm xung đột thống nhất được quy định trong điều ước quốc tế mà quốc gia là thành viên, vậy không phải quốc gia đơn phương ban hành mà là đa bên quy định. => chỉ có thể là quy phạm đa bên, không thể 1 bên được Quy phạm xung đột mệnh lệnh luôn luôn là quy phạm một bên? =>  đối với quy phạm xung đột mệnh lệnh còn có thể là quy phạm 2 bên vì chỉ ra nguyên tắc xác định luật áp dụng, mà mệnh lệnh là quy định chính xác hệ thống pl cần được áp dụng. 2 là có thể là mệnh lệnh là đặt ra 1 nguyên tắc chọn luật, đáp ứng điều kiện nào thì áp dụng cái đó chứ các bên không được chọn luật"]]},{"h":"1.5. Kiểu hệ thuộc:","b":[["p","Khái niệm: Là các nguyên tắc xác định luật áp dụng đối với quan hệ dân sự có yếu tố nước ngoài Một số nguyên tắc điển hình: (từ 1 đến 5 quan trọng)"],["p","- Luật nhân thân của cá nhân:"],["p","+ Luật quốc tịch của cá nhân"],["p","+ Luật nơi cá nhân cư trú"],["p","- Luật quốc tịch của pháp nhân"],["p","- Luật do các bên lựa chọn"],["p","- Luật Tòa án"],["p","- Luật nơi có tài sản => tài sản hữu hình => áp dụng luật của quốc gia nơi có tài sản"],["p","- Luật có mối liên hệ gắn bó mật thiết => chặt chẽ nhất với 1 quốc gia nhất định"],["p","- Luật nơi thực hiện hành vi"],["p","- Luật nơi xảy ra thiệt hại"],["p","- Luật treo quốc kỳ"]]},{"h":"1.5.1. Luật nhân thân của cá nhân","b":[["p","- Khái niệm: Là nguyên tắc áp dụng pháp luật của nước mà cá nhân có quốc tịch hoặc pháp luật của nước nơi cá nhân cư trú để điều chỉnh các vấn đề về nhân thân của cá nhân."],["p","- Phạm vi áp dụng:"],["p","+ Pháp luật quốc tế"],["p","+ Pháp luật Việt Nam: Điều 673, 674, 680, 682 BLDS; 126, 127, 129 Luật HNGĐ Trường hợp cá nhân là người nhiều quốc tịch or không quốc tịch => 672.2:"],["p","(không phải quy phạm xung đột)"],["p","+ Nhiều quốc tịch:"],["p","Quốc tịch nước ngoài + VN => áp dụng bởi pháp luật VN  Không có quốc tịch VN:"],["p",""],["p","Có quốc tịch + cư trú tại thời điểm xác lập giao dịch (tại QG  đó) Có quốc tịch + có mối liên hệ gắn bó mật thiết "],["p","+ Không quốc tịch:"],["p","Cư trú"],["p",""],["p","Mối liên hệ gắn bó mật thiết"],["p",""],["p","- Vấn đề 2: Luật của nước mà pháp nhân có quốc tịch áp dụng giải quyết những vấn đề pháp lý nào? Điều 676.2"],["p","+ Điều kiện hoạt động: 676.3"]]},{"h":"1.5.2. Luật do các bên lựa chọn","b":[["p","- Khái niệm: Là nguyên tắc xác định pháp luật điềuchinrh quan hệ dân sự có yếu tố nước ngoài căn cứ vào lựa chọn của các bên"],["p","- Phạm vi áp dụng:"],["p","+ Pháp luật quốc tế: Điều 9.1, 12 CISG 1980; Điều 36.1 HĐTTTP Việt - Nga"],["p","+ Pháp luật Việt Nam: Điều 678.2, 683.1, 684, 687 BLDS; 5.2 LTM 2005;"],["p","5 BLHH 2015"],["p","- Điều kiện chọn luật:"],["p","+ Hình thức: có thỏa thuận về việc chọn luật => tự do về mặt ý chí => có thể là điều khoản trong hợp đồng or có quy định trong phụ lục đi kèm => một trong các bên chứng minh được bên còn lại vi phạm hình thức thì sẽ vi phạm về mặt tự do, thiện chí => vô hiệu"],["p","+ Quyền chọn luật: Điều 664.2 BLDS; 5 BLHH; 14 Luật TTTM 2010"],["p","+ Nội dung: Áp dụng có tính khả thi (668.4; 670)"],["p","+ Không nhằm mục đích lẩn tránh pháp luật"],["p","- Tính khả thi: có khả năng áp dụng:"],["p","+ Lựa chọn quy phạm thực chất: 668.4"],["p","+ Hệ quả pháp lý => không trái nguyên tắc cơ bản: 670.1 BLDS, 14.3 LTTTM, 5.3 BLHH"],["p","- Một số vấn đề pháp lý:"],["p","+ Giới hạn quyền chọn: được chọn hay không"],["p","+ Thời điểm chọn luật: Trước, trong hay sau khi xảy ra tranh chấp"]]},{"h":"1.5.3. Hệ thuộc luật tòa án:","b":[["p","- Khái niệm: là nguyên tắc xác định pháp luật áp dụng đối với quan hệ dân sự có yếu tố nước ngoài căn cứ pháp luật của nước nơi có tòa án đang thụ lý giải quyết vụ việc dân sự có yếu tố nước ngoài"],["p","- Phạm vi áp dụng:"],["p","+ Luật nội dung: không đương nhiên áp dụng Lex fori (luật của nước có tòa án) => quy định quyền và nghĩa vụ của các chủ thể tham gia quan hệ dân sự có yếu tố nước ngoài"],["p","+ Luật hình thức: Đương nhiên áp dụng Lex fori (đương nhiên cho quan hệ giữa 2 bên NTGTT và NTHTT) => quy định thẩm quyền và công nhận cho thi hành. Xuất phát từ nguyên tắc chủ quyền quốc gia"],["p","*Ngoại lệ: Điều 2.3, 466, 467 BLTTDS 2015 A (VN) => B (Sing). Phát sinh 2 quan hệ là quan hệ tố tụng dân sự  và quan hệ dân sự. Trong quan hệ tố tụng dân sự gồm người THTT và người TGTT. => trường hợp này áp dụng Lex fori => Tòa án VN. Pháp luật Vn sẽ được áp dụng để giải quyết 2 vấn đề: (1) xác định tòa án việt nam có thẩm quyền hay không?, (2) vấn đề công nhận và cho thi hành. Nhưng có ngoại lệ là điều ước quốc tế mà VN là thành viên có quy định khác. Còn trong quan hệ dân sự thì"],["p","(1) là lựa chọn (điều kiện chọn luật) và (2) là pháp luật có mối liên hệ gắn bó mật thiết (Lex fori). 670 BLDS (chọn luật nước ngoài) or chọn luật VN BLTTDS (tập quán quốc tế trái với quy định cơ bản của pháp luật VN thì áp dụng PLVN)"],["p","VD: A ( VN) ly hôn B (Mỹ)"],["p","- Quan hệ dân sự có YTNN"],["p","+ A"],["p","+ B"],["p","=> Xung đột pháp luật"],["p","- Quan hệ TTDS có YTNN"],["p","+ NTHTT (TA, VKS)"],["p","+ NTGTT thuộc BA"],["p","=> Không có xung đột pháp luật"],["p","- Lex feri => Luật VN"],["p","- Điều 664.1 => hoặc luật VN => xung đột quy phạm luật áp dụng"],["p","-> Điều 127 LHNGD"]]},{"h":"1.5.4. Hệ thuộc luật nơi có tài sản","b":[["p","- Khái niệm: là nguyên tắc xác định luật áp dụng căn cứ vào nơi có tài sản đang hiện hữu"],["p","- Phạm vi áp dụng:"],["p","- Cơ sở pháp lý: 677, 678.1, 683.4, 680.2, 681.2.c BLDS, 127.3 Luật HNGD, 35 HĐTTTP V-N"],["p","+ Bất động sản thì luôn áp dụng pháp luật của nơi có bất động sản => theo nguyên tắc chủ quyền quốc gia, bảo vệ toàn vẹn lãnh thổ"],["p","*Ngoại lệ: Không áp dụng luật nơi có tài sản:"],["p","- Đối tượng quyền sở hữu trí tuệ (679)"],["p","- Tài sản của pháp nhân khi giải thể, phá sản (676.2)"],["p","- Tài sản thuộc sở hữu quốc gia"],["p","- Động sản đang trên đường vận chuyển (678.2)"],["p","- Tài sản là tàu bay, tàu biẻn (3 BLHH, 4 LHKDD)"]]},{"h":"1.5.5. Luật có mối quan hệ gắn bó mật thiết:","b":[["p","- Khái niệm: Là nguyên tắc xác định luật áp dụng căn cứ mối liên hệ gắn bó giữa quan hệ dân sự và quốc gia nhất định"],["p","- Phạm vi áp dụng:"],["p","+ Nước ngoài: Điều 4.1 quy tắc rome 2008; tài liệu diễn giải pháp luật thứ 2 của Luật Xung đột của Viện nghiên cứu pháp luật Hoa kỳ; Điều 2 Luật ADQHDSCYTNN Trung Quốc"],["p","+ Pháp luật VN: Điều 664.3, 672, 683 BLDS"],["p","*Điều 672:"],["p","- Nhiều quốc tịch:"],["p","+ QTVN => PLVN"],["p","+ Không có QTVN"],["p","QT + CT"],["p",""],["p","QT + Mối liên hệ gắn bó mật thiết"],["p",""],["p","- Không quốc tịch:"],["p","+ CT"],["p","+ MLHGBMT"],["p","=> mối quan hệ giữa cá nhân với quốc gia dựa trên cơ sở nhân thân và tài sản"],["p","*Điều 683:"],["p","- Chọn luật"],["p","- MLHGBMT"],["p","=> kết nối giữa hợp đồng được ký với 1 quốc gia cụ thể (nghĩa là xác định cho hợp đồng đó chứ không phải cá nhân nào)"],["p","*Điều 664.3:"],["p","- Điều ước quốc tế/ PLQG => Chọn => MLHGBMT"],["p","=> phạm vi áp dụng rộng hơn bao gồm quan hệ dân sự có yếu tố nước ngoài nói chung"]]},{"h":"2. Áp dụng pháp luật nước ngoài","b":[["p","Lý do, sự cần thiết của áp dụng PL nước ngoài Trường hợp áp dụng pháp luật nước ngoài (trả lời luôn trường hợp nào áp dụng PL Việt Nam) Bảo lưu trật tự công, dẫn chiếu (dẫn chiếu ngược và dẫn chiếu đến PL của nước thứ 3) => khái niệm, bản chất, nguyên nhân làm phát sinh dẫn chiếu và cách thức giải pháp Lẫn tránh pháp luật?"]]},{"h":"2.1. Sự cần thiết của việc áp dụng pháp luật nước ngoài","b":[]},{"h":"2.2. Trường hợp áp dụng pháp luật nước ngoài","b":[["p","- Theo dẫn chiếu của quy phạm xung đột thống nhất - Điều 664.1"],["p","*Điều 26, 42 + 39 HĐVN"],["p","+ Thừa kế: thẩm quyền (42) => bất động sản thì là tòa án nơi có tài sản, còn động sản là tòa án người để lại di sản là công dân; luật áp dụng (39)"],["p","- Theo dẫn chiếu của quy phạm xung đột thông thường - Điều 664.1"],["p","+ Phạm vi áp dụng dẫn chiếu đến quy phạm gì? Khoản 1 Điều 668"],["p","- Theo sự lựa chọn của các bên - Điều 664.2"],["p","- Pháp luật có mối liên hệ gắn bó mật thiết - Điều 664.3"]]},{"h":"2.3. Nguyên tắc áp dụng PL nước ngoài","b":[["p","- Chủ thể có nghĩa vụ xác định nội dung pháp luật nước ngoài - Điều 481 BLTTDS"],["p","- Giải thích pháp luật nước ngoài (667)"],["p","- Áp dụng pháp luật nước có nhiều hệ thống pháp luật - 669"],["p","- Phạm vi áp dụng pháp luật nước ngoài - 668.1,4"]]},{"h":"2.4. Dẫn chiếu ngược, dẫn chiếu pháp luật nước thứ 3","b":[["p","- Dẫn chiếu được hiểu là trường hợp mà quy phạm xung đột trong pháp luật của nước có tòa án tham chiếu đến việc áp dụng pháp luật nước ngoài và quy phạm trong pháp luật của nước ngoài tham chiếu ngược trở lại pháp của nước có tòa án hoặc pháp luật của nước thứ 3"],["p","- Có 2 cấp độ dẫn chiếu"],["p","- Nguyên nhân làm phát sinh dẫn chiếu:"]]},{"h":"2.5. Bảo lưu trật tự công","b":[["p","- Cơ sở lý luận: Chủ quyền quốc gia"],["p","- Cơ sở pháp lý: Điều 666, 670 BLDS, 5 LTM"],["p","- Nguyên tắc cơ bản của pháp luật VN"],["p","*Tình huống: 3 vấn đề pháp lý: (1) chủ thể giao kết hợp đồng"]]}]},{"t":"CÔNG NHẬN VÀ CHO THI HÀNH ĐỐI VỚI BẢN ÁN, QUYẾT ĐỊNH CỦA TÒA ÁN NƯỚC NGOÀI VÀ PHÁN QUYẾT CỦA TRỌNG TÀI NƯỚC NGOÀI","n":4,"g":[{"h":"I. KHÁI NIỆM, BẢN CHẤT CHẾ ĐỊNH CÔNG NHẬN VÀ CHO THI HÀNH","b":[["h","1. Khái niệm:"],["p","- Công nhận: thừa nhận tính đúng đắn của 1 vấn đề"],["p","- Cho thi hành: tiền đề cho việc thi hành - CQ có thẩm quyền đồng ý or không đồng ý về việc cho hay không cho bản án, quyết định của Tòa án nước ngoài or Phán quyết của Trọng tài nước ngoài được thực thi trên lãnh thổ Việt Nam."],["p","- Mối quan hệ:"],["p","+ Công nhận:"],["p","Công nhận => Được cho thi hành"],["p",""],["p","Không công nhận => Không thi hành (472.1.d BLTTDS => TAVN  từ chối giải quyết vụ việc đã được TANN giải quyết. Nếu không đồng ý vẫn giải quyết như bình thường) Không công nhận => Không có yêu cầu thi hành (thuận tình ly  hôn, không chia con or tài sản; quyết định không công nhận vợ chồng)"],["p","- Khái niệm: Công nhận và cho thi hành bản án, quyết định nước ngoài tại Việt Nam là việc Tòa án Việt Nam thừa nhận hiệu lực pháp luật đối với bản án, quyết định của Tòa án nước ngoài, phán quyết của Trọng tài nước ngoài và cho phép chúng được thi hành trên lãnh thổ Việt Nam (hiểu Dân sự theo nghĩa rộng nhất bao gồm nhiều lĩnh vực)"],["p","- Bản chất của công nhận và cho thi hành: Là một thủ tục tố tụng đặc biệt xem xét việc thừa nhận hiệu lực pháp luật đối với bản án, quyết định của TANN, phán quyết của TTNN như bản án, quyết định được tuyên bởi Tòa án quốc gia sở tại và không xét xử lại vụ việc dân sự đó."],["p","+ Yếu tố nước ngoài: (1) Vụ án dân sự; (2) Việc dân sự: công nhận và cho thi hành"],["h","2. Sự cần thiết của vấn đề công nhận - Cho thi hành:"],["p","a) Nguyên tắc ưu tiên ĐƯQT Việt Nam là thành viên"],["p","- CSPL: Điều 2.3 BLTTDS; 423.1.a, 424.1.a"],["p","- Công ước NewYork 1958 về CN-CTH QĐ của TTNN; HĐTTTP..., 664, 665 BLDS"],["p","VD: TAVN CN-CTH chia làm 2 trường hợp:"],["p","- Quốc gia có hiệp định (Nga) => HĐTTTP V-N => ĐK CN-CTH => Ưu tiên áp dụng ĐƯQT, nếu không có mới áp dụng PLQG"],["p","- Quốc gia không có hiệp định (Sing, Malay, Nhật, Anh,...) => ĐK CN-CTH"],["p","=> Theo nguyên tắc có đi có lại => ĐK áp dụng PLQGVN"],["p","- Có 2 nguồn luật xét công nhận và cho thi hành: Điều ước quốc tế và BLTTDS"],["p","- TAVN không xét lại mà xét Điều kiện công nhận và cho thi hành:"],["p","+ Đối tượng nộp đơn"],["p","+ Chủ thể nộp đơn"],["p","+ Thời hiệu nộp đơn"],["p","+ Hồ sơ đơn yêu cầu (đầy đủ thành phần) => gửi trả bổ sung => không bổ sung thì đình chỉ"],["p","- Điều 439 và 459 => nếu bản án, quyết định của tòa nước ngoài rơi vào trường hợp không công nhận thì TAVN ra quyết định không công nhận, còn lại thì ra quyết định công nhận"],["p","- Các điều kiện trên thì phải được quy định trong điều ước quốc tế mà VN là thành viên, nếu không quy định thì áp dụng PLQG (thời hiệu nộp đơn)"],["p","b) Nguyên tắc có đi có lại:"],["p","- CSPL: Điều 423.1.b, 424.1.b BLTTDS"],["p","- Chịu sự chi phối của nguyên tắc thiện chí quốc gia"],["p","- Nguyên tắc chủ quyền quốc gia: Khi Tòa án giải quyết thfi bản án được giới hạn bởi không gian lãnh thổ chứ không đương nhiên có hiệu lực tại nước khác (phải qua cơ chế công nhận và cho thi hành"],["p","- Nguyên tắc thiện chí giữa các quốc gia: công nhận lẫn nhau"],["p","- 431.1.a: đương nhiên được công nhận => Điều kiện:"],["p","+ Bản án được quy định tại ĐƯQT mà VN là thành viên: 9 quốc gia:"],["p","bungari, belarus, cadactan, nga (51), mông cổ, hungari"],["p","+ Bản án không có yêu cầu thi hành (thuận tình ly hôn, yêu cầu tuyên bố 1 người đã chết/mất tích, xác định cha mẹ cho con,...) => đương nhiên. Bản án có nghĩa vụ thi hành thì KHÔNG rơi vào trường hợp đương nhiên. Phán quyết của trọng tài THÌ THUỘC TRƯỜNG HỢP KHÔNG CÓ YÊU CẦU THI HÀNH (vì 1 trong 2 bên là thương nhân thì đương nhiên có nghĩa vụ thi hành, mà có nghĩa vụ thi hành thì không đương nhiên công nhận)"],["p","- 431.2:"],["p","+ Đối tượng: 9 quốc gia về đương nhiên công nhận và cho thi hành"],["p","c) Nguyên tắc BA, QĐ NN chỉ có hiệu lực tại Việt Nam sau khi QĐ CN-CTH của TAVN có hiệu lực"],["p","- CSPL: Điều 427.3 BLTTDS"],["p","d) Nguyên tắc không xét xử lại vụ việc đã được giải quyết bởi TANN, TTNN"],["p","- CSPL: Điều 438.4, 458.4 BLTTDS"]]},{"h":"II. CÔNG NHẬN VÀ CHO THI HÀNH BẢN ÁN, QUYẾT ĐỊNH CỦA TANN TẠI VIỆT NAM","b":[["h","1. Các loại bản án, quyết định của TANN được xem xét CN-CTH tại VN"],["p","- BA, QĐ của TANN (423.1)"],["p","- QĐ của cơ quan khác có thẩm quyền của nước ngoài (423.2)"],["p","- Điều 423:"],["p","+ BA, QD về dân sự, hôn nhân gia đình, kinh doanh, thương mại, lao động, QD về tài sản (BS,QD hình sự, hành chính) của TANN => Quy định tại ĐƯQT (V-N tại điều 52)"],["p","+ BA, QD về dân sự, hôn nhân gia đình, kinh doanh, thương mại, lao động, QD về tài sản (BS,QD hình sự, hành chính) của TANN => Nguyên tắc có đi có lại"],["p","+ BA, QD dân sự khác => Theo PLVN (Điều 125 LHNGD)"],["p","+ QD về nhân thân, hôn nhân gia đình => Cơ quan có thẩm quyền khác của nước ngoài => (1) ĐƯQT, (2) Có đi có lại; (3) PLVN"],["h","2. Bản án quyết định TANN đương nhiên được công nhận tại Việt Nam"],["p","- CSPL: Điều 431 BLTTDS"],["p","- 431.1:"],["p","+ Điều kiện: thuộc trường hợp đương nhiên được công nhận => Điều 51 V- N:"],["p","Vụ kiện dân sự không mang tính chất tài sản  Vụ kiện hôn nhân gia đình không mang tính chất tài sản => không  cần phải có một thủ tục tố tụng đặc biệt nào => đương nhiên được công nhận (26 V-N): (1) Cùng quốc tịch khác cư trú => thẩm quyền thuộc Tòa án các bên có quốc tịch; (2) cùng quốc tịch bên này khác cư trú => tòa án cả 2; (3) khác quốc tịch cùng cư trú => tòa cư trú; (4) khác quốc tịch khác cư trú => cả 2 nơi"],["p","+ Trong thời hạn quy định tại 447"],["p","*Tại sao pháp luật Việt Nam có quy định về các trường hợp đương nhiên CN- CTH đối với bản án, quyết định dân sự của TANN"],["p","*Người Việt Nam ở nước ngoài:"],["p","- Xác định có yếu tố nước ngoài: điểm b,c khoản 2 Điều 663"],["p","- Xác định thẩm quyền: vụ án dân sự có liên quan đến tài sản trên lãnh thổ Việt Nam"],["p","- Xác định luật áp dụng: 664 => “hoặc luật Việt Nam” nghĩa là nguyên tắc xác định luật áp dụng, cụ thể là quan hệ dân sự có yếu tố nước ngoài. Thừa kế => 680, 681."],["p","- Bị đơn có nơi cư trú tại Việt Nam, có yêu cầu Tòa án Việt Nam giải quyết => TAVN có thẩm quyền đối với yêu cầu này. (472 BLTTDS)"],["p","+ Bị đơn phản tố rằng không công nhận tính hợp pháp của di chúc"],["p","=> Phải xác định tư cách tố tụng => xác định yếu tố bị đơn"],["p","*Tình huống 2:"],["p","- Thẩm quyền chung: điểm b khoản 1 Điều 469. Tòa án phải tôn trọng từ chối thẩm quyền vì đã thỏa thuận chọn Trọng tài quốc tế Việt Nam nhưng tên quy định trong hợp đồng giữa 2 công ty là sai nên Trọng tài không giải quyết mà do TAND tỉnh Bình Dương thụ lý"],["h","3. Chủ thể yêu cầu về công nhận và cho thi hành bản án, quyết định của tòa án nước ngoài"],["p","- Điều 425 BLTTDS"],["p","Chủ thể/ Nơi nhận đơn/Thời hiệu:"],["p","- Người được thi hành/người đại diện => CN-CTH (chỉ được quyền nộp đơn nếu vào thời điểm nộp đơn xác định nơi cư trú, trụ sở, nơi có tài sản của người phải thi hành, không xác định được thì Tòa án không thụ lý) => Tòa án/Bộ tư pháp (chỉ có 6 điều ước quy định Bộ Tư pháp là nơi nhận đơn => 3 năm."],["p","- Người phải thi hành/người đại diện => Không công nhận (điều kiện nơi cư trú, trụ sở, nơi có tài sản không đặt ra) => Tòa án => 3 năm (thời điểm bắt đầu tính là theo quy định của pháp luật nước ngoài)"],["p","- Đương sự/NCQLILQ/QĐ => Không công nhận/không yc thi hành => Tòa án/Bộ tư pháp => 6 tháng"],["p","- Đối với yêu cầu công nhận và cho thi hành bản án, quyết định dân sự của Tòa án nước ngoài: Điều 432 BLTTDS"],["p","- Khoản 1 Điều 425"],["p","- Trường hợp tòa án không xác định được địa chỉ hoặc tài sản của người phải thi hành thì giải quyết như thế nào? => thì đình chỉ"],["p","- Đối với yêu cầu không công nhận bản án, quyết định dân sự của Tòa án nước ngoài không có yêu cầu thi hành tại Việt Nam: Điều 447 BLTTDS"],["p","- Đối với yêu cầu công nhận và cho thi hành tại Việt Nam phán quyết của Trọng tài nước ngoài: Điều 451 BLTTDS"],["p","- Thành phần hồ sơ: Điều 433, 434"],["p","+ Đơn yêu cầu"],["p","+ Hồ sơ đính kèm đơn yêu cầu:"],["p","Trường hợp 1: Đối với bản án CN - CTH căn cứ điều ước quốc tế  mà Việt Nam là thành viên Trường hợp 2: Đối với bản án CN-CTH theo nguyên tắc có đi có  lại"],["p","- Thời hiệu yêu cầu công nhận cho thi hành:"],["p","+ Trong 3 năm thì thời gian không tính vào thời hiệu: khoản 2 Điều 432"],["p","- Trường hợp từ chối công nhận, cho thi hành đối với bản án, quyết định của tòa án nước ngoài"],["p","+ CSPL: Điều 439"],["p","+ Yêu cầu: Phân tích, làm tõ quy định về các trường hợp từ chối công nhận bản án, quyết định của Tòa án nước ngoài"],["p","+ Không rơi vào 439 thì ra quyết định công nhận"],["p","- Điều 439:"],["p","+ Không đáp ứng các điều kiện về công nhận cho thi hành => 439.1=> quy định tại điều ước quốc tế => Việt - Pháp (21) và Việt Nam - Hungary (55), Việt"],["p","- Nga (53), Việt Nam - Tiệp khắc (47), Việt - Cam (22), Việt - Mông cổ (47), Việt - Trung (17)"],["p","+ Bản án quyết định chưa có hiệu lực pháp luật (theo pháp luật của nước nơi tuyên bản án chứ không phải nơi nước tiếp nhận yêu cầu) => Ngoại lệ"],["p","+ Người phải thi hành hoặc người đại diện không có mặt tại phiên tòa"],["p","+ Tòa án nước ra phán quyết không có thẩm quyền theo 440 => cho mục đích công nhận và cho thi hành chứ không nhằm xác định thẩm quyền xét xử của tòa nước ngoài Vấn đề thẩm quyền gián tiếp: thẩm quyền của tòa nước ngoài  thông qua quy định của pháp luật nước sở tại => thông qua nguyên tắc gương soi (440.1 - không thuộc thẩm quyền riêng biệt) => không thuộc thẩm quyền riêng của VN và thuộc thẩm quyền giải quyết của nước ngoài thì VN mới công nhận và cho thi hành. Thẩm quyền chung và VN thụ lý trước => Việt Nam có thẩm quyền và NN không có thẩm quyền thụ lý. NN thụ lý trước thì VN từ chối thẩm quyền => nguyên tắc thiện chí giữa các quốc gia. (440.2.c)."],["h","472.1.d = 440.2.c"],["p","Thẩm quyền trực tiếp: 1 tòa án của 1 quốc gia có thẩm quyền đối  với vụ việc hay không Có phải tất cả các bản án được công nhận là đều có hiệu lực pháp luật không?"],["p","433, 434, 53 Việt - Nga"],["p","Giả sử xét đơn trong trường hợp đang trong quá trình tố tụng ở nước ngoài thì nước tiếp nhận sẽ xét như thế nào?"]]},{"h":"III. CÔNG NHẬN VÀ CHO THI HÀNH PHÁN QUYẾT CỦA TTNN TẠI VIỆT NAM","b":[["p","- Điều kiện công nhận và cho thi hành?"],["p","- Xác định, trình bày trình tự thủ tục xét đơn yêu cầu công nhận cho thi hành phán quyết"],["p","*BA,QĐ của TANN: Điều 431 => đương nhiên CN-CTH (không cần thông qua thủ tục tố tụng đặc biệt nào, nghĩa là không cần nộp đơn nhưng vẫn được công nhận)"],["p","+ CN - CTH"],["p","+ Không CN"],["p","+ Không CN đối với bản án không có yêu cầu thi hành"],["p","*Phán quyết của TTNN: Không có trường hợp đương nhiên công nhận. Phải là tranh chấp trong lĩnh vực thương mại, có ít nhất 1 bên là thương nhân => phát sinh nghĩa vụ của 1 bên đối với bên còn lại"],["p","+ CN - CTH => Ra 1 trong 2 quyết định: (1) công nhận; (2) không công nhận"],["p","+ Gồm người phải thi hành và người được thi hành (người nộp đơn yêu cầu CN - CTH)"],["h","1. Công nhận và cho thi hành phán quyết TTNN theo Công ước New York 1958 (Điều 5, Điều 459 BLTTDS)"],["h","1.1. Đối tượng xét đơn CN - CTH theo công ước:"],["p","- Cơ sở pháp lý:"],["p","+ Điều 1 CƯ NY 1958"],["p","Được ban hành tại quốc gia khác với quốc gia được yêu cầu công  nhận, cho thi hành (quốc gia theo nghĩa rộng - là thành viên or chưa là thành viên) QĐTT không được coi là quyết định trong nước tại quốc gia được  yêu cầu công nhận, cho thi hành Phạm vi áp dụng công ước: (1) QDTT (thành viên), (2) QDTT  (không là thành viên) - chỉ cần công nhận trên cơ sở có đi có lại;"],["p","(3) quan hệ thương mại; (4) quan hệ khác"],["p","Bảo lưu công ước: Việt Nam (Điều 2 QĐ 453/1995/CTH) =>  QĐTT (thành viên) và Lĩnh vực thương mại (ngoài thương mại sẽ không CN - CTH theo công ước này)"],["p","+ Điều 5 CƯ NY 1958:"],["p",""],["h","2. Công nhận và cho thi hành phán quyết TTNN theo pháp luật Việt Nam"],["h","2.1. Khái niệm:"],["p","- Trọng tài nước ngoài: 3.11 Luật TTTM 2010"],["p","- Quyết định của TTNN: 3.9 Luật TTTM 2010"],["p","- Phán quyết trọng tài:"],["p","Kết luận"],["p","- Phán quyết TTNN:"],["p","+ Phán quyết"]]}]},{"t":"QUYỀN SỞ HỮU TRONG TƯ PHÁP QUỐC TẾ XUNG ĐỘT PHÁP LUẬT VỀ QUYỀN SỞ HỮU CÓ YẾU TỐ NƯỚC NGOÀI","n":5,"g":[{"h":"","b":[["p","- Vai trò của hệ thuộc luật nơi có tài sản?"],["p","XÁC ĐỊNH THẨM QUYỀN CỦA TAVN ĐỐI VỚI TRANH CHẤP VỀ QUYỀN SỞ HỮU CÓ YTNN VAI TRÒ CỦA HỆ THUỘC LUẬT NƠI CÓ TÀI SẢN TRƯỜNG HỢP NGOẠI LỆ KHÔNG ÁP DỤNG HỆ THUỘC LUẬT NƠI CÓ TÀI SẢN"],["p","- Vì sao không áp dụng hệ thuộc luật nơi có tài sản (quyền sở hữu trí tuệ)?"],["p","nhằm đảm bảo vấn đề gì"],["p","- Không áp dụng luật nơi có tài sản thì áp dụng luật nào?"],["p","- Vì sao áp dụng hệ thuộc luật này (nước có yêu cầu quyền bảo hộ) mà không phải là luật khác?"],["p","QSH CỦA NGƯỜI NƯỚC NGOÀI TẠI VIỆT NAM"]]},{"h":"I. KHÁI QUÁT VỀ QUYỀN SỞ HỮU TRONG TƯ PHÁP QUỐC TẾ","b":[["h","1. Khái niệm quyền sở hữu trong TPQT"],["p","- Quyền sở hữu TPQT: Quyền sở hữu và có YTNN"],["p","- Khoản 2 Điều 663: QHDS có YTNN"],["p","+ Chủ thể: cá nhân, pháp nhân"],["p","+ Đối tượng: tài sản"],["p","+ Sự kiện PL: ở nước ngoài"],["p","Trình bày ý nghĩa của việc xác định yếu tố nước ngoài:"],["p","+ Phân biệt đối tượng điều chỉnh: Không có YTNN thì là luật dân sự"],["p","+ Xác định thẩm quyền của tòa án quốc gia đối với vụ việc quyền sở hữu có YTNN: có hay không có thẩm quyền. Không có YTNN thì đương nhiên là Tòa quốc gia."],["p","+ Xác định pháp luật áp dụng đối với QSH có YTNN: có thể có 2 luật có thể áp dụng nên phải xác định luật nào áp dụng Phân biệt phạm vi điều chỉnh quyền sở hữu trong tư pháp quốc tế và luật dân sự (về chế định sở hữu)"],["p","- Thẩm quyền của tòa án Việt Nam đối với vụ việc quyền sở hữu có YTNN"],["p","+ CSPL: ĐƯQT mà VN là thành viên; BLTTDS"],["p","+ Thẩm quyền riêng biệt: 470.1.a"],["p","+ Thẩm quyền chung: điểm a,b,c,đ,e khoản 1 Điều 469"],["h","2. Giải quyết xung đột pháp luật về quyền sở hữu"],["h","2.1. Xung đột pháp luật về quyền sở hữu"],["p","- Khái niệm:"],["p","- Nguyên nhân phát sinh"],["p","- Các vấn đề phát sinh xung đột pháp luật"],["p","- Phương pháp giải quyết"],["p","- Nguồn luật"],["h","2.2. Giải quyết xung đột pháp luật:"],["p","- Quyền sở hữu:"],["p","+ Vai trò của luật nơi có tài sản"],["p","+ Trường hợp không áp dụng Luật nơi có tài sản"]]}]}],"cp":[{"t":"Mở đầu","n":0,"g":[{"h":"","b":[["p","CÔNG PHÁP QUỐC TẾ"],["p","Công pháp quốc tế: khoa học pháp lý, nghiên cứu pháp luật, có tên gọi chung là Luật quốc tế. Hệ thống pháp luật độc lập song song với các quốc gia nói chung và VN nói riêng."],["p","Có 6 chương( C1: kq luật quốc tế( vấn đề chung, khác j so các nước khác); C2: nguồn luật quốc tế; C3: vấn đề về dân cư, C4: lãnh thổ, biên giới các quốc gia; C5: ngoại giao; C6: tranh chấp; C7: giải quyết tranh chấp) Tài liệu: giáo trình công pháp quốc tế( quyển 1: từ chương 1-5, quyển 2: từ chương 6-7). Giáo trình trường ĐH luật HN, Ngoại giao, ĐH luật đh quốc gia HN. Văn bản quy phạm pháp luật công pháp quốc tế. Hiến chương LHQ 1945, tuyên bố năm 1970 của đại hội đồng LHQ về các nguyên tắc cơ bản được sử dụng cho các quốc gia, Công ước viên 1969 về điều ước quốc tế, luật điều ước quốc tế 2016, luật thỏa thuận quốc tế 2020, luật quốc tịch 2008, luật quốc tịch sửa đổi bổ sung 2014, công ước lhq về luật biển 1982( tải toàn văn và phụ lục 5-8- thành lập nên thiết chế tài phán thành lập nên luật biển), luật biển VN 2012, công ước viên 1961 về ngoại giao, công ước viên 1963 về lãnh sự, pháp lệnh cấp hàm ngoại giao 1995, luật cơ quan đại diện của nước CHXHCNVN ở nước ngoài 2009, quy chế tòa án công lý quốc tế 1945 KT: có 3-4 cột. Cột 1: thuyết trình, cột 2: thi, cột 3: cộng, cột 4: kt cá nhân  Thuyết trình: soạn thảo văn bản-word (40%); ppt (30%) (10 slide đổ lại); thuyết trình (30) (10p), phản biện 6 ngày cuối của môn sẽ thuyết trình, 12 đề 24 nhóm, tối thiểu 3 câu hỏi pháp lý ( quyền và nghĩa vụ pháp lý các bên trong vụ việc)  PPT: thuyết trình vụ việc tranh chấp, slide đầu gt vụ tranh chấp, quan điểm của nguyên đơn, cơ quan giải quyết tranh chấp  Thi tự luận đề mở 90p- 3 phần (yêu cầu: nhận diện vấn đề pháp lý quốc tế và giải quyết trên cơ sở lý luận và pháp lý quốc tế; tình huống: dài 2-3- các thông tin sự kiện về luật quốc tế (50% trong đề tài thuyết trình). Cách trình bày: trình bày rõ ràng."],["p","Những bạn giải quyết được nhiệm vụ không phải của mình được điểm cộng 15/2/2023"]]}]},{"t":"KHÁI QUÁT VỀ LUẬT QUỐC TẾ","n":1,"g":[{"h":"I. Khái niệm luật quốc tế","b":[["p","- Luật quốc tế là một hệ thống pháp luật bao gồm các nguyên tắc được các chủ thể của luật quốc tế bình đẳng tình nguyện hình thành nên nhằm mục đích điều chỉnh các mối qhe xã hội trên nhiều lĩnh vực khác nhau (quan hệ xã hội) giữa các chủ thể của quốc tế với nhau."],["p","- Chủ thể luật quốc tế bao gồm các quốc gia (VN, TQ...), tổ chức quốc tế liên chính phủ (NATO..), các thực thể đặc biệt (vùng lãnh thổ có quy chế pháp lý đặc biệt, các dân tộc đang đấu tranh giành quyền tự quyết(Balenti)"],["p","- Hệ thống pháp luật bao gồm nhiều ngành luật, bao gồm chế định pháp luật, thành tố nhỏ nhất là các quy phạm pháp luật"],["p","- Luật quốc tế là 1 hệ thống pháp luật, ra đời, độc lập, song song cùng tồn tại với hệ thống pháp luật của các quốc gia. Mục đích nhằm điều chỉnh quan hệ XH giữa các chủ thể của luật quốc tế trên nhiều lĩnh vực"],["p","- Tuy nhiên LQG và LQT là 2 hệ thống riêng biệt nhau và khác nhau. Mối quan hệ giữa LQT và LQG là mỗi quan hệ tác động qua lại lẫn nhau. LQG- cơ sở để thực thi PLQT. Buộc LQG phải vận động theo xu hướng phát triển chung của LQT (vd: vấn đề bảo vệ môi trường)"],["p","- LQT ra đời khi có sự xuất hiện của các quốc gia và các mối quan hệ có nhu cầu điều chỉnh giữa các quốc gia lại với nhau."],["p","- LQT hiện đại ra đời 1945 vì có sự xuất hiện của Hiến chương LHQ-vb hình thành khung pháp lý mới, văn minh, tiến bộ và hiện đại, hướng đến duy trì an ninh và hòa bình, bảo vệ phát triển quyền con người."]]},{"h":"II. Đặc trưng","b":[["p","– 4 đặc trưng: Chủ thể, đối tượng điều chỉnh, trình tự xây dựng pháp luật, thực thi pháp luật"],["p","1. Chủ thể: những thực thể, những dạng tồn tại ngoài thực tại khách quan mà con người có thể thấy được, độc lập tham gia vào các quan hệ quốc tế có đầy đủ năng lực để hưởng quyền cũng như chịu nghĩa vụ và trách nhiệm pháp lý quốc tễ. (cá nhân, nhà nước, pháp nhân)"],["p","– Để được xem là quốc gia thực thể đó phải thỏa hiệp những đk sau: dân cư phải ổn định (chỉnh phủ phải kiểm soát được toàn bộ hoặc phần lớn dân cư), lãnh thổ phải xác định (chính phủ phải kiểm soát được toàn bộ hoặc phần lớn lãnh thổ), chính phủ hữu hiệu hay chính phủ thực sự (phải mang quyền lực nhà nước, kiểm soát xã hội bằng quyền lực, dùng các biện pháp cưỡng chế để mn tuân theo) và có khả năng vào quan hệ quốc tế 1 cách độc lập. Trong luật quốc tế hiện đại khi các thực thể đủ đk theo điều của công pháp Monte thì họ được công nhận là một quốc gia mà không cần phải có sự công nhận của các chủ thể khác CÂU HỎI: Vì sao quốc gia là chủ thể quan trọng nhất của luật quốc tế? Quốc gia là chủ thể hình thành, quốc gia là chủ thể thực thi, thi hành luật pháp quốc và hoàn thiện luật pháp quốc tế"],["p","- Tổ chức quốc tế liên chính phủ: là thực thể được liên kết bởi các chủ thể của luật quốc tế trên cơ sở 1 điều ước luật quốc tế có đẩy đủ quyền năng và năng lực tham gia vào quan hệ quốc tế, có cơ cấu tổ chức tôn chỉ, mục tiêu cụ thể, chặt chẽ. Thành viên của tổ chức quốc tế liên chính phủ không bao gồm các quốc gia mà có thể bao gồm các chủ thể của luật quốc tế. Phi chính phủ khác liên chính phủ. Tổ chức quốc tế phi chính phủ sẽ bao gồm cá nhân và tổ chức dân sự CÂU HỎI: Vì sao nói tổ chức liên chính phủ là phái sinh và hạn chế?"],["p","LCP chủ thể hạn chế. Không tự động sinh ra, do người khác sinh ra."],["p","Những người có quyền lực sẽ quyết định sẽ là người quyết định cơ cấu, cơ quan thành viên của các tổ chức đó, tôn chỉ mục tiêu do người khác áp định. Không thực hiện quyền năng vượt ra khỏi cái tổ chức họ đang nắm quyền, được sắp đặt hết trong hiến chương 2015."],["p","Do người khác thành lập, đều cho chủ thể khác quyết định nên họ không thể vượt ra khỏi những điều mà thành viên sắp đặt quyết định."],["p","– Dân tộc đang đấu tranh giành quyền tự quyết:"],["p","⤷ Có 2 đk:"],["p"," Dân tộc trong luật quốc tế (đk cần): được hiểu là toàn bộ cộng đồng người cùng cư trú sinh sống gắn bó vs nhau trên 1 phạm vi lãnh thổ hợp thành khái niệm quốc gia-> dân cư trong luật quốc tế. (VD:"],["p","trước khi VN bị xâm lược là 1 quốc gia nhưng khi bị xâm lược không còn là một quốc gia nữa, nhưng những người dân sinh sống trên quốc gia trước đây (trước khi bị xâm lược) vẫn là 1)  Dân tộc đó đang chịu thuộc địa hoặc phụ thuộc (lệ thuộc) hay chịu chế độ phân biệt chủng tộc. (VD: VN thời pháp gọi thuộc địa- bị biến thành phần lãnh thổ Đk của Pháp, thời Mỹ VN là phụ thuộc- vẫn tồn tại đủ nhưng bị kiểm soát)  Thành lập được lực lượng lãnh đạo phong trào đấu tranh: Trong đối nội phải có sự thống nhất trong phong trào đấu tranh. Cần sự lãnh đạo về đối nội và ngoại giao về đối ngoại CÂU HỎI: Chủ thể luật quốc tế khác gì với chủ luật quốc gia? Khác ở chỗ về thành phần cá nhân và pháp nhân. Dù khi tham gia sẽ có các cá nhân, pháp nhân, tổ chức nhưng nếu không có các tổ chức đó thì không có tư cách, đầy đủ năng lực tham gia vào chủ thể luật quốc tế."],["p","2. Đối tượng điều chỉnh: điều chỉnh các mối quan hệ trong xã hội. Xuất hiện những quan hệ về nhân thân và tài sản. Điều chỉnh các mối quan hệ cá nhân trong đời sống xã hội: kinh tế- chính trị, xã hội… Sự khác nhau giữa đối tượng điều chỉnh giữa luật quốc tế khác với luật quốc gia:"],["p","3. Đặc trưng về xây dựng: pháp luật quốc gia do nhà nước ban hành nhưng không phải lúc nào cũng ban hành mà còn thừa nhận tập quán. Luật quốc tế được hình thành bằng cách nên buộc các QG, TC, TTĐB bình đẳng tự nguyện giữa các chủ thể của luật quốc tế. Luật quốc tế không có cơ quan lập pháp như pháp luật quốc gia. Mọi chủ thể LQT đều bình đẳng vs nhau nên mọi quy phạm pháp luật họ hình thành nên đều không giống quy phạm pháp lý của luật quốc gia."],["p","Luật quốc gia đều có sự phân chia trong bộ luật pháp lý vì cơ quan hình thành nên các quy phạm pháp luật này đều có sự phân chia về quyền lực thứ bậc nhà nước. Còn các vppl luật quốc tế không phân chia vì các chủ thể ngang bằng nhau trong địa vị pháp lý Trong hệ thống pháp luật VN sắp xếp: HP; Luật= Nghị Quyết; Pháp luật, Nghị quyết; Nghị định; Thông tư."],["p","4. Thực thi pháp luật: LQT không có quan hành pháp phủ và tư pháp (VKS...) như pháp luật quốc gia. Việc đảm bảo thi hành pháp luật trên cơ sở bình đẳng tự nguyện giữa các chủ thể của Luật Quốc tế. Lưu ý, trong LQT có những lực lượng hòa bình. Nếu các quốc gia không thi hành theo những phán quyến mà của 17 người trong IJC đề ra thì IJC không có thẩm quyền kiện trừ trường hợp mọi người trogn quốc gia đó đồng ý. 1 bên không thi hành thì IJC cũng không là gì được các quốc gia."],["p","CÂU HỎI: Vậy luật quốc tế được thành lập ra để làm j? LQT như sợi dậy để kìm hãm các cường quốc không xâm phạm, gây chiến tranh với các nước nhỏ (VN, Lào, Camphuchia…). Tồn tại hình thành nên những nguyên tắc để ràng buộc những “ông lớn” (Mỹ, Nhật, TQ…)"]]},{"h":"III. Các nguyên tắc cơ bản của luật quốc tế","b":[["p","– Nguồn gốc: 7 nguyên tắc cơ bản của LQT bị ảnh hưởng bởi Liên Xô, các hiến chương LHQ được xem như bắt buộc. Được ghi nhận đầu trong hiến chương LHQ 1945."],["p","- Khái niệm: Các nguyên tắc cơ bản của LQT là những tư tưởng chính trị (là sản phẩm đấu tranh giữa 2 cực; những người đi đàm phán đều mang tính chất chính trị, kìm chế thỏa mãn nhau về lợi ích chính trị) mang tính chất chỉ đạo bao trùm và có tính bắt buộc chung (jus corgens)."],["h","1. Nguyên tắc 1: Bình đẳng chủ quyền giữa các quốc gia (muốn duy trì hòa bình- an ninh)"],["h","2. NT 2: Các dân tộc bình đẳng và có quyền tự quyết"],["h","3. NT 3: Không can thiệp vào việc nội bộ"],["h","4. NT 4: Không sử dụng vũ lực và đe dọa sử dụng vũ lực trong quan hệ quốc tế (giải quyết tranh chấp)"],["h","5. NT 5: Hòa bình giải quyết các tranh chấp quốc tế (ngồi lại được với nhau)"],["h","6. NT 6: Các quốc gia có nghĩa vụ hợp tác với nhau (giữ được chữ tín)"],["p","7. NT7: Tận tâm thiện chí thực hiện các cam kết quốc tế (pacta sunt servanda) STT Nguyên Cơ sở pháp lý Nội dung Ngoại lệ tắc 1 Bình đẳng -Khoản 1 điều 2 Lhq -Chủ quyền quốc gia là -Quốc gia tự hạn chủ quyền 1945 quyền định đoạt tối chế chủ quyền giữa các -Tuyên bố 1970 của cao của quốc gia về -Khi quốc gia bị quốc gia đại Hội đồng LHQ đối nối và đối ngoại trừng phạt vì vi phạm quốc tế 2 Nguyên - Khoản 2 điều 1 - Phải được xem là dân Không có ngoại lệ tắc các Hiến chương LHQ tộc trong luật quốc tế dân tộc 1945 (xem thêm tuyên bố bình đẳng - Tuyên bố 1970 1970) và có - Nghị quyết 1514 - Thỏa mãn đk dân tộc quyền tự năm 1960 của Đại đấu tranh giành quyết hội đồng LHQ quyền tự quyền 3 Không can - Khoản 7 điều 2 của - Những công việc thiệp vào Hiến chương LHQ thuộc phạm trù công việc 1945 những công việc quốc nội bộ của - Tuyên bố 1970 gia. (VD: việc thỏa quốc gia thuận giữa Mỹ và khác Triều Tiên tại HN có đc xem là công việc nội bộ? Đây là công việc nội bộ. Những công việc nội bộ thuộc chủ quyền)"],["p","- Can thiệp vào công"],["p","việc nội bộ 1 cách"],["p","trực tiếp: chủ thể"],["p","nhân danh chính"],["p","mình tự thực hiện"],["p","thông qua các biện"],["p","pháp khác nhau. VD:"],["p","quân sự, chính trị,"],["p","kinh tế, văn hóa,"],["p","ngoại giao… để can"],["p","thiệp vào công việc"],["p","nội bộ của các quốc"],["p","gia khác. Can thiệp"],["p","gián tiếp: tương tư"],["p","như trên nhưng thông"],["p","qua chủ thể thứ 3"],["p","(LQT) hoặc/ và tài trợ,"],["p","kích động, đào tạo,"],["p","xúi giục các phần tử,"],["p","lực lượng sở tại."],["p","- 2 ngoại lệ:"],["h","1. Hành động can"],["p","thiệp của Hội đồng"],["p","bảo an liên hợp"],["p","quốc theo chương"],["p","7 của Hiến chương"],["p","(39-42)"],["h","2. Thỏa thuận can"],["p","thiệp nội bộ chỉ"],["p","đúng với 2 đk sau:"],["p","đugns với ngyên"],["p","tắc cơ bản luật"],["p","pháp quốc tế ;hỏa"],["p","thuận đó phải phù"],["p","hợp vs quốc gia."],["p","4 Không sử - Điều 2.4 Hiến – Sử dụng vũ lực TRỰC – Hội đồng Bảo dụng vũ chương LHQ 1945 TIẾP chủ thể tự thực An LHQ theo lực và đe - Tuyên bố 1970 hiện hoặc tự nhân điều 42 của dọa sử - Nghị quyết số 3314 danh chính mình Hiến chương."],["p","dụng vũ ngày 12/4/1974 của thông qua các biện VD: Savien và lực trong Đại hồi đồng LHQ pháp khác nhau. VD: Cosovo… (bị quan hệ quân sự, chính trị, tranh cãi về từ quốc tế kinh tế, ngoại giao, thỏa đáng và văn hóa… để xâm chính đáng phạm đến động lập trong điều 42.) chủ quyền, thống Trong hình sự, là nhất và toàn vẹn lãnh có từ phòng vệ thổ của chủ thể khác. chính đáng. VD về"],["p","– Sử dụng vũ lưc GIÁN quốc tế: Quốc A và"],["p","TIẾP như trên nhưng B. A tấn công B tại"],["p","thông qua chủ thể biên giới và gửi tối"],["p","thứ 3: sử dụng lính hậu thư cho B,"],["p","đánh thuê, thậm chí trước khi A tấn"],["p","kích động các thành công, B đã diệt trừ"],["p","tử kích động… đe dọa A (th1); cũng là 2"],["p","sử dụng vuux lực là ông đó, A đưa"],["p","kết quả của nó có khả quân tấn công B"],["p","năng rất cao sẽ dẫn luôn ko tuyên bố"],["p","đến việc sử dụng vũ nữa. B phản"],["p","lực. VD: gửi tối hậu công(th2)."],["p","thư, tập trung quân B chạy vào chùa"],["p","lực bất thường dọc và người dân trốn"],["p","biên giới, tập trận trái vào đó đã bị A giết phép dọc bên giới sạch, sau một hồi B đã tiêu diệt hết đám khủng bố của A. (th3)- phòng ngừa, khả năng bị tấn công rõ ràng hơn so với 2 th còn lại."],["p","– Dành quyền tự"],["p","quyết giải"],["p","phóng dân tộc"],["p","đang đấu tranh"],["p","giành quyền tự"],["p","quyết"],["p","– Quyền tự về"],["p","hợp pháp theo"],["p","đ.51 Hiến"],["p","chương LHQ"],["p","năm 1945"],["p","5 Hòa bình - Đ.33 HCLHQ - Tranh chấp qte là Không có ngoại giải quyết 1945 những mâu thuẫn lệ, không có biện các tranh - Điều 2.3 HCLHQ xung đột về lợi ích pháp hòa bình chấp quốc 1945 giữa các chủ thể này thì tìm cái tế - Tuyên bố 1970 của luật quốc tế khác và ko được các chủ thể phải vi phạm các giải quyết bằng nguyên tắc khác biện pháp hòa bình (Đ.33): điều tra, đàm phán, ngoại giao"],["p","- Biện pháp hòa"],["p","bình giải quyết:"],["p","điều 33 chương 6"],["p","- Ndung của nguyên"],["p","tắc: Điều 2.3"],["p","HCLHQ 1945 và"],["p","Tuyên bố 1970"],["p","6 Các quốc Không có ngoại lệ"],["p","gia có"],["p","nghĩa vụ"],["p","hợp tác"],["p","với nhau"],["p","(không đặt"],["p","ra một"],["p","cam kết)"],["p","(TỰ"],["p","NGHIÊN"],["p","CỨU)"],["p","7 Nguyên - Luật quốc tế yêu - Ngoại lệ 1"],["p","tắc thiện cầu các chủ thể (đ.46-53"],["p","tâm, thiện tận tâm thiện chí CUV 1969):"],["p","chí thực nổ lực tôn trọng và khi điều ước hiện các thực hiện những gì vô hiệu, các cam kết mình đã cam kết. bên sẽ ko quốc tế VD: cam kết trong thiện chí điều ước quốc tế, thực hiện."],["p","tập quán quốc tế, - Khi hoàn"],["p","tập quán quốc tế, cảnh thay"],["p","hành vi đơn đổi cơ bản"],["p","phương,… dẫn đến các"],["p","chủ thể của"],["p","luật quốc tế"],["p","không thiện"],["p","tâm, thiện"],["p","chí thực"],["p","hiện các"],["p","điều ước"],["p","quốc tế."],["p","2/3/2023"]]}]},{"t":"NGUỒN CỦA LQT","n":2,"g":[{"h":"I. Khái niệm nguồn của LQT","b":[["p","- Là hình thức biểu hiện sự tồn tại (nơi chứa đựng) của các QPPL Quốc tế do các chủ thể bình đẳng tự nguyện hình thành nên để điều chỉnh các quan hệ giữa họ với nhau  Phân loại các nguồn (khoản 1 điều 38): chỉ là quy chế của 1 cơ quan chuyên môn ko có quy chế ràng buộc. Ko có quy chế ràng buộc nhưng lại được lấy ra để áp dụng: tòa sẽ dựa vào những nguyên tắc để đưa ra phán quyết ai đúng, ai sai. Được thừa nhận rộng rãi, lặp đi lặp lại nhiều lần và hình thành nên tập quán. Tuy nhiên, trong quá trình áp dụng quốc gia chỉ thừa nhận 2 cái là nguồn: Điều ước quốc tế và Tập quán quốc tế  ĐVQT Nguồn của luật quốc tế: chứa những  TQQT quy tắc bắt buộc  Nguyên tắc pháp lý chung Phương tiện bổ trợ nguồn:"],["p"," Án lệ"],["p","có giá trị bổ sung thêm"],["p"," Học thuyết pháp luật"],["p","cho nguồn, nghiên cứu các"],["p"," Nghị quyết TCQTLCP"],["p","luật của các quốc gia, giải"],["p"," Hành vi đơn phương"],["p","thích bổ trợ thêm cho"],["p","nguồn"],["p"," Giá trị pháp lý:"],["p"," Nguồn có giá trị pháp lý bắt buộc còn phương tiện bổ trợ nguồn chỉ mang tính tham khảo CÂU HỎI: Cùng là nguồn, điều ước qt và tập quán cái nào sẽ có giá trị pháp lý cao hơn? Vì ko có giá trị pháp lý nên ko thể so sánh, đối tượng so sánh pháp lý ko tương đồng. (NGUỒN và PHƯƠNG TIỆN BỔ TRỢ NGUỒN). Đặc trưng số 3 thể hiện được ĐUQT và TQQT đều ngang nhau, ko phân chia về thứ bậc pháp lý, chủ thể với nhau, đều có giá trị pháp lý như nhau  Giá trị áp dụng: Nguồn được ưu tiên hơn vì Phương tiện bổ trợ không có trị và ko thể so sánh với nguồn để áp dụng vào thực tiễn, chỉ là cơ sở để dựa vào và bổ trợ cho nguồn. Giá trị điều ước sẽ được ưu tiên hơn vì dễ dùng, dễ áp dụng, dễ thực hiện. Thực tiễn cho thấy điều ước quốc tế được cụ thể hóa rõ ràng, chi tiết thành văn bản. Tập quán là khó áp dụng, lặp đi lặp lại và bất thành văn"]]},{"h":"II. Điều ước quốc tế","b":[["p","II.1 Khái niệm điều ước quốc tế"],["p","- Thỏa thuận bằng vb giữa các chủ thể của LQT trên cơ sở bình đẳng, tự nguyện nhằm xác lập thay đổi chấm dứt quyền và nghĩa vụ pháp lý"],["p","- Những đặc điểm sau:"],["p"," VB"],["p"," Chủ thể xây dựng nên: Chủ thể của luật quốc tế  Xây dựng trên cơ sở bình đẳng tự nguyên  Điểm a khoản 1 điều 2 của CUV 1969 và khoản 1 điều 2 của LQT 2016: nói rằng điều ước chỉ giữa cá quốc gia (chủ thể) (CUV). Không có cơ quan hành pháp và tư pháp thực thi pháp luật  Luật áp dụng cho xây dựng pháp luật là nhiều luật khác bao gồm luật VN, 7 nguyên tắc  Văn kiện: Có thể cấu thành từ một hoặc nhiều văn kiện khác nhau."],["p"," Về tên gọi"],["p"," Quyền và nghĩa vụ pháp luật"],["p","VD: Năm 2000. Qgia A và B tranh chấp đảo X. Năm 2005, quốc gia A và B thỏa thuận bằng miệng 2 nội dung sau đây: 1. Chọn quốc gia C (bên thứ 3 hòa giải). 2. Nếu ko hòa giải được thì chọn Tòa án công lý quốc tế là cơ quan giải quyết tranh chấp. Năm 2010, QGia A gửi qgia B 1 “bức thư tình” vs nội dung “Là nêu lại toàn bộ đầy đủ và chính xác những j đã được thỏa thuận bằng miệng năm 2005 giữa A và B. Năm 2015, B đồng ý toàn bộ ndung của “bức thư tềnh” tại biên bản hội nghị của các quốc gia trong khu vực. Hỏi: A và B đã xác lập điều ước chưa?"],["p","TRẢ LỜI: A và B đã xác lập điều ước. Bình đẳng tự nguyện kí kết trên cơ sở quốc tế, không vi phạm quy phạm quốc tế. NT số 5 hòa bình giải quyết các tranh chấp quốc tế. Trọng tài và tòa án. Đã chọn ra 3 biện pháp và hoàn toàn tuân thủ nguyên tắc của công pháp quốc tế."],["p","Lựa chọn phương thức (hòa giải) và cơ quan (tòa án công lý quốc tế) giải quyết tranh chấp xác lập quyền đc đơn phương hòa giải hoặc đơn phương khởi kiện. Xác lập quyền và nghĩa vụ của các bên. Văn kiện 1 là bức thư 2 là văn bản hội nghị."],["p","II.2 Quy trình ký kết điều ước quốc tế"],["p","- Có 2 giai đoạn:"],["p"," Giai đoạn 1: xây dựng văn bản điều ước (soạn và hình thành nên văn bản):"],["p"," Đàm phán: Các chủ thể của LQT sẽ trao đổi quan điểm, thảo luận và thống nhất nội dung đưa vào văn bản điều ước. Cách thức đàm phán trong các tổ chức qte liên chính phủ thực hiện các đàm phán thông qua các hội nghị thượng đỉnh hoặc bất thường. Ngoài các tổ chức qte liên chính phủ thì do các chủ thể tự thảo thuận."],["p"," Soạn thảo: đưa những ndung đàm phán vào vb điều ước. Cách thức soạn thảo trong các tổ chức qte liên chính phủ do các cơ quan chuyên môn của tổ chức này thực hiện. Ngoài các tổ chức qte còn có thể do các bên tự thỏa thuận. LƯU Ý: BƯỚC ĐÀM PHÁN VÀ SOẠN THẢO CÓ THỂ THAY THẾ CHO NHAU."],["p"," Thông qua: hoạt động xác định văn bản điều ước cuối cùng chấm dứt quá trình đàm phán soạn thảo."],["p","Có thể có nhìu văn bản khác nhau. Thông qua công khai hoặc biểu quyết."],["p"," Ký: quy trình ký kết 1 điều ước gồm 2 giai đoạn và nhiều bước khác nhau."],["p"," Giai đoạn 2: Phê chuẩn phê duyệt"],["p"," Điểm b khoản 1 điều 2 CUV 1969: phê chuẩn phê duyệt giữa chủ thể LQT 1 cách đơn phương+giáo trình  Phê chuẩn: khoản 8 điều 2-> Điều 28->khoản 1 điều 4 luật ĐUQT 2016: là hành động của QH hoặc chủ tịch nước. Loại ĐU phê chuẩn theo điều 28."],["p"," Phê duyệt: khoản 9 điều 2-> Đ.37-> Khoản 2 điều 4: Chính phủ phê duyệt. Điều ước được phê duyệt theo Đ.37. Khoản 2 điều 4 là pp loại trừ, điều ước nhân danh chính phủ và chính phủ phê duyệt  Thông thường, thẩm quyền phê chuẩn thuộc về cơ quan lập pháp, cơ quan quyền lực cao nhất của quốc gia đó. Bởi vì phê chuẩn sẽ được áp dụng cho những loại điều ước quan trọng và được liệt kê trong khoản 2 điều 4. Việc phê duyệt sẽ do cơ quan hành pháp thực hiện, đối với những điều ước ít quan trọng hơn những điều ước cần phê chuẩn. Luật qte ko bắt buộc các chủ thể phải phê chuẩn phê duyệt điều ước cho dù họ có tham gia vào quá trình xây dựng nên văn bản điều ước  Giai đoạn 3: Gia nhập (điểm b khoản 1 điều 2 CUV 1989)  Gia nhập được thực hiện khi chủ thể vào quá trình kí kết hoặc khi điều ước đã phát sinh hiệu lực. Muốn là thành viên thì xin gia nhập."],["p"," Cách thức xin gia nhập: kí trực tiếp vào văn bảng điều ước (1); gửi thư phê chuẩn phê duyệt (2) CÂU HỎI: TẠI SAO LẠI CÓ 2 CÁCH THỨC GIA NHẬP?"],["p","Khi bản thân điều ước đó yêu cầu thực hiện phê chuẩn, phê duyệt để xin gia nhập CÂU HỎI: PHÂN BIỆT 3 LOẠI KÝ KẾT Đàm phán-> soạn thảo-> thông qua. Đến thông qua chốt và chấm dứt quá trình soạn thảo. Cần người đại diện để ký kết giữa các quốc gia. Vụ trưởng vụ pháp chế đi theo đàm phán, soạn thảo và thông qua văn bản điều ước. Người trực tiếp đàm phán (ký tắt- ký xác nhận đây là điều ước vb cuối cùng, không có quyền). Ký ad referedum- người có thẩm quyền, không đại diện cho quốc gia nhưng thẩm quyền, chuyên môn lớn hơn nên sẽ mang ý kiến về hỏi QH. Sau đó sẽ biến thành chữ ký (người có đầy đủ thẩm quyền đi ký) chính thức, đầy đủ."],["p","- Ký tắt: chữ ký chốt vb để xác thực điều ước cuối cùng"],["p","- Ký ad referendum: cũng là chữ ký xác thực vb nhưng nếu được cơ quan, cơ quan có chức năng sẽ được coi là chữ ký đầy đủ, chính thức"],["p","- Ký đầy đủ: người có đầy đủ thẩm quyền đại diện cho luật quốc tế và nó sẽ phát sinh hiệu lực khi có sự ràng buộc giữa chủ thể luật quốc tế và điều ước quốc tế khi bản thân điều ước đó."],["p","Hoặc pháp luật của chủ thể đó ko yêu cầu, phê chuẩn hay phê duyệt."],["p","II.3 Bảo lưu (2.6)"],["p","- KN (điểm d khoản 1 khoản 2): ý nghĩa và mong muốn của các bên khi thực hiện bảo lưu. Bảo lưu chỉ được thực hiện từ bước thông qua trở về sau. Những trường hợp không được bảo lưu: cấm bảo lưu (1); việc bảo lưu làm đối tượng mục đích ko thực hiện được"],["p","(2); điều ước cho phép bảo lưu điều khoản nào thì chỉ được bảo lưu điều đó thôi (3); điều ước quốc tế song phương (3): 2 bên không thống nhất quan điểm -> đa phương được bao lưu."],["p","- Hệ quả pháp lý: trong qhe giữa quốc gia đề ra bảo lữu và qgia phản đối mà các bên vẫn muốn là thành viên của điều ước thì sẽ áp dụng điều ước quốc tế ban đầu (DUQT chưa được bảo lưu)."],["p","Trong qhe giữa ông đề ra và ông đồng ý thì áp dụng ĐU đã được bảo lưu. Ông không nói j thì coi khoản 5 đ.20."],["p"," VD: ĐUQT X có 50 đkhoan cho phép bảo lưu điều số 10, QG A đưa tuyên bố BL điều 10. B đồng ý bảo lưu của A, C phản đối tuyên bố bảo lưu A, D im lặng. Trong quan hệ giữa A và B có áp dụng đ.10 ko? Qhe A và C có áp dụng đ.10? A và D có áp dụng đ.10 ko? B, C, D áp dụng đ.10? Biết việc bảo lưu phải được chấp nhận (đ.19-21 CUV 1969) Trả lời: A và B ko (khoản 2 điều"],["p","20), A và C (điểm b khoản 4 điều 20), A và D ko (điều 5 khoản"],["p","20), B, C, D có (điểm c khoản 4 điều 20). Khi điều ước phát sinh hiệu, A và C có phát sinh, áp dụng cái được áp dụng ban đầu. A mún đàm phán mới so với các bên đã chốt và C phải chấp nhận lời đề nghị mới, còn không thì quay lại điều cũ. A và D không hoặc có vì trong tg 12 tháng thể hiện phản đối với A thì như C, không phản đối như B. B, C, D không áp dụng, không ai muốn sửa đổi."],["p","- Áp dụng điều ước quốc tế"],["p"," Áp dụng trực tiếp: là việc các chủ thể của LQT sử dụng các quy phạm pháp luật QT ở trong DUQT để điều chỉnh cho các đối tượng điều chỉnh của PL của các chủ thể luật QT. VD:"],["p"," Áp dụng gián tiếp: là qtrinh nội lực hóa biến quy phạm PLQT ở trong ĐU thành quy phạm PL của chủ thể luật qte."],["p","Sau đó sử dụng để điều chỉnh đối tượng của các chủ thể LQT (khoản 2 điều 6 Luật ĐU QT 2016)."],["p","II.4 Các đk ĐUQT trở thành nguồn của luật QT"],["p","- Điều 7,8 CUV 1969"]]},{"h":"III. Tập quán quốc tế","b":[["p","III.1 Khái niệm"],["p","- Quy tắc xử sự bất thành văn được các chủ thể thừa nhận như các quy phạm bắt buộc, đc các chủ thể của LQT thừa nhận rộng rãi. Con đường hình thành nên tập quán thông qua hành vi pháp lý đơn phương (1), thông qua các điều ước quốc tế (2), các nghị quyết tổ chức quốc tế liên chính phủ (3), nguyên tắc pháp lý chung (4), thông qua án lệ (5), các học thuyết pháp lý"],["p","(6). Có đc tồn tại trong án lệ, thừa nhận hay đề cập?"],["p","- Đk trở thành nguồn của TQ: không vi phạm các nguyên tắc cơ bản (1), áp dụng lặp đi lặp lại trong thời gian dài (2), được các chủ thể thừa nhận trong nhiều trường hợp bối cảnh khác nhau"],["p","(3)"]]}]},{"t":"DÂN CƯ TRONG LUẬT QUỐC TẾ","n":3,"g":[{"h":"I. Khái niệm và thành phần dân cư","b":[["p","- Toàn bộ những con người sinh sống cư trú trên lãnh thổ 1 quốc gia nhất định và chịu sự điều chỉnh của pháp luật quốc gia đó ⤷ Là những người mang quốc tịch của quốc gia sở tài ⤷ Không quốc tịch: không mang quốc tịch của bất kì quốc gia nào."],["p","⤷ Người có quốc tịch nước ngoài: mang ít nhất 1 quốc tịch của quốc gia nào đó nhưng không của quốc gia sở tại"],["p","- Chủ quyền quốc gia của dân cư: quyền định đoạt tối cao về nội ngoại đối với:"],["p","⤷ Đặt ra và thực thi các quyền và nghĩa vụ pháp lý với công dân kể cả trong hoặc ngoài lãnh thổ ⤷ Đặt ra và thực thi các quyền và nghĩa vụ pháp lý với người nước ngoài trên lãnh thổ nước sở tại."],["p","- Quốc tịch:"],["p","⤷ KN: liên kết chính trị pháp lý giữa quốc gia và công dân hình thành nên quyền và nghĩa vụ đối ứng ⤷ Tính chất chính trị: kết quả của quá trình đấu tranh giai cấp ⤷ Những cách thức xác lập qhe quốc tịch: sinh đẻ xác định quốc tịch cho trẻ từ khi mới đc sinh ra (1) là việc xác lập quốc tịch cho trẻ nơi trẻ đc sinh ra bất kể cha mẹ nó là ai; huyết thống xác định theo quốc tịch cha/mẹ bất kể trẻ được sinh ở đâu (2)"],["p","VD: không áp dụng khoản 1 nếu người đó đang cư trú ở VN mang quốc tịch nước ngoài. Ông A có quốc tịch VN. Vì đề bài không nói và ông A nhập tịch theo điều 19(về VN) hoặc theo đ.23- diện người Việt định cư ở nước ngoài thì sẽ không được tước quốc tịch."]]},{"h":"II. Căn cứ xác lập quốc tịch","b":[]},{"h":"III. H","b":[]},{"h":"IV. Bảo hộ công dân","b":[["p","IV.1 Khái niệm bảo hộ công dân"],["p","- Theo nghĩa hẹp, bảo hộ công dân là việc NN giúp đỡ công dân khi họ bị xâm hại, bị đe dọa xâm hại quyền và lợi ích hợp pháp"],["p","- Nghĩa rộng: việc NN giúp đỡ mọi mặt cho công dân khi phát sinh nhu cầu bảo hộ ở nước ngoài (LƯU Ý: SỬ DỤNG KHÁI NIỆM THEO NGHĨA RỘNG)."],["p","- Đk bảo hộ công dân: là công dân có quan hệ quốc tịch, quan hệ quốc tịch đang hiện hữu, xác định thẩm quyền bảo hộ công dân cho người mang nhiều quốc tịch."],["p","⤷ Việc xác định thẩm quyền bảo hộ song phương cho người nhiều quốc tịch, sẽ áp dụng nguyên tắc quốc tích hữu hiệu (quốc tịch thật sự) ⤷ Dựa vào việc đánh giá tổng hòa các yếu tố sau đây để quyết định quốc tịch nào là lk hữu hiệu nhất, thực sự nhất: tài sản, nơi sinh, nơi cư trú, thân nhân, nơi hưởng quyền, nghĩa vụ nhiều hơn… ⤷ Khi phát sinh nhu cầu bảo hộ: quyền và lợi ích hợp pháp của công dân bị xâm phạm (nghĩa hẹp). TH2: phát sinh nhu cầu bảo hộ khi công dân có hành vi xâm phạm nước sở tại và bị xử lý (không phải giúp họ thoát tội chỉ là bảo vệ quyền và lợi ích hợp pháp của họ tại nước sở tại ⤷ Khi phát sinh nhu cầu về hành chính tư pháp: có thể cung cấp dịch vụ pháp lý ⤷ Khi công dân đã áp dụng hết các biện pháp nhưng ko tự bảo hộ đc. Tự thực hiện hoặc đã thực hiện theo trình tự thủ tục của pháp luật quốc gia. Khi phát sinh các nhu cầu bảo hộ thì đầu tiên họ phải tự thực hiện."],["p","IV.2 Quy chế pháp lý dành cho người nước ngoài"],["p","– Nguyên tắc đối xử quốc gia (đối xử như công dân) (NT): quốc gia sẽ dành cho người nước ngoài những quyền và nghĩa vụ pháp lý không kém thuận lợi hơn công dân của nước sở tại. VN sẽ dành cho cta những quyền và nghĩa vụ. Bình đẳng, không phân biệt đối xử so với công dân của VN. Trừ 1 số trường hợp đb, quyền bầu cử, quyền ứng cử, không kém thuận lợi hơn"],["p","– Nguyên tắc tối huệ quốc (MFN): quốc gia sẽ dành cho người nước ngoài những quyền và nghĩa vụ không kém thuận lợi hơn công dân của nước thứ 3. Nếu NT là so sánh công dân nước ngoài và công dân sở tại thì MFN là ss những người dân vs người nước ngoài tại nước sở tại"],["p","– Đãi ngộ đặc biệt: quốc gia sẽ dành cho người nước ngoài quyền ưu đãi và miễn trừ mà công dân cũng không được hưởmg"],["p","– Nguyên tắc có qua có lại: quốc gia sở tại vs người nước ngoài theo cách họ đối xử vs công dân của nước sở tại IV.3 Tị nạn chính trị (cư trú chính trị)"],["p","– Việc quốc gia cho phép người nước ngoài, được cư trú trên lãnh thổ của mình khi họ đang bị truy nã vì tội phạm chính trị cư trú trên lãnh thổ của mình. Tự do tôn giáo, vì dân chủ. Tự do khoa học"],["p","– Việc cho hay không cho là quyền của mỗi quốc gia vì mỗi quốc gia có quan niệm khác nhau. Chỉ phát sinh đối với những người phạm tội chính trị (cư trú chính trị)"],["p","– Cho phép được cư trú trong lãnh thổ quốc gia, bảo vệ an ninh cho họ. Xem xét khả năng cấp quốc tịch cho họ"],["p","– Khuyến cáo những trường hợp sau không cho phép tị nạn chính trị. Đầu tiên là tội ác quốc tế: tội diệt chủng, tội ác chiến tranh tội chống lại loài người"],["p","– Những người thực hiện hành vi ám sát những đối tượng bảo hộ quốc tế, thực hiện hành vi phạm tội quốc tế."],["p","– Dẫn độ tội phạm khi có hiệp định về dẫn độ. Người phạm tội quốc gia thì không được tị nạn chính trị (còn nhiều tranh cãi)"],["p","– Điều 49 HP những người nước ngoài đấu tranh về dân chủ thì được VN xem xét cho cư trú chính trị"]]}]},{"t":"PHÁP LUẬT VỀ LÃNH THỔ QUỐC GIA","n":4,"g":[{"h":"I. Những vấn đề pháp lý cơ bản về lãnh thổ quốc gia","b":[["h","1. Khái niệm lãnh thổ quốc gia"],["p","– Lãnh thổ quốc gia là 1 phần của trái đất, bao gồm vùng đất, vùng nước, vùng trời trên chúng và lòng đất dưới chúng thuộc chủ quyền của 1 quốc gia"],["h","1.2 Các bộ phận"],["p","– Vùng đất của một quốc gia bao gồm toàn bộ phần đất liền (đất lục địa) và các đảo, quần đảo thuộc chủ quyền của các quốc gia kể cả các đảo và quần đảo gần hoặc xa bờ. Đ.121 công ước luật biển năm"],["p","– ĐK để xác định là 1 hòn đảo: nằm trên biển, gắn kết cố định vs đáy biển, lớn, tảng băng trôi, đc cấu thành bởi đất liền và quần đảo, thường 2 trở lên, gồm các đảo và vùng"],["p","– Quốc gia là chủ thể duy nhất và cao nhất, mọi vấn đề phát sinh đều được phát sinh"],["h","1.3 Vùng đất"],["h","1.3.1Khái niệm"],["h","1.3.2Cách thức xác lập lãnh thổ"],["h","1.3.3Tính chất chủ quyền"],["h","1.4 Lãnh thổ vùng nước"],["h","1.4.1Vùng nước nội địa"],["h","1.4.2Vùng nước biên giới"],["p","– Vùng nước biên giới của 1 quốc gia bao gồm ở biển nội địa, sông, suối đầm ảo, kênh rạch… nằm trong khu vực biên giới giữa các quốc gia. Lưu ý: đường biên giới là đường vô hình, đường biên giới là do con người làm ra. Việc sử dụng vùng nước biên giới không thể tuyệt đối, riêng biệt, phải thảo luận chia sẻ."],["p","Cùng hợp tác 2 quốc gia"],["p","– Tính chất chủ quyền là hoàn toàn đầy đủ. Vì các quốc gia cùng hợp tác với các quốc gia."],["p","– Xác lập vùng nước biên giới phải thông qua sự thỏa thuận giữa các quốc gia láng giềng. VD: con sông Mekong vùng nước nội địa của TQ; biên giới của Lào vs Myaanmar;"],["h","1.4.3Vùng nước nội thủy"],["p","– Vùng nước nội thủy được xác định một bên là bờ biển còn bên kia là đường cơ sở của quốc gia ven biển. Khi xác định sẽ xác định ranh giới trong và ngoài. Có thể là bờ biển đất liền hoặc đảo."],["p","– Cách thức xác lập: xác lập đường cơ sở và tuyên bố chủ quyền."],["p","– Tính chất chủ quyền: tuyệt đối và riêng biệt (như vùng đất)"],["h","1.4.4Vùng nước lãnh hải"],["p","– Vùng nước lãnh hải là vùng biển nằm ngoài nội thủy, tiếp liền với nội thủy có chiều rộng được xác định một bên là đường cơ sở và bên là đường cơ sở và bên kia là ranh giới phía ngoài cửa lãnh hải."],["p","– Ranh giới ngoài: điều 3 Công ước luật biển 1982 (trang 368):"],["p","– Tính chất chủ quyền: lãnh hải là bộ phần lãnh thổ thuộc chủ quyền hoàn toàn và đầy đủ của quốc gia. Trong vũng lãnh hải, tàu thuyền của các quốc gia có biển hay không có biển đều được quyền “đi qua không gây hại”. Tại vùng nước lãnh hải tồn tại quyền đi qua không gây hại. Tàu thuyền là phương tiện giao thông đi lại nên được quyền tự do đi lại. Điều 17 CULB 1982:"],["p","thỏa những điều kiện của công ước đc quyền đi qua ko gây hại."],["p","Không cần trả phí, thông báo dành cho tàu thuyền nước ngoài."],["p","Được thông qua 91-92, trước 1982. Ngăn ngừa bị tấn công. Khi công ước ra đời chia ra nội thủy, lãnh hải."],["h","1.5 Vùng thổ vùng trời"],["p","– Khoảng không gian bao trìm trên vùng đất và vùng nước của quốc gia, thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia."],["p","– Các thức xác lập quốc gia sở tại sẽ tuyên bố vùng trời của mình trên cơ sở các nguyên tắc của luật quốc tế hoặc vạch ra trong các điều ước. Có 2 cách thức xác lập. Khi nào thỏa thuận hay khi nào đơn phương tuyên bố? Cách xác lập mà có sự tiếp giáp về lãnh thổ: thông qua sự thỏa thuận. Nếu 1 bên đơn phương sẽ xảy ra tranh chấp."],["p","– Biên giới trên biển là ranh giới ngoài của lãnh hải (đường xanh dương gạch đứt). Tiếp giáp vùng trời biên giới Lào và Cam, vùng trời VN và quốc tế. Không giáp với ai nên tự đơn phương tuyên bố. VN tiếp giáp lãnh thổ trên biển vs: TQ, Cam. Chỗ nào tiếp giáp lãnh thổ đều phải thông qua sự thỏa thuận, nếu ko tiếp giáp thì đc đơn phương theo thỏa thuận vs quốc tế"],["p","– Tính chất chủ quyền: vùng trời thuộc chủ quyền hoàn toàn, tuyện đối của quốc gia."],["p","– Trừ Điều 53."],["h","1.6 Vùng lòng đất"],["p","– Là bộ phận lòng đất ở phía dưới vùng đất và vùng nước của quốc gia đc xác định từ biên giới trên bộ và biên giới trên biển xuống tâm trái đất. Tính chất chủ quyền là hoàn toàn tuyệt đối và riêng biệt. Cách thức xác lập tương tự như vùng trời."],["p","SO SÁNH ĐIỀU 1 HP 2013 VS KN VÀ CÁC BỘ PHẬN CẤU THÀNH NÊN LÃNH THỔ QUỐC GIA."]]},{"h":"II. Khái quát về biên giới quốc gia","b":[["h","1. Khái niệm biên giới quốc gia"],["p","– Biên giới quốc gia là ranh giới phân định lãnh thổ quốc gia này với lãnh thổ quốc gia khác hoặc với các vùng quốc gia có quyền chủ quyền trên biển hoặc giữa lãnh thổ quốc gia và lãnh thổ quốc tế."],["p","– Chức năng: giữa lãnh thổ quốc gia chủ quyền, quyền tài phán của quốc gia trên biển; giữa lãnh thổ quốc gia vs lãnh thổ quốc tế. Quyền chủ quyền bao gồm vùng tiếp giáp lãnh hải, thềm kinh tế, thềm lục địa."],["p","– 1 đất, 2a nội địa, 2b biên giới, 2c nội thủy, 2d lãnh hải, 3 trời, 5 tiếp giáp lãnh hải, 6 đặc quyền kinh tế, 7 thềm, 8 biển quốc tế, 9 đáy đại dương, 10 trời quốc tế"],["h","2. Các bộ phận cấu thành biên giới quốc gia"],["h","2.1 Biên giới trên bộ"],["p","– Biên giới trên bộ: đường biên giới trên đất liền, trên đảo, trên sông, trên hồ biên giới… Cách thức xác định: các quốc gia thường thỏa thuận ký kết 1 điều ước quốc tế song phương hoặc đa phương về biên giới (hoặc về lãnh thổ)"],["h","2.2 Biên giới trên biển"],["p","– Biên giới trên biển là ranh giới ngoài của lãnh hải do quốc gia ven biển thiết lập phù hợp vs công ước của LHQ về luật biển năm 1982 gồm:"],["p"," (1): biên giới trên biển giữa 2 quốc gia có lãnh hải tiếp giáp đối diện nhau."],["p"," (2): đường biên giới phân định vùng biển vùng chủ quyền của quốc gia ven biển với những vùng biển khác thuộc chủ quyền của quốc gia."],["h","2.3 Biên giới vùng trời"],["p","– Biên giới vùng trời của quốc gia là ranh giới phân định vùng trời thuộc chủ quyền quốc gia này"]]}]}],"cp2":[{"t":"Mở đầu","n":0,"g":[{"h":"","b":[["p","TỔNG HỢP CPQT NHÓM 2"]]}]},{"t":"NGUỒN CỦA LUẬT QUỐC TẾ","n":2,"g":[{"h":"1. Sự khác biệt giữa NGUỒN của LQT và nguồn của LQG: Đoàn","b":[["p","Khái niệm"],["p","Nguồn của LQT là: những hình thức biểu hiện sự tồn tại của các nguyên tắc, quy phạm pháp luật quốc tế. Do chính các chủ thể của Luật quốc tế thỏa thuận xây dựng nên. Nhằm điều chỉnh các các quan hệ về nhiều mặt ( chủ yếu điều chỉnh các quan hệ về mặt chính trị). Được đảm bảo thực hiện thông qua các chủ thể của Luật quốc tế (trước tiên và chủ yếu là các quốc gia)."],["p","Nguồn của LQG là: hệ thống các quy phạm pháp luật có mối liên hệ nội tại thống nhất với nhau được phân định thành các chế định pháp luật, các ngành luật và được thể hiện trong các văn bản. Do các cơ quan nhà nước có thẩm quyền ban hành theo những trình tự thủ tục và hình thức nhất định. Nhằm điều chỉnh các quan hệ trên nhiều lĩnh vực và được đảm bảo thực hiện thông qua các cơ quan cưỡng chế nhà nước;"],["p","Tiêu chí so sánh:"],["t",[["Tiêu chí","Luật Quốc gia","Luật Quốc tế"],["Hình thức biểu hiện nguồn","-thành văn: VBQPPL -bất thành văn: tập quán pháp, tiền lệ pháp( án lệ) -> Giá trị pháp lý: từ cao xuống thấp ( Hiến Pháp, luật, vb dưới luật,...)","-thành văn : VBQPPLQT(Điều ước quốc tế) -bất thành văn: tập quán quốc tế -> Gtri ply: ngang bằng nhau"],["Con đường hình thành (trình tự để xây dựng nên nguồn)","Thông qua các cơ quan lập pháp,và các cơ quan nhà nước khác có thẩm quyền ban hành. VD:Quốc Hội là cơ quan duy nhất có quyền ban hành Hiến Pháp, các vb luật. Dưới đó là lệnh thuộc thẩm quyền của chủ tịch nước; Nghị định thuộc thẩm quyền của Chính phủ.","không có cơ quan lập pháp chung, chủ yếu do sự thỏa thuận, bình đẳng, tự nguyện giữa các chủ thể luật quốc tế xây dựng nên, trước tiên và chủ yếu là thông qua sự thỏa thuận của các quốc gia. Vd: Tổ chức LHQ được thành lập năm 1945 cho ra đời Hiến chương LHQ hình thành thông qua sự thỏa thuận của 51qg đầu tiên (các qg sáng lập)"],["Giá trị pháp lý: ( phạm vi áp dụng nguồn)","Hẹp. dùng để điều chỉnh các mối quan hệ phát sinh trong phạm vi lãnh thổ","Rộng hơn. dùng để điều chỉnh các mối quan hệ phát sinh giữa các quốc gia với nhau,các quan hệ xã hội phát sinh trong đời sống sinh hoạt quốc tế giữa các chủ thể ( trước tiên và chủ yếu là áp dụng cho các quốc gia thành viên) VD: Hiến chương được áp dụng cho 193 các nước thành viên tức là 193 nước thành viên phải phải áp dụng."],["Cơ chế đảm bảo thực thi","xuất phát từ bản chất của chúng: - Bản chất của LQG xuất phát từ ý chí của giai cấp thống trị nên bắt buộc mọi giai tầng chủ thể phải tuân theo. -> Có cơ quan cưỡng chế chủ chung","Xuất phát từ cơ sở tự nguyện -> Không có cơ quan cưỡng chế chung, Do các chủ thể của luật quốc tế"]]],["p","-> Nhận xét: Luật quốc tế và luật quốc gia đều là những hệ thống nguyên tắc quy phạm pháp luật được các quốc gia,các chủ thể tham gia quy phạm pháp luật xây dựng.Tuy nhiên, giữa hai luật này vẫn tồn tại nhiều điểm đặc trưng riêng biệt."],["p","Tại sao lại ưu tiên áp dụng điều ước quốc tế ?\\"],["p","– Theo nguyên tắc của Điều ước quốc tế thì cần phải soạn thảo phù hợp với pháp luật của quốc tế. Cùng với đó, trước khi ký kết điều ước thì hầu hết điều ước này phù hợp với hiến pháp của quốc gia, nếu trái với quy định quốc gia thì có thể sửa đổi hiến pháp quốc gia. Theo đó, sau khi ký kết điều ước quốc tế thì thực tiễn có thể áp dụng trực tiếp điều ước quốc tế mà không cần phải nghị định hướng dẫn nào khác."],["p","– Theo một trong những nguyên tắc khi ký kết Điều ước quốc tế dựa trên sự tự nguyện, bình đẳng và tận tâm. Nhưng thực tế vẫn có một số quốc gia không tham gia việc ký kết nhưng vẫn thực hiện theo những quy định về nghĩa vụ của Điều ước quốc tế. Điều này chứng tỏ rằng Điều ước quốc tế được coi là cách xử sự chung được áp dụng phổ biến"],["p","5 phương tiện bổ trợ nguồn:"],["p","- Các nguyên tắc pháp luật chung"],["p","- Phán quyết của Toà án công lý quốc tế"],["p","- Nghị quyết của tổ chức quốc tế Liên chính phủ: bao gồm nghị quyết có hiệu lực bắt buộc và nghị quyết không có hiệu lực bắt buộc đổi với các thành viên"],["p","- Hành vi pháp lý đơn phương của quốc gia"],["p","- Các học thuyết về luật quốc tế"]]},{"h":"2. Điều ước quốc tế","b":[]},{"h":"2.1 Khái niệm, điều kiện để ĐƯQT trở thành nguồn: Huy","b":[["p","Khái niệm: Điều ước quốc tế là văn bản pháp lý quốc tế. Do các chủ thể luật quốc tế thỏa thuận xây dựng nên trên cơ sở tự nguyện, bình đẳng (trước tiên là các quốc gia). Nhằm xác lập, thay đổi, chấm dứt những quyền và nghĩa vụ giữa các chủ thể của luật quốc tế."],["p","Điều kiện trở thành nguồn của điều ước quốc tế: Không phải tất cả các điều ước quốc tế được ký kết đều là nguồn của luật quốc tế. Một điều ước muốn trở thành nguồn của luật quốc tế phải thỏa mãn các điều kiện sau:"],["p","Là vb pháp lý quốc tế"],["p","Được ký kết trên cơ sở hoàn toàn tự nguyện và bình đẳng về quyền và nghĩa vụ."],["p","Được ký kết phù hợp với quy định của pháp luật quốc gia của các bên về trình tự, thẩm quyền và thủ tục ký kết."],["p","Nội dung phù hợp với những nguyên tắc cơ bản của Luật quốc tế. (7 nguyên tắc)"]]},{"h":"2.2 Quá trình ký kết ĐƯQT: trình bày : g","b":[["p","Nếu ĐƯQT không quy định là phê chuẩn/phê duyệt thì sau khi ký chính thức thì Đưqt đó sẽ phát sinh hiệu lực."],["p","Gđ1: (cụ thể ra trong đó làm gì)"],["p","Đàm phán"],["p","Là sự thương lượng đấu tranh về lợi ích giữa các chủ thể tham gia ký kết điều ước quốc tế nhằm đi đến một thỏa thuận chung nhất"],["p","Hình thức đàm phán :"],["p","Tại hội nghị thượng đỉnh"],["p","Cử phái đoàn đàm phán"],["p","Đàm phán thông qua cơ quan đại diện nước ngoài"],["p","Thẩm quyền đàm phán :"],["p","Thẩm quyền đương nhiên. Điều 7.2 công ước viên 1969 về luật điều ước quốc tế"],["p","Theo ủy quyền : điều 7.1 Công ước viên 1969 về luật điều ước quốc tế"],["p","Soạn thảo"],["p","Là quá trình truyền tải những nội dung đàm phán thể hiện thành văn bản điều ước"],["p","Hình thức soạn thảo:"],["p","Đối với điều ước quốc tế song phương: sẽ thành lập ban soạn thảo văn bản để soạn thảo văn bản điều ước. Hoặc cũng có thể do 1 bên soạn thảo sau đó 2 bên sẽ thống nhất nội dung văn bản điều ước"],["p","Đối với điều ước đa phương: các bên ký kết sẽ thành lập ủy ban soạn thảo bao gồm đại diện của tất cả các bên tham gia"],["p","Thông qua"],["p","Là hoạt động nhằm thống nhất lần cuối cùng nội dung văn bản điều ước, từ đó các chủ thể không thể đơn phương sửa đổi, bổ sung ,hủy bỏ các nội dung trong văn bån điều ước nếu điều ước đó không cho phép."],["p","Các cách thức thông qua văn bản điều ước :do các bên thỏa thuận"],["p","Điều ước song phương: bằng cách tổ chức hội nghị toàn thể hoặc thông qua sự thỏa thuận của cá nhân có thẩm quyền do các bên cử ra.Thỏa thuận này có thể bằng lời nói hoặc bằng hình thức ký tắt."],["p","Đối với điều ước đa phương : có thể thông qua bằng bỏ phiếu kín hoặc biểu quyết"],["p","Nguyên tắc consensus(đồng thuận): văn bản điều ước được thông qua khi không có quốc gia nào phản đối.Áp dụng cho những nội dung quan trọng,đòi hỏi sự tham gia và thực hiện 1 cách đầy đủ của tất cả các bên liên quan"],["p","Gđ2 (như trên):"],["p","Ký"],["p","ký tắt: Là việc các vị đại diện của các bên tham gia đàm phán, soạn thảo ký xác nhận văn bản dự thảo là văn bản đã được thông qua. Sau ký tắt điều ước quốc tế chưa phát sinh hiệu lực ( có thể xem xét, đánh giá, cân nhắc nếu có đk trái với pl qg)"],["p","ký tượng trưng (Ad referendum): là việc ký của vị đại diện với điều kiện là có sự đồng ý tiếp theo của cơ quan có thẩm quyền theo quy định của pháp luật trong nước thì điều ước sẽ không phải ký chính thức nữa. Như vậy, hình thức ký có hiệu lực cho điều ước nếu các cơ quan có thẩm quyền của quốc gia tỏ rõ sự chấp thuận sau khi ký ad referendum."],["p","ký đầy đủ (ký chính thức ): là việc ký của vị đại diện vào văn bản dự thảo điều ước, Nếu điều không quy định các trình tự và thủ tục khác ( như phê chuẩn, phê duyệt) thì điều ước quốc tế đó sẽ phát sinh hiệu lực sau khi ký đầy đủ ( tất cả các bên có mong muốn all bên điều ước đi vào thực hiện)"],["p","Khi không yêu cầu phải phê chuẩn/ phê duyệt thì việc ký đầy đủ hoặc hình thức tương đương sẽ tạo ra hiệu lực ràng buộc giữa chủ thể và điều ước quốc tế đó."],["p","Gđ3: Phê chuẩn hoặc phê duyệt (*): cần làm rõ : Bảo Hân"],["p","Khi Đưqt có quy định qua bước phê chuẩn/phê duyệt thì sau khi ký chưa phát sinh hiệu lực theo thủ tục nội bộ của các quốc gia thành viên mà phải qua pc/pd mới phát sinh hiệu lực cho đưqt đó."],["p","-> Phê chuẩn/ phê duyệt là gì?"],["p","Phê chuẩn:"],["p","(Khái niệm phê chuẩn được quy định tại Điều 2 khoản 1 điểm b của Công ước Vienna 1969)"],["p","Phê chuẩn là hành vi pháp lý đơn phương (tuyên bố đơn phương) của cơ quan nhà nước có thẩm quyền thực hiện nhằm chính thức tự nguyện công nhận hiệu lực ràng buộc của ĐƯQT đối với quốc gia mình."],["p","Mục đích của việc phê chuẩn:"],["p","Thứ nhất, việc phê chuẩn ĐƯQT diễn ra trong một quá trình giúp cho CQNN có thẩm quyền có cơ hội, có điều kiện cũng như thời gian để rà soát lại một lần nữa nội dung điều ước mà quốc gia đã ký trước khi chính thức ràng buộc hiệu lực của điều ước đối với QG mình."],["p","Thứ hai, kiểm tra tính hợp pháp của người đại diện."],["p","Thứ ba, giúp cho các QG có thời gian chuẩn bị cho việc thực hiện ĐƯQT ở phạm vi QG."],["p","Phê duyệt:"],["p","( Khái niệm phê duyệt được quy định tại Điều 2 khoản 1 điểm b của Công ước Vienna 1969)"],["p","Khái niệm phê duyệt cũng giống phê chuẩn. Phê duyệt cũng là hành vi pháp lý đơn phương của CQNN có thẩm quyền chính thức xác nhận hiệu lực của một ĐƯQT đối với QG mình."],["p","Mục đích của việc phê duyệt cũng tương tự như phê chuẩn."],["p","-> Thẩm quyền của 2 cái đó"],["p","Phê chuẩn:"],["p","Thông qua hành vi phê chuẩn, quốc gia bày tỏ sự đồng ý của mình trong việc hưởng quyền và thực hiện các nghĩa vụ tương ứng đã được ghi nhận trong ĐƯQT."],["p","Quốc gia không có nghĩa vụ phê chuẩn một ĐƯQT mà họ đã ký trước đó. Như đã nói ở trên, việc phê chuẩn có ý nghĩa như việc QG chính thức công nhận hiệu lực của điều ước đó đối với QG mình, vì thế trước khi phê chuẩn thì điều ước đó vẫn chưa có hiệu lực pháp lý. Nếu trong quá trình phê chuẩn mà CQNN có thẩm quyền rà soát được những nội dung bất lợi, mâu thuẫn với PL QG thì họ có quyền không phê chuẩn điều ước đó. Hành vi từ chối phê chuẩn ĐƯQT không bị coi là hành vi VPPL QT."],["p","Theo PL của hầu hết các QG trên TG, thẩm quyền phê chuẩn ĐƯQT thuộc về cơ quan quyền lực cao nhất của nhà nước hoặc Nguyên thủ quốc gia hoặc cơ quan hành phap"],["p","Ví dụ về phê chuẩn ĐƯQT ở VN :"],["p","Theo điều 32 Luật Ký kết, gia nhập và thực hiện điều ước quốc tế của VN năm 2005, thẩm quyền phê chuẩn ĐƯQT thuộc về QH và Chủ tịch nước"],["p","Theo HP2013, tại khoản 14 điều 70 có quy định rõ thẩm quyền của QH trong việc phê chuẩn việc quyết định gia nhập hoặc chấm dứt hiệu lực của ĐƯQT liên quan đến các vấn đề như chiến tranh, hoà bình, chủ quyền quốc gia và tư cách thành viên của nước Cộng hoà XHCNVN tại các tổ chức quốc tế cũng như các khu vực quan trọng; ngoài ra QH cũng phê chuẩn các ĐƯQT về các vấn đề nhân quyền như quyền con người, quyền và nghĩa vụ cơ bản của công dân; cuối cùng là phê chuẩn các ĐƯQT khác trái với luật, nghị quyết của QH."],["p","Cũng theo HP2013, tại khoản 6 điều 88 có quy định cụ thể Chủ tịch nước có thẩm quyền trình QH phê chuẩn, quyết định gia nhập hoặc chấm dứt hiệu lực của ĐƯQT được quy định tại ví dụ trước đó (khoản 14 điều 70); ngoài ra còn có thể tự quyết định phê chuẩn, gia nhập hoặc chấm dứt hiệu lực ĐƯQT khác nhân danh Nhà nước."],["p","=> Từ đó rút ra được một số kết luận như sau:"],["p","Thứ nhất, phê chuẩn là những hành vi pháp lý đơn phương mà các QG thực hiện. Nếu như quá trình đàm phán là quá trình mà các bên tham gia ký kết thực hiện để tạo ra các văn bản dự thảo thì hành vi phê chuẩn là hành vi pháp lý đơn phương do các QG tham gia thực hiện."],["p","Thứ hai, ĐƯQT nào cần phê chuẩn sẽ do các bên ký kết thỏa thuận và ghi nhận trong điều ước đó. Nhưng việc phê chuẩn sẽ được thực hiện trên cơ sở tuân thủ theo đúng quy định về thẩm quyền và thủ tục được quy định bởi PL của QG."],["p","Thứ ba, hành vi phê chuẩn là hành vi có mục đích rõ ràng. Đây là hành vi có sự cam kết và tuyên bố rằng ĐƯQT mà mình phê chuẩn bắt đầu chính thức có hiệu lực đối với QG tham gia ký kết."],["p","Phê duyệt:"],["p","Thẩm quyền phê duyệt ĐƯQT thông thường sẽ thuộc về cơ quan hành pháp."],["p","Ví dụ về phê duyệt ĐUQT ở VN :"],["p","Theo HP2013, tại khoản 7 điều 96 có quy định Chính phủ có thẩm quyền phê duyệt hoặc chấm dứt hiệu lực ĐƯQT nhân danh CP, trừ ĐƯQT trình QH phê chuẩn quy định tại khoản 14 điều 70."],["p","-> Phân loại phê chuẩn và phê duyệt"],["p","Giống nhau:"],["p","Về bản chất, cả phê chuẩn và phê duyệt đều là những hành vi pháp lý của thủ tục nội bộ của QG. Mục đích của phê chuẩn và phê duyệt là nhằm xác nhận sự đồng ý ràng buộc với một điều ước quốc tế nhất định."],["p","Làm điều ước quốc tế phát sinh hiệu lực đối với quốc gia tham gia điều ước quốc tế."],["p","Phê chuẩn và phê duyệt áp dụng cả với điều ước quốc tế song phương và đa phương."],["p","Khác nhau:"],["t",[["","Phê chuẩn","Phê duyệt"],["Thẩm quyền","Thuộc về cơ quan quyền lực cao nhất của nhà nước hoặc nguyên thủ quốc gia hoặc cơ quan hành pháp (Tổng thống, Quốc hội, Nghị viện, Chủ tịch nước,...) Ở Vn: Luật Đưqt 2016","Thuộc về cơ quan hành pháp (Chính phủ)"],["Đối tượng","(quy định tại Điều 31 Luật ký kết, gia nhập và thực hiện ĐƯQT của VN năm 2005) Các loại điều ước quốc tế phải phê chuẩn - ĐƯQT có quy định phải phê chuẩn, về biên giới, lãnh thổ,... - ĐƯQT nhân danh Nhà nước. - ĐƯQT nhân danh CP có quy định trái với luật, nghị quyết của Quốc hội.","(quy định tại Luật ký kết, gia nhập và thực hiện ĐƯQT của VN năm 2005) Trừ trường hợp thuộc thẩm quyền phê chuẩn của Quốc hội, các điều ước quốc tế sau đây phải được phê duyệt: - ĐƯQT nhân danh CP có quy định phải phê duyệt - ĐƯQT nhân danh CP phải hoàn thành thủ tục pháp lý theo quy định của mỗi nước để có hiệu lực ( thủ tục pháp lý nội bộ ) - ĐƯQT nhân danh CP có quy định trái với quy định trong văn bản quy phạm pháp luật của Chính phủ."],["Mức độ quan trọng","Được áp dụng, đặt ra đối với những ĐƯQT có tầm quan trọng đặc biệt đối với QG","Được áp dụng, đặt ra đối với những ĐƯQT có tầm quan trọng cũng như ảnh hưởng thấp hơn"]]],["p","Về 3 quá trình: Gia Hân"],["p","-> Tại sao lại có 3 quá trình? Bỏ bước nào có được không?"],["p","-"],["p","-> Bước nào quan trọng nhất? Tại sao?"],["p","Thể hiện sự đồng ý ràng buộc ( thể hiện thông qua việc ký, phê chuẩn, phê duyệt theo điều 11 - điều 15) là bước quan trọng trọng nhất trong tất cả các bước ký kết điều ước quốc tế vì chỉ đến bước này, một quốc gia mới chính thức thể hiện ý chí chịu ràng buộc bởi một điều ước quốc tế."]]},{"h":"2.3 Bảo lưu ĐƯQT ( điều 19 đến điều 23 Công Ước Viên ):","b":[["p","Khái niệm:"],["p","Theo Công ước Viên năm 1969 về luật điều ước quốc tế, thuật ngữ bảo lưu điều ước quốc tế dùng để chỉ một tuyên bố đơn phương bất kể cách viết hoặc tên gọi như thế nào của một quốc gia đưa ra khi ký, phê chuẩn, phê duyệt hoặc gia nhập điều ước đó.nhằm qua đó loại trừ hoặc thay đổi hiệu lực của một hoặc một số quy định của điều ước trong việc áp dụng chúng đối với quốc gia đó."],["p","Mục đích"],["p","Vừa đảm bảo giá trị của điều ước vẫn còn mà vừa bảo vệ lợi ích các quốc gia, chế định bảo lưu xuất hiện, đảm bảo một quốc gia vì lợi ích riêng của mình có thể sửa đổi hiệu lực hoặc loại bỏ một hoặc một số quy định."],["p","Thời điểm bảo lưu: ( khoản 1 điều 19 CUV): Tùy vào từng thời điểm có thể ở đư đã phát sinh hiệu lực và chưa phát sinh hiệu lực"],["p","Khi ký, phê chuẩn, chấp thuận, phê duyệt, hoặc gia nhập một điều ước, một quốc gia có thể đề ra một bảo lưu"],["p","Khi ký, -> Chưa phát sinh hiệu lực"],["p","Qg gửi công hàm xin gia nhập vào các qg khác -> Đư đã phát sinh hiệu lực"],["p","Muốn cho tuyên bố xin bảo lưu có hiệu lực mà qg đó muốn bảo lưu thì QUỐC GIA ĐÓ PHẢI NHẮC LẠI TUYÊN BỐ BẢO LƯU, ĐIỀU KHOẢN BẢO LƯU"],["p","Trường hợp không được bảo lưu: ( tương tự bảo lưu là quyền không tuyệt đối)"],["p","một quốc gia sẽ không được phép đưa ra tuyên bố bảo lưu nếu liên quan đến:"],["p","Trường hợp điều ước quốc tế cấm bảo lưu;"],["p","Điều ước quốc tế chỉ cho phép bảo lưu những điều khoản cụ thể"],["p","Trường hợp bảo lưu không phù hợp với đối tượng và mục đích của điều ước"],["p","Bảo lưu chỉ có thể được thực hiện đối với các ĐƯQT đa phương, sẽ không đặt ra đối với điều ước QT song phương. Việc một bên đưa ra tuyên bố bảo lưu sẽ được coi như một đề nghị thỏa thuận lại, ký kết ĐƯ mới Bởi vì tất cả điều ước song phương chỉ có thể ký kết và thực hiện khi có sự đồng thuận của hai bên tham gia."],["p","Thủ tục bảo lưu"],["p","Do bảo lưu có ảnh hưởng trực tiếp tới giá trị hiệu lực của các điều khoản của điều ước quốc tế trong quan hệ giữa các bên nên theo quy định của Công ước Viên năm 1969, việc tuyên bố bảo lưu, rút bảo lưu, chấp thuận hoặc phản đối bảo lưu đều phải được trình bày bằng văn bản và thông báo cho các bên liên quan."],["p","Điều ước quốc tế quy định rõ điều khoản nào được bảo lưu-> đương nhiên bỏ lưu đều khoản đó"],["p","không quy định rõ điều khoản được bảo lưu"],["p","-> phải được tất cả các quốc gia đàm phán chấp nhận"],["p","-> chấp nhận bảo lưu: Sau 12 12 tháng mà không phản hồi"],["p","- điều ước thành lập một tổ chức quốc tế -> chấp thuận của cơ quan có thẩm quyền của tổ chức quốc tế đó"],["p","- Điều ước quốc tế có quy định vấn đề phê chuẩn/ phê duyệt mà tuyên bố bảo lưu được đưa ra ở những giai đoạn đầu của quá trình ký kết -> phải nhắc lại khi phê chuẩn/ phê duyệt"],["p","- Hình thức của các tuyên bố bảo lưu. phản đối bảo lưu và đồng ý bảo lưu -> bằng văn bản"],["p","- Rút tuyên bố bảo lưu, đồng ý và phản đối bảo lưu -> bằng văn bản"],["p","Hệ quả pháp lý của bảo lưu"],["p","Quan hệ giữa Quốc gia bảo lưu và quốc gia chấp nhận bảo lưu -> thực hiện bằng các điều ước quốc tế áp dụng bảo lưu"],["p","Quan hệ giữa Quốc gia Tuyên bố bảo lưu vào quốc gia chống lại bảo lưu -> điều chỉnh bằng điều ước mà không áp dụng bảo lưu"],["p","Ý nghĩa của bảo lưu: Huyền Cơ"],["p","Đối với nhiều thành viên, bảo lưu là giải pháp pháp lý để giải quyết hài hoà lợi ích riêng của quốc gia với lợi ích khi tham gia điều ước, qua đó góp phần tăng cường số lượng thành viên tham gia để điều ước có điều kiện hình thành và phát huy vai trò điều chỉnh các quan hệ quốc tế nảy sinh."],["p","Tại sao bảo lưu là quyền không tuyệt đối? Vì"],["p","Bảo lưu sẽ không đặt ra đối với điều ước quốc tế song phương. Vì điều ước quốc tế song phương chỉ có thể đặt ra khi có sự đồng thuận của hai bên mà 1 bên đưa ra bảo lưu thì xem như đưa ra một đề nghị mới, lúc này hai bên lại tiếp tục thỏa thuận, thống nhất vấn đề đó chứ k thể đưa ra bảo lưu."],["p","Bảo lưu không thể được thực hiện đối với những điều ước cấm bảo lưu ( đối với điều ước đa phương). Có nghĩa là muốn trở thành thành viên của điều ước quốc tế này thì bắt buộc chủ thể phải thực hiện đầy đủ nội dung, điều khoản,.. Không thực hiện được thì không thể trở thành thành viên của điều ước."],["p","Không được bảo lưu những điều khoản khác ngoài những điều khoản điều ước quốc tế cho phép bảo lưu"],["p","Không được bảo lưu nếu bảo lưu không phù hợp với đối tượng và mục đích của điều ước. (https://iuscogens-vie.org/2018/07/22/88/ kỹ hơn về một số ví dụ của bảo lưu)"],["p","Giải quyết mối quan hệ bảo lưu:"],["p","Rút các bảo lưu và phản đối bảo lưu"],["p","Trừ khi điều ước có quy định khác, bất cứ lúc nào cũng có thể rút một bảo lưu mà không cần có sự đồng ý của các quốc gia đã chấp thuận bảo lưu"],["p","Trừ khi điều ước có quy định khác, bất cứ khi nào cũng có thể rút một phản đối bảo lưu"],["p","Trừ khi điều ước có quy định khác hoặc có thỏa thuận nào khác:"],["p","Việc rút một bảo lưu sẽ chỉ có giá trị hiệu lực đối với một quốc gia ký kết khác khi một quốc gia này được nhận thông báo"],["p","Việc rút một phản đối bảo lưu sẽ chỉ có giá trị hiệu lực khi nào quốc gia đề ra bảo lưu nhận được thông báo về việc rút này."],["p","Chấp thuận và bác bỏ bảo lưu ( điều 20 CƯV )"],["p","—------------------------------------------"],["p","Cho biết đuqt chấm dứt hiệu lực trong những trường hợp nào? : Huyền Cơ"],["p","Điều ước quốc tế có hai loại: điều ước có thời hạn và điều ước vô thời hạn"],["p","Tự động hết hiệu lực"],["p","Hết thời hạn có hiệu lực của điều ước. Trên thực tế, nếu các bên chưa thực hiện xong nghĩa vụ thì các bên sẽ thỏa thuận kéo dài hiệu lực của điều ước"],["p","Khi các bên đã thực hiện xong các quyền và nghĩa vụ quy định trong điều ước quốc tế trước thời hạn quy định"],["p","Về mặt nguyên tắc, khi có chiến tranh xảy ra, đưqt sẽ hết hiệu lực đối với bên tham chiến (đa phương), và chấm dứt hiệu lực đối với đưqt song phương."],["p","*Tuy nhiên, khi có chiến tranh xảy ra, một số đưqt vẫn không mất hiệu lực: đưqt về lãnh thổ, biên giới; quyền con người; điều ước mà các bên đã thỏa thuận trước là khi có chiến tranh xảy ra thì điều ước vẫn tiếp tục có giá trị... ( giáo trình trang 126)"],["p","Hết hiệu lực theo ý muốn của các bên"],["p","Thỏa thuận"],["p","Bãi bỏ điều ước quốc tế: Là hành vi đơn phương của một quốc gia tuyên bố điều ước đã hết hiệu lực đối với mình ( theo quy định của điều ước), Với điều kiện điều ước đó cho phép bãi bỏ là quyền của quốc gia, nó được ghi nhận trong điều ước."],["p","VD: Một quốc gia thành viên được bãi bỏ điều ước sau thời hạn 3 năm."],["p","Đưqt cũng có thể được bãi bỏ khi các bên thống nhất bãi bỏ."],["p","Hủy bỏ điều ước quốc tế: là tuyên bố đơn phương của một quốc gia ( của cơ quan có thẩm quyền trong nước) nhằm chấm dứt hiệu lực của một điều ước quốc tế đối với mình mà không cần điều ước quốc tế đó cho phép mà chỉ cần rơi vào một trong những trường hợp sau:"],["p","Có một hay nhiều bên vi phạm nghiêm trọng điều ước"],["p","Có một trong các bên chỉ hưởng quyền mà không thực hiện nghĩa vụ"],["p","Khi điều kiện hoàn cảnh trong nước bị thay đổi căn bản dẫn đến các bên không thể thực hiện được:"],["p","Khi có sự thay đổi tư cách chủ thể của LQT: hợp nhất, chia tách"],["p","VD: 1. năm 1993 ký là nhân danh Tiệp Khắc, nhưng sau đó đất nước bị chia tách thành 2 quốc gia"]]},{"h":"2. Năm 1990 Đông Đức và Tây Đức hợp lại làm một","b":[["p","Khi có sự thay đổi về thể chế chính trị: lật đổ chính phủ cũ để thành lập nên chính phủ mới (CP đảo chính vì CP đảo chính này hợp lòng dân; duy trì được quyền lực trong thời gian dài, ổn định; có khả năng kiểm soát toàn bộ hoặc phần lớn lãnh thổ quốc gia một cánh độc lập và tự chủ, tự quản lý và điều hành mọi công việc của đất nước)."],["p","Thực hiện đuqt bằng cách nào? Liên hệ Việt Nam? ( tìm CSPL trong Luật Điều ước quốc tế)"],["p","Áp dụng trực tiếp, liên hệ Việt Nam: Đoàn"],["p","Áp dụng trực tiếp : Điều ước qt đó đủ rõ, đủ chi tiết thì điều ước quốc tế có hiệu lực trực tiếp đối với các lĩnh vực thuộc phạm vi điều chỉnh của nó tại các nước thành viên.Điều này sẽ dẫn đến hệ quả là điều ước quốc tế sau khi phát sinh hiệu lực sẽ được áp dụng trực tiếp mà quốc gia đó không cần phải tiến hành \"nội luật hoá\", trừ khi chính điều ước quốc tế đó có quy định khác."],["p","Liên hệ Việt Nam :"],["p","+ Căn cứ vào yêu cầu, nội dung, tính chất của điều ước quốc tế, Quốc hội, Chủ tịch nước, Chính phủ khi quyết định chấp nhận sự ràng buộc của điều ước quốc tế đồng thời quyết định áp dụng trực tiếp toàn bộ hoặc một phần điều ước quốc tế đó đối với cơ quan, tổ chức, cá nhân trong trường hợp quy định của điều ước quốc tế đã đủ rõ, đủ chi tiết để thực hiện. (trong điều 6 Luật điều ước quốc tế 2016)."],["p","+ Điều ước phân định Vịnh Bắc Bộ"],["p","+ Trên thực tế hầu hết các ĐUQT ở Việt Nam đều được áp dụng gián tiếp và được thể hiện trong hồ sơ đề nghị ký kết ĐUQT. Cụ thể một số điều được áp dụng trực tiếp:"],["p","Áp dụng gián tiếp, liên hệ Việt Nam( cần phải nội luật hóa, sửa đổi, bổ sung): Đạt"],["p","Trong trường hợp điều ước quốc tế đó chưa rõ ràng, chưa phù hợp với tình hình thực tế của quốc gia. Điều ước quốc tế có hiệu lực gián tiếp đối với các lĩnh vực thuộc phạm vi điều chỉnh của nó tại các nước thành viên.Điều này sẽ dẫn đến hệ quả là điều ước quốc tế sau khi đưa vào quốc gia cần phải tiến hành chuyển hóa, \"nội luật hoá\", sửa đổi, bổ sung cho phù hợp với tình hình thực tế của các quốc gia."],["p","Điều 6 khoản 2 Luật điều ước quốc tế 2016"],["p","Liên hệ:"],["p","VN chính thức trở thành thành viên của Công ước Viên 1982 thì VN sẽ tiến hành “nội luật hóa”, diễn giải rõ ràng chi tiết hơn những điều ước đó để nhân dân được thực hiện dễ dàng hơn"],["p","VN là thành viên của Công ước quốc tế về Luật Biển"],["p","Trong trường hợp có cả Đưqt và luật quốc gia thì áp dụng cái nào?"],["p","Về mặt nguyên tắc Theo khoản 1, điều 6 CUV thì ưu tiên áp dụng Đuqt khi nước ta là thành viên ( nguyên tắc tuân thủ tận tâm thực hiện các cam kết quốc tế)"],["p","Theo k1 điều 6 Luật đưqt quy định ưu tiên áp dụng Hiến Pháp nghĩa là HP có hiệu lực cao hơn Đưqt là đúng hay sai?"],["p","Theo câu chữ ghi là Hiến pháp có hiệu lực cao hơn ĐIều ước quốc tế là đúng."],["p","Tuy nhiên, lại có những điều nếu áp dụng quốc gia thì lại trái với quan điểm quốc tế hoặc áp dụng điều ước quốc tế là trái với luật qg. Cho nên ghi nhận trừ Hiến Pháp để đảm bảo tất cả điều ước mà VN tham gia không trái với Hiến Pháp, nâng cao ý thức của các cqnn có thể dự liệu ngay từ đầu, cân nhắc kĩ để vẫn có thể tuân thủ các cam kết quốc tế mà không trái với HP"],["p","Tập quán quốc tế là gì?: Huy"],["p","Tập quán quốc tế là những quy tắc xử sự hình thành trong thực tiễn quan hệ quốc tế được các quốc gia và các chủ thể khác của quan hệ quốc tế thừa nhận rộng rãi là những quy phạm pháp luật quốc tế để điều chỉnh quan hệ quốc gia"],["p","Để được công nhận là tập quán quốc tế thì một nguyên tắc xử sự chung phải được hai chủ thể luật quốc tế thừa nhận tính bắt buộc và áp dụng trong quan hệ giữa họ với nha"],["p","Điều kiện để Tập quán quốc tế trở thành nguồn của LQT? : Hoàng"],["p","Những thói quen quốc tế sẽ được công nhận và trở thành tập quán quốc tế khi thỏa mãn 3 yêu cầu sau"],["p","–Được áp dụng lặp đi lặp lại qua một thời gian dài trong thực tiễn pháp lý quốc tế."],["p","– Thừa nhận rộng rãi như những quy phạm pháp lý có tính chất bắt buộc."],["p","– Nội dung phù hợp với các nguyên tắc cơ bản của luật quốc tế hiện đại."],["p","Giá trị pháp lý và phương thức áp dụng tập quán quốc tế: Bảo Hân"],["p","Cùng với pháp luật quốc gia và điều ước quốc tế, tập quán quốc tế đóng vai trò quan trọng trong hoạt động thương mại quốc tế với tư cách là nguồn luật."],["p","Không phải bất cứ tập quán quốc tế nào cũng có thể được coi là nguồn luật của pháp luật quốc tế. Tập quán quốc tế chỉ được coi là nguồn của luật quốc tế khi nào thỏa mãn các điều kiện pháp lý nhất định (điều kiện được nêu ở phần 4)"],["p","Tập quán quốc tế có giá trị pháp lý như điều ước quốc tế. Việc áp dụng loại quy phạm nào của LQT sẽ tuỳ thuộc vào từng lĩnh vực và từng mqh cụ thể."],["p","Tập quán quốc tế có thể được áp dụng khi không có quy phạm điều ước quốc tế điều chỉnh hoặc các chủ thể LQT chọn lựa tập quán quốc tế để điều chỉnh."],["p","=> Nghĩa là: Trong trường hợp tranh chấp phát sinh nhưng hợp đồng do các bên ký kết không có điều khoản cụ thể về việc giải quyết tranh chấp, đồng thời luật trong nước và điều ước quốc tế liên quan cũng không có quy phạm điều chỉnh thì cơ quan xét xử có thể áp dụng tập quán quốc tế để giải quyết."],["p","Ngay trong lời mở đầu của Công ước Viên 1969 đã khẳng định rằng “những quy phạm của luật tập quán quốc tế sẽ tiếp tục điều chỉnh những vấn đề không đạt được điều chỉnh trong Công ước này”"],["p","=> các quốc gia chưa gia nhập công ước vẫn có thể viện dẫn các quy phạm của công ước dưới dạng các quy phạm tập quán."],["p","Ví dụ cụ thể về việc áp dụng tập quán quốc tế"],["p","Ở Anh, nếu như ĐƯQT không có hiệu lực thi hành trực tiếp trên lãnh thổ Anh và chúng chỉ trở thành một bộ phận của pháp luật Anh khi được chuyển hoá vào nội luật thông qua một đạo luật của Nghị viện, thì TQQT lại được coi là một bộ phận của pháp luật Anh và được Toà án áp dụng."],["p","Trước khi Công ước Luật biển 1982 ra đời, các quốc gia đã áp dụng một số điều trong công ước với tư cách là tập quán quốc tế như: chế độ qua lại vô hại của tàu thuyền nước ngoài trong vùng lãnh hải, quyền tài phán của quốc gia trong nội thuỷ nước mình…"],["p","Vụ Nicaragoa kiện Mỹ về việc tiến hành các hoạt động quân sự và bán quân sự tại Nicaragoa và chống lại Nicaragoa. Trong vụ kiện này Tòa án đã sử dụng luật tập quán để giải quyết tranh chấp giữa hai bên. Nicaragoa đã buộc tội Mỹ sử dụng vũ lực và đe dọa sử dụng vũ, vi phạm 4 công ước mà hai bên đều tham gia, nhất là Hiến chương LHQ và Hiến chương của Tổ chức các nước châu mỹ, tòa cũng phải xem xét đến lập luận của Mỹ về việc thực hiện quyền tự vệ tập thể chính đáng có lợi cho En Xanvado. Tranh chấp ở đây rõ ràng là một cuộc tranh chấp về việc giải thích và áp dụng một điều ước đa phương mà cả Mỹ, Nicaragoa và En Xavando đều là thành viên của điều ước đó. Tuy nhiên bảo lưu của Mỹ không cho phép tòa có thẩm quyền giải quyết tranh chấp trong việc áp dụng và giải thích các điều ước quốc tế đó như là nguồn của luật điều ước. Vì thế mà tập quán quốc tế đã được tòa án viện dẫn để giải quyết tranh chấp giữa Mỹ và Nicaragua, tòa kết luận Mỹ vi phạm các nguyên tắc tập quán của luật quốc tế về cấm sử dụng vũ lực và đe dọa sử dụng vũ lực trong quan hệ quốc tế cũng như cấm can thiệp vào công việc nội bộ của một quốc gia khác."],["p","So sánh ĐƯQT và TQQT? : Gia Hân"],["p","Điểm giống nhau:"],["p","Chủ thể để xd nên ĐƯQT và TQQT đều là chủ thể của luật quốc tế: quốc gia, các tổ chức qte liên cp, các dtoc đang đấu tranh giành quyền tự quyết. Trong các chủ thể này thì có thể khẳng định quốc gia chính là chủ thể trước tiên và chủ yếu hình thành nên Đưqt và Tqqt"],["p","Chúng đều hình thành từ sự thỏa thuận của các chủ thể lqt trên cơ sở bình đẳng, tự nguyện"],["p","Đều là nguồn chứa đựng quy phạm pháp luật quốc tế mang tính bắt buộc các chủ thể của lqt phải thi hành"],["p","Đều có giá trị pháp lý ngang bằng nhau"],["p","Đều phù hợp với các nguyên tắc cơ bản của lqt"],["p","Điểm khác nhau:"],["t",[["Tiêu chí so sánh","Điều ước quốc tế","Tập quán quốc tế"],["Hình thức","Hình thức của ĐƯQT là văn bản - nguồn thành văn, các công ước, hiệp ước, hiệp định, hòa ước, thỏa ước, thỏa tước, nghị định thư, hiến chương, quy chế…","Là những quy tắc xử sự “ bất thành văn”."],["Về phương thức hình thành","ĐƯQT được hình thành dựa trên sự thỏa thuận, bình đẳng của hai hay nhiều chủ thể của luật quốc tế thông qua quá trình đàm phán, ký kết rất chặt chẽ gồm đàm phán, soạn thảo và thông qua văn bản điều ước , ký , phê chuẩn hoặc phê duyệt.","Tập quán quốc tế ra đời thông qua quá trình hình thành áp dụng lâu dài, ổn định và thống nhất. Hinh thành từ nghị quyết của tổ chức quốc tế, từ tiền lệ, từ các hành vi pháp lý đơn phương của quốc gia, từ thực tiễn thực hiện điều ước quốc tế. -> Tqqt được hình thành sớm hơn"],["Sửa đổi, bổ sung","Vấn đề sửa đổi, bổ sung trong điều ước đơn giản hơn rất nhiều so với tập quán, vì điều ước tồn tại dưới hình thức văn bản.","Vấn đề sửa đổi, bổ sung trong lâu dài hơn rất nhiều so với điều ước quốc tế."],["Giá trị áp dụng","Có giá trị áp dụng chiếm ưu thế hơn","Có giá trị áp dụng thấp hơn điều ước quốc tế."],["Điều kiện có hiệu lực","- Được ký kết phải phù hợp với thủ tục thẩm quyền theo quy định của các bên ký kết - phải có nội dung phù hợp với các nguyên tắc cơ bản của luật quốc tế","- Tập quán quốc tế phải được thừa nhận rộng rãi như những quy phạm mang tính bắt buộc. - Tập quán quốc tế phải có nội dung phù hợp với các nguyên tắc cơ bản của luật quốc tế"]]],["p","-> Trong trường hợp hai bên xảy ra tranh chấp quốc tế thì sử dụng đưqt hay tqqt"],["p","- Tùy theo sự thỏa thuận của các bên sử dụng đuqt hay tqqt"],["p","- Thông thường sẽ ưu tiên áp dụng đuqt vì những ưu điểm của nó"],["p","Hãy kể tên các phương tiện bổ trợ cho nguồn của LQT và lý giải ngắn gọn: Đạt"],["p","Các phương tiện bổ trợ nguồn:"],["p","Những nguyên tắc pháp luật chung :là những nguyên tắc mang tính chất pháp lý kỹ thuật được ghi nhận trong hầu hết các hệ thống pháp luật trên thế giới và được các cơ quan tài phán quốc tế áp dụng trong trường hợp không có các nguyên tắc và các quy phạm luật quốc tế. Ví dụ: Nguyên tắc luật chung thay thế nguyên tắc luật riêng, luật sau thay thế luật trước. Nguyên tắc không ai là thẩm phán trong vụ việc của chính mình."],["p","Phán quyết của Tòa án Công lý quốc tế và các thiết chế tài phán quốc tế là các phán quyết giải quyết tranh chấp do các cơ quan tài phán quốc tế đưa ra có vai trò làm sáng tỏ hoặc là cơ sở hình thành điều ước quốc tế và tập quán quốc tế."],["p","Nghị quyết của các tổ chức quốc tế liên chính phủ là những văn bản không có giá trị pháp lý ràng buộc. Do các tổ chức quốc tế đưa ra nhằm giải thích hoặc giải quyết một số vấn đề của luật quốc tế."],["p","Học thuyết,các công trình nghiên cứu của các học giả luật quốc tế là các hành vi pháp luật có tính chất quốc tế về cả hai phương diện hình thức và nội dung do cơ quan nhà nước có thẩm quyền thực hiện, có mục đích tạo ra các kết quả nhất định trong các quan hệ quốc tế."],["p","Hành vi pháp lý đơn phương của một quốc gia là hành vi do các chủ thể có thẩm quyền của quốc gia thể hiện nhằm mục đích xác lập về quyền và nghĩa vụ pháp lý cho quốc gia."],["p","Tại sao lại gọi là phương tiện bổ trợ? ( nói tầm quan trọng): Đoàn. Gọi là phương tiện bổ trợ vì:"],["p","Nó là cơ sở hình thành nên nguồn cơ bản(ĐƯQT,TQQT). Là phương tiện giải thích, làm sáng tỏ nội dung của nguồn cơ bản. Nó được sử dụng để điều chỉnh các quan hệ luật quốc tế trong trường hợp không có nguồn cơ bản điều chỉnh."],["p","Các phương tiện bổ trợ không thể là nguồn của Luật quốc tế vì:"],["p","Đối với các phán quyết của tòa án công lý: không chứa đựng các nguyên tắc, các quy phạm của lqt mà chỉ áp dụng trọng những quốc gia, vụ việc cụ thể."],["p","Hành vi ply đơn phương cả qg: chỉ có giá trị đối với quốc gia đưa ra tuyên bố đó thôi."],["p","Các nghị quyết của tổ chức quốc tế liên chính phủ: về mặt nguyên tắc thì có hai nghị quyết: mang tính khuyến nghị và bắt buộc. Khuyến nghị thì không bàn tới còn bắt buộc thì nó chỉ áp dụng cho các quốc gia trong tổ chức qte liên chính phủ"],["p","Các học thuyết về luật quốc tế chỉ là phương tiện mà không phải là nguồn của luật quốc tế vì đó không phải là văn bản pháp lý ràng buộc giữa các quốc gia, bản thân nó không chứa đựng các qppl, không làm phát sinh quyền và nghĩa vụ giữa các chủ thể với nhau trong qhqt và không có sự công nhận giữa các quốc gia."],["p","Các nguyên tắc pháp luật chung do các dân tộc văn minh thừa nhận: là nguồn của luật quốc tế. Tuy nhiên, cho đến nay chưa có văn bản nào chỉ rõ những nguyên tắc nào là những nguyên tắc pháp luật chung được các dân tộc văn minh thừa nhận."],["p","Điều kiện chung để trở thành nguồn của LQT: Bảo Hân"],["p","- Là văn bản quy phạm pháp luật quốc tế có nội dung phù hợp với 7 nguyên tắc cơ bản của Luật quốc tế"],["p","- Đạt được sự thỏa thuận, thừa nhận của chính các chủ thể của luật quốc tế trên cơ sở tự nguyện, bình đẳng"],["p","- Là quy phạm có tính bắt buộc chung các chủ thể của luật quốc tế phải thi hành"]]}]},{"t":"DÂN CƯ TRONG LUẬT QUỐC TẾ","n":3,"g":[{"h":"","b":[["p","Hai bộ phận cấu thành dân cư : Nhị Hoàng"],["p","Dân cư là người dân sống chủ yếu trong một quốc gia nhất định và tuân thủ pháp luật của quốc gia đó. Dân cư được chia làm hai đối tượng"]]},{"h":"1.1 Công dân nước sở tại","b":[["p","Công dân nước sở tại ( người mang quốc tịch của quốc gia đó): là bộ phận quan trọng nhất và chiếm đại đa số trong thành phần dân cư của một quốc gia. Về mặt nguyên tắc, công dân của một quốc gia chịu sự điều chỉnh của pháp luật của quốc gia mà họ đang mang quốc tịch.Tuy nhiên có một bộ phận công dân của một quốc gia nhưng đang sinh sống và làm việc tại nước ngoài."],["p","Trong trường hợp đặc biệt( người có hai hoặc nhiều quốc tịch trong đó có quốc tịch của nước đang cư trú) một cá nhân có thể được điều chỉnh bởi pháp luật của những quốc gia mà họ đồng thời mang quốc tịch."]]},{"h":"1.2 Người nước ngoài sinh sống trên lãnh thổ nước sở tại:","b":[["p","Người mang quốc tịch nước ngoài bao gồm người mang hai quốc tịch hoặc nhiều quốc tịch, không quốc tịch. Bộ phận dân cư này vừa chịu sự điều chỉnh của pháp luật quốc gia đang cư trú đồng thời chịu sự điều chỉnh của pháp luật của quốc gia mà họ là công dân. Hiện nay \"người nước ngoài\" còn bao gồm những người không quốc tịch, đây là những người không có một quốc tịch nào, họ là những người được hưởng quy chế pháp lý do quốc gia nơi họ đang cư trú quy định. Người không quốc tịch chỉ chịu sự điều chỉnh của pháp luật của quốc gia họ đang cư trú."],["p","Ví dụ: A là người Mĩ hiện đang làm việc tại Việt Nam. A phải chịu sự điều chỉnh của pháp luật đồng thời của Việt Nam và Mĩ."],["p","CSPL: Khoản 5 điều 13 Luật quốc tịch VN 2008"],["p","-> Bộ phận nào chiếm đại đa số quan trọng nhất? Vì sao?"],["p","=> công dân chiếm đại đa số trong thành phần dân cư của một quốc gia. Vì người sở tại là cư dân chiếm đại đa số ở quốc gia đó còn người nước ngoài chỉ là 1 bộ phận dân cư nhỏ nhập cư đến nhằm sinh sống, làm việc và du lịch."],["p","Quốc tịch"]]},{"h":"2.1 Bốn đặc điểm cấu thành quốc tịch : Cơ","b":[["p","Quốc tịch mang tính ổn định, bền vững:"],["p","Về mặt không gian: không bị thay đổi, mất đi do sự thay đổi cư trú. Dù cư trú ở đâu về mối quan hệ quốc tịch, cá nhân cũng được hưởng các quyền và gánh vác nghĩa vụ như nhau."],["p","CSPL: Khoản 1 Điều 31 Luật quốc tịch VN -> Đã là công dân VN nhưng vi phạm nghiêm trọng đến nhà nước CHXHCN VN thì sẽ bị tước quốc tịch VN"],["p","Điều 44 Hiến Pháp 2013 quy định: Công dân có nghĩa vụ phải trung thành với Tổ quốc"],["p","-> Công dân VN dù sống ở lãnh thổ nào cũng phải trung thành với Tổ quốc VN"],["p","Về mặt thời gian: Quốc tịch sẽ gắn với cá nhân từ lúc sinh ra cho đến khi chết đi; mối liên hệ quốc tịch chỉ có thể thay đổi trong những trường hợp nhất định, với những điều kiện hết sức khắt khe."],["p","Quốc tịch là cơ sở phát sinh các quyền và nghĩa vụ giữa công dân và quốc gia: các quyền và nghĩa vụ cơ bản của công dân là những quyền và nghĩa vụ bao trùm nhất và đầy đủ nhất mà không một bộ phận dân cư nào khác có được. quốc tịch được hiểu là mối liên hệ pháp lý- chính trị của một cá nhân với một quốc gia mà không phải với chính quyền của quốc gia đó."],["p","CSPL: * Điều 45 Hiến pháp 2013 quy định về nghĩa vụ quân sự"],["p","Điều 27 HP 2013 quy định về quyền bầu cử -> người dân được nhà nước tạo điều kiện từ đủ 18t được bầu cử và từ đủ 21t được ứng cử"],["p","Điều 6 Luật quốc tịch Việt Nam 2008 sđ, bs 2014 quy định Bảo hộ Việt Nam đối với công dân ở nước ngoài."],["p","Tính cá nhân của Quốc tịch: Quốc tịch gắn bó với bản thân cá nhân mang quốc tịch. Việc thay đổi quốc tịch của một người không làm quốc tịch của người khác thay đổi theo."],["p","CSPL: Điều 9, 10 Luật quốc tịch VN; Khoản 1 điều 37 Luật Quốc tịch VN quy định Trẻ em là công dân Việt Nam được người nước ngoài nhận làm con nuôi thì vẫn giữ quốc tịch Việt Nam."],["p","Quốc tịch có ý nghĩa pháp lý quốc tế:"],["p","Là cơ sở để một quốc gia tiến hành bảo hộ ngoại giao cho công dân mình"],["p","CSPL: Điều 3 Dự thảo các điều luật về bảo hộ ngoại giao (do UBPLQT đưa ra 2006)"],["p","Điều 6 Luật quốc tịch Việt Nam 2008 quy định Bảo hộ Việt Nam đối với công dân ở nước ngoài."],["p","Vd: 39 công dân VN bị mất ở nước Anh, thì công an Việt Nam"],["p","Quốc tịch là cơ sở để quốc gia thực hiện trách nhiệm pháp lý quốc tế đối với những quốc gia khác liên quan đến hành vi của những người mang quốc tịch quốc gia mình thực hiện"],["p","Quốc tịch là cơ sở để từ chối dẫn độ tội phạm đối với công dân mình( trừ những trường hợp điều ước quốc tế quy định rõ cụ thể)"],["p","Quốc tịch cũng là cơ sở để quốc gia xác định thẩm quyền Tài Phán đối với một số cá nhân trong trường hợp có sự xung đột về thẩm quyền và xét xử hành vi cho cá nhân thực hiện."],["p","Câu hỏi:"],["p","Phân biệt bảo hộ ngoại giao với bảo hộ công dân : Gia Hân"],["p","-> Bảo hộ cd chỉ đặt ra đv cd của qg khi ở nước ngoài"],["p","- Khái niệm:"],["p","Bảo hộ ngoại giao là sự bảo hộ thông qua cơ quan đại diện ngoại giao hay lãnh sự của một quốc gia đối với công dân nước mình ở nước ngoài, khi các quyền lợi dân sự, lao động, hôn nhân và gia đình… của họ bị vi phạm."],["p","Theo nghĩa hẹp: Bảo hộ công dân là hoạt động của cơ quan nhà nước có thẩm quyền bảo vệ quyền và lợi ích của công dân nước mình ở nước ngoài, khi các quyền và lợi ích này bị xâm hại ở nước ngoài."],["p","Theo nghĩa rộng: Bảo hộ công dân bao gồm cả các hoạt động giúp đỡ về mọi mặt mà nhà nước dành cho công dân của nước mình đang ở nước ngoài, kể cả trong trường hợp không có hành vi xâm hại nào tới các công dân của nước này."],["p","2. Bảo hộ công dân có phải được áp dụng với tất cả công dân của một quốc gia kể cả trong nước và ngoài nước?: Hoàng"],["p","Thẩm quyền bảo hộ công dân: Dựa trên cơ sở cơ cấu tổ chức và phạm vi hoạt động của các cơ quan nhà nước có thẩm quyền bảo hộ công dân, có thể chia các cơ quan này ra làm 2 loại: cơ quan có thẩm quyền trong nước và cơ quan có thẩm quyền nước ngoài."],["p","– Cơ quan có thẩm quyền bảo hộ trong nước: hầu hết các quốc gia đều thực hiện việc bảo hộ công dân thông qua Bộ ngoại giao. Bộ ngoại giao chịu trách nhiệm trước chính phủ về các hoạt động bảo hộ công ở trong nước cũng như nước ngoài."],["p","– Cơ quan có thẩm quyền bảo hộ ở nước ngoài: Theo nguyên tắc chung, thẩm quyền bảo hộ công dân nước mình ở nước ngoài thuộc về các cơ quan đại diện ngoại giao, cơ quan lãnh sự của nước cử đại diện tại nước nhận đại diện. Việc bảo hộ công dân do các cơ đại diện thực hiện được ghi nhận trong công ước Viên năm 1961 về quan hệ ngoại giao và công ước Viên năm 1963 về quan hệ lãnh sự."],["p","– Để được một quốc gia nào đó bảo hộ, đối tượng được bảo hộ phải thỏa mãn các điều kiện sau:"],["p","+ Đối tượng bảo hộ là công dân của quốc gia tiến hành bảo hộ. Tuy nhiên trên thực tế có trường hợp một người có quốc tịch của quốc gia đó nhưng không được bảo hộ (ví dụ: trường hợp người có 2 hay nhiều quốc tịch, không được bảo hộ nếu sự bảo hộ đó chống lại quốc gia mà người này cũng mang quốc tịch); cũng có trường hợp một người không mang quốc tịch của quốc gia này nhưng lại được quốc gia đó bảo hộ trong trường hợp bị xâm phạm. (ví dụ: Đối với công dân thuộc Liên minh Châu Âu)."],["p","Khi quyền lợi hợp pháp của đối tượng bảo hộ bị xâm hại"],["p","+ Đã áp dụng các biện pháp tự bảo vệ trên thực tế theo pháp luật của nước sở tại: như: yêu cầu đòi bồi thường để khắc phục thiệt hại nhưng không mang lại kết quả…"],["p","=> bảo hộ công dân không phải áp dụng với tất cả công dân của một quốc gia trong nước và ngoài nước."]]},{"h":"3. Có phải trong mọi trường hợp quốc gia có trường hợp từ chối dẫn độ tội phạm hay không? : Huyền Cơ","b":[["p","TL: Điều 33 Luật tương trợ Tư pháp 2007 quy định Trường hợp bị dẫn độ"],["p","Được từ chối dẫn độ được quy định trong Điều 35 Luật tương trợ Tư pháp 2007 quy định về Từ chối dẫn độ tội phạm. Tuy nhiên, có một số trường hợp vẫn bị dẫn độ Điều 33 Luật tương trợ Tư pháp 2007 quy định Trường hợp bị dẫn độ."],["p","Ngoại lệ của nguyên tắc không dẫn độ người phạm tội về chính trị như: thủ phạm giết hại nguyên thủ quốc gia, người đứng đầu Chính phủ hoặc các nhà lãnh đạo cao cấp khác của quốc gia không được hưởng quyền không bị dẫn độ khi đã thực hiện hành vi phạm tội."]]},{"h":"2.2 Năm cách thức được hưởng quốc tịch: Đoàn","b":[["p","Hưởng quốc tịch theo sự sinh đẻ: ( phổ biến nhất)"],["p","Đây là căn cứ phổ biến nhất, dùng để xác định quốc tịch cho trẻ em khi sinh ra, có 2 nguyên tắc xác định và nó phụ thuộc vào ý chí của quốc gia mà cá nhân mang quốc tịch:"],["p","+ Nguyên tắc huyết thống: đứa trẻ sinh ra có quốc tịch theo quốc tịch của cha mẹ bất kể sinh ra ở đâu. Nguyên tắc này được áp dụng ở hầu hết các nước châu Âu như Italia, Phần Lan,..."],["p","CSPL: Việt Nam áp dụng nguyên tắc chủ đạo là nguyên tắc huyết thống được quy định tại: điều 15 Luật quốc tịch VN 2008, sđ bổ sung 2014 - trẻ em sinh ra có cha mẹ là công dân VN thì có quốc tịch VN"],["p","Điều 16 Luật quốc tịch VN - trẻ em sinh ra mà có cha hoặc mẹ là công dân VN còn người kia là người không quốc tịch hoặc có mẹ là quốc tịch VN còn cha không rõ thì có quốc tịch VN."],["p","Khoản 2 Điều 16 Luật quốc tịch VN trường hợp cha mẹ không thỏa thuận được thì đứa trẻ sinh ra trên lãnh thổ VN có quốc tịch VN."],["p","-> Hạn chế của của quốc gia chỉ quy định nguyên tắc huyết thống: cha mẹ không quốc tịch dẫn đến con không có quốc tịch; hoặc cha mẹ khác quốc tịch dẫn đến tình trạng con có hai hay nhiều quốc tịch."],["p","+ Nguyên tắc nơi sinh: trẻ em sẽ mang quốc tịch của một quốc gia nếu sinh ra trên lãnh thổ quốc gia đó không phụ thuộc quốc tịch cha mẹ. Nguyên tắc này được áp dụng phổ biến và triệt để ở các nước châu Mỹ như Chi Lê, Brazil, Canada,..."],["p","CSPL: Điều 17 Luật quốc tịch Vn - trẻ em sinh ra trên lãnh thổ VN mà cha mẹ đều là người không có quốc tịch nhưng có nơi thường trú tại VN thì có quốc tịch VN"],["p","Điều 18 Luật quốc tịch VN - trẻ sơ sinh bị bỏ rơi, trẻ em được tìm thấy trên lãnh thổ VN mà không rõ cha mẹ là ai thì có quốc tịch VN."],["p","Khoản 2 Điều 18. Trẻ em quy định tại khoản 1 Điều này chưa đủ 15 tuổi không còn quốc tịch Việt Nam trong các trường hợp sau đây:"],["p","a) Tìm thấy cha mẹ mà cha mẹ chỉ có quốc tịch nước ngoài;"],["p","b) Chỉ tìm thấy cha hoặc mẹ mà người đó chỉ có quốc tịch nước ngoài."],["p","-> Các quy định này xuất phát từ chính sách nhân đạo đối với những trường hợp trẻ em không quốc tịch để cho em có quốc tịch và được hưởng quyền lợi của quốc gia."],["p","=> Ngoài việc ký kết Điều ước quốc tế giữa các quốc gia, đa số quốc gia áp dụng cả 2 nguyên tắc để hạn chế tình trạng không quốc tịch hoặc hai hay nhiều quốc tịch. Ví dụ như Ba Lan, Việt Nam,..v..v"],["p","Hưởng quốc tịch theo sự gia nhập quốc tịch: ( phổ biến thứ 2)"],["p","Áp dụng với người không quốc tịch, người nước ngoài nhưng muốn thay đổi quốc tịch, hoặc trường hợp quốc gia cho phép người đã có quốc tịch muốn thêm quốc tịch của quốc gia đó. Việc trao quốc tịch được sự cho phép của cơ quan có thẩm quyền và thực hiện theo trình tự luật định"],["p","Điều kiện cơ bản: 5 điều kiện"],["p","+ Đạt độ tuổi nhất định: thông thường đây là tuổi có năng lực hành vi đầy đủ ( ở Việt Nam từ đủ 18 tuổi trở lên có năng lực hành vi đầy đủ )"],["p","+ Có thời gian cư trú nhất định."],["p","Theo điểm d khoản 1 điều 19 Luật quốc tịch VN thì công dân nước ngoài cần phải thường trú tại VN từ 5 năm trở lên tính đến thời điểm xin nhập quốc tịch ( ở Mỹ, Anh, Thuỵ Điển, Đức,… cũng áp dụng thời gian từ 5 năm trở lên; còn ở Nhật, Thuỵ Sĩ là 10 năm; ở Lucxambua là 15 năm… )"],["p","Điều 20 là Hồ sơ nhập quốc tịch"],["p","+ Biết ngôn ngữ và có khả năng hòa nhập vào cộng đồng."],["p","Điểm b Điều 10 NĐ 16/2020 NĐ-CP quy định người không có giấy tờ chứng minh trình độ tiếng Việt có thể đóng tiền đi test trình độ tại Sở Tư Pháp hoặc đi học tại Đại học KHXH và NV"],["p","+ Điều kiện về chính trị-văn hóa: có hiểu biết nhất định về văn hóa-xã hội của nước nơi mình nhập quốc tịch. Nhằm đảm bảo việc tuân thủ pháp luật cũng như hòa nhập vào đời sống chính trị-xh ở quốc gia sở tại"],["p","+ Đủ điều kiện sức khỏe, khả năng kinh tế. Ngoài ra, một số nước áp dụng nguyên tắc một quốc tịch, nếu xin gia nhập quốc tịch, đương sự phải mất quốc tịch cũ."],["p","Tại điều 19 Luật quốc tịch VN cũng có quy định người nhập quốc tịch Việt Nam thì phải thôi quốc tịch nước ngoài, trừ một số trường hợp do luật định"],["p","Ngoài ra hưởng quốc tịch có thể xuất phát từ sự kiện kết hôn ( điểm a khoản 2 Điều 19 Luật Quốc tịch VN) hoặc nhận con nuôi. (trường hợp trẻ em được nhận nuôi bởi công dân VN cũng được nhập tịch VN quy định tại khoản 2,3 điều 37 Luật quốc tịch VN )"],["p","CSPL : Luật quốc tịch VN có quy định điều kiện và trình tự, thủ tục giải quyết hồ sơ xin nhập tịch VN tại các điều 19,20,21,22"],["p","Câu hỏi: Anh Nhập quốc tịch ở VN có bắt buộc phải thôi quốc tịch cũ không?"],["p","->Về nguyên tắc thì sau khi nhập quốc tịch Việt Nam phải thôi quốc tịch cũ nhưng Theo khoản 2 Điều 19 Luật Quốc tịch VN thì anh cưới vợ VN sẽ không cần phải thôi quốc tịch cũ."],["p","Hưởng quốc tịch theo sự lựa chọn quốc tịch:"],["p","+ Khi có sự thay đổi về chủ quyền lãnh thổ: chuyển nhượng, trao đổi lãnh thổ, phân chia, hợp nhất lãnh thổ quốc gia."],["p","+ Khi có sự di chuyển dân cư (trao đổi dân cư)."],["p","Ví dụ : Hiệp định ngày 6/7/1945 giữa Liên Xô (cũ) và Chính phủ lâm thời của Mặt trận dân tộc thống nhất Ba Lan có quy định việc người Ba Lan và người Do Thái có quốc tịch Ba Lan trước đó hiện đang cư trú trên lãnh thổ Liên Xô có quyền rút quốc tịch Liên Xô và chuyển về Ba Lan. Tương tự, người Ucraina đang cư trú trên lãnh thổ Ba Lan có quyền rút quốc tịch Ba Lan và chuyển về Liên Xô."],["p","+ Khi một người có 2 hay nhiều quốc tịch mà quốc gia yêu cầu lựa chọn một trong số quốc tịch đó."],["p","Ví dụ : Điều 11 Luật quốc tịch Nhật Bản có quy định công dân Nhật Bản có quốc tịch nước ngoài sẽ mất quốc tịch Nhật Bản nếu lựa chọn quốc tịch nước khác."],["p","Hưởng quốc tịch theo sự phục hồi quốc tịch:"],["p","+ Người đã xin thôi quốc tịch để ra nước ngoài sinh sống nay trở về tổ quốc."],["p","+ Người bị mất quốc tịch do kết hôn với người nước ngoài hoặc được nhận làm con nuôi nay ly hôn hoặc hủy việc nhận con nuôi."],["p","CSPL : Điều 23,24,25 Luật quốc tịch VN có ghi rõ điều kiện cũng như thủ tục, hồ sơ để xin trở lại quốc tịch VN"],["p","Hưởng quốc tịch do thưởng quốc tịch:"],["p","Dành cho những người có công trạng lớn hoặc có lợi cho Việt Nam"],["p","VD: đầu tư lớn vào công ty lớn ở VN thì chỉ cần năng lực hvi dân sự đầy đủ và tuân thủ HP VN ( khoản 2 điều 19)"],["p","Hệ quả pháp lý:"],["p","+ Trở thành công dân thực sự, hưởng quyền và nghĩa vụ đầy đủ."],["p","+ Trở thành công dân danh dự, hưởng một số quyền nhất định, không đầy đủ."],["p","Ví dụ : Che Guevara là công dân Argentina đã được nhà nước Cuba tặng thưởng quốc tịch nước Cuba vì đã giữ nhiều trọng trách quan trọng trong chính phủ Cuba."],["p","George Washington cũng được Quốc hội Pháp tặng thưởng quốc tịch Pháp vì đã đóng góp lớn trong Cách mạng tư sản Pháp thế kỷ XVII."],["p","Những trường hợp khác có thể dẫn đến việc thay đổi quốc tịch của một công dân:"],["p","Đăng ký quốc tịch: thực chất là một dạng nhập tịch nhưng có điều kiện đơn giản hơn là điều kiện vào quốc tịch"],["p","Có quốc tịch thông qua hôn nhân: có quốc tịch theo vợ hoặc chồng. Tuy nhiên hiện nay Luật Quốc tịch các nước cho thấy việc kết hôn không tự động dẫn đến việc tự động nhập tịch"],["p","Có quốc tịch do làm con nuôi người nước ngoài: trẻ em có quốc tịch nước ngoài theo cha mẹ nuôi."],["p","Được công nhận quốc tịch: là hình thức có quốc tịch áp dụng đối với người có quan hệ gắn bó với một nước nào đó hoặc từng có quốc tịch một nước nào đó."]]},{"h":"2.3 Ba trường hợp chấm dứt mqh quốc tịch đối với quốc gia họ: Đạt","b":[["p","Thôi quốc tịch"],["p","- Căn cứ để xác định việc thôi quốc tịch Việt Nam được quy định tại khoản 1 Điều 27 Luật Quốc tịch"],["p","- Thôi quốc tịch là việc đương sự xin thôi quốc tịch xuất phát từ ý chí, nguyện vọng cá nhân."],["p","- Để được thôi quốc tịch đương sự phải làm đơn xin thôi quốc tịch gửi đến cơ quan nhà nước có thẩm quyền."],["p","- Việc xin thôi quốc tịch không chỉ phụ thuộc vào ý chí của cá nhân xin thôi quốc tịch mà còn phụ thuộc vào ý chí của nhà nước. Những người xin thôi quốc tịch Việt Nam thuộc các trường hợp sau đây sẽ chưa được thôi quốc tịch (khoản 2 Điều 27 Luật Quốc tịch Việt Nam)"],["p","2. Người xin thôi quốc tịch Việt Nam chưa được thôi quốc tịch Việt Nam, nếu thuộc một trong những trường hợp sau đây:"],["p","a) Đang nợ thuế đối với Nhà nước hoặc đang có nghĩa vụ tài sản đối với cơ quan, tổ chức hoặc cá nhân ở Việt Nam;"],["p","b) Đang bị truy cứu trách nhiệm hình sự;"],["p","c) Đang chấp hành bản án, quyết định của Toà án Việt Nam;"],["p","d) Đang bị tạm giam để chờ thi hành án;"],["p","đ) Đang chấp hành quyết định áp dụng biện pháp xử lý hành chính đưa vào cơ sở giáo dục, cơ sở chữa bệnh, trường giáo dưỡng."],["p","3. Người xin thôi quốc tịch Việt Nam không được thôi quốc tịch Việt Nam, nếu việc đó làm phương hại đến lợi ích quốc gia của Việt Nam."],["p","4. Cán bộ, công chức và những người đang phục vụ trong lực lượng vũ trang nhân dân Việt Nam không được thôi quốc tịch Việt Nam."],["p","5. Chính phủ quy định cụ thể các điều kiện được thôi quốc tịch Việt Nam."],["p","-Pháp luật các nước đều quy định một số điều kiện chủ yếu để xin thôi quốc tịch như:đã thực hiện đầy đủ nghĩa vụ thuế hoặc các nghĩa vụ tài chính cho quốc gia mà họ xin thoi quốc tịch,không phải thi hành các phán quyết dân sự,đã hoàn thành hoặc được miễn nghĩa vụ quân sự,..."],["p","Tước quốc tịch"],["p","- Điều 31 Luật Quốc tịch Việt Nam năm 2008 (được sửa đổi, bổ sung năm 2014), Điều 22 Nghị định số 16/2020/NĐ-CP quy định căn cứ tước quốc tịch Việt Nam"],["p","Điều 31. Căn cứ tước quốc tịch Việt Nam"],["p","1. Công dân Việt Nam cư trú ở nước ngoài có thể bị tước quốc tịch Việt Nam, nếu có hành vi gây phương hại nghiêm trọng đến nền độc lập dân tộc, đến sự nghiệp xây dựng và bảo vệ Tổ quốc Việt Nam hoặc đến uy tín của nước Cộng hoà xã hội chủ nghĩa Việt Nam."],["p","2. Người đã nhập quốc tịch Việt Nam theo quy định tại Điều 19 của Luật này dù cư trú ở trong hoặc ngoài lãnh thổ Việt Nam cũng có thể bị tước quốc tịch Việt Nam, nếu có hành vi quy định tại khoản 1 Điều này."],["p","- Tước quốc tịch là biện pháp trừng phạt của nhà nước áp dụng đối với công dân nước mình do những hành vi vi phạm nghiêm trọng pháp luật,làm phương hại đến lợi ích và uy tín của quốc gia."],["p","- Pháp luật các nước thường có những quy định về việc tước quốc tịch của một cá nhân do những hành vi như:phản bội tổ quốc, xúc phạm dân tộc, gián điệp, tham gia quân đội,chính quyền nước khác mà không được sự đồng ý của nhà nước…"],["p","- Tuy nhiên việc tước quốc tịch phải được áp dụng một cách hợp lí,đảm bảo phù hợp với luật pháp quốc tế.Ví dụ như :hạn chế tình trạng người không quốc tịch;tước quốc tịch đối với một nhóm người vì lí do tôn giáo,sắc tộc,chính trị khác,..."],["p","Tước quốc tịch không phải là chế tài hình sự, chỉ là biện pháp trừng phạt của nhà nước trong trường hợp họ không còn xứng đáng với danh hiệu công dân"],["p","Tự động(đương nhiên) mất quốc tịch"],["p","- Điều 33 Luật Quốc tịch Việt Nam năm 2008 (được sửa đổi, bổ sung năm 2014), Điều 23 Nghị định số 16/2020/NĐ-CP quy định Căn cứ hủy bỏ Quyết định cho nhập quốc tịch Việt Nam gồm"],["p","- Là việc một người tự động mất quốc tịch khi rơi vào các trường hợp mà pháp luật đã quy định trước."],["p","- Cơ sở của áp dụng mất quốc tịch không nhất thiết phải là các hành vi vi phạm pháp luật nghiêm trọng mà nhằm mục đích tránh rắc rối trong việc có 2 quốc tịch hoặc đơn giản là mối quan hệ quốc tịch này không thể tiếp tục tồn tại.Chẳng hạn như:có quốc tịch khác,cư trú ở nước ngoài và không trở lại trong thời gian xác định,..."],["p","- Ngoài ra, tự động mất quốc tịch theo các điều ước quốc tế được cho là một trường hợp khác của tự động mất quốc tịch.Cụ thể,công dân mất đi quốc tịch khi các nước có sự thay đổi về lãnh thổ hoặc có sự di chuyển của một bộ phận dân cư.Nhằm hạn chế người có 2 quốc tịch,những trường hợp này sẽ tự động mất đi quốc tịch cũ và giữ quốc tịch mới"]]},{"h":"2.4 Khái niệm và nguyên nhân của tình trạng hai quốc tịch , Nhiều quốc tịch?","b":[["p","Khái niệm tình trạng hai quốc tịch"],["p","Hai quốc tịch là tình trạng một người cùng lúc có hai quốc tịch, nói cách khác, pháp luật của cả hai nước đều coi người đó là công dân mình đồng thời đòi hỏi ở công dân ấy những nghĩa vụ đối với nhà nước."],["p","Tình trạng hai quốc tịch là một thực tế ở hầu hết các quốc gia trên thế giới và có nhiều quốc gia hiện nay không cấm hoặc cho phép công dân có hai quốc tịch, bởi nó đem lại nhiều bất lợi trong quan hệ quốc tế. Nhìn chung, trạng thái hai quốc tịch xuất hiện do các nguyên nhân sau:"],["p","Trẻ em được sinh ra trên lãnh thổ quốc gia có luật quốc tịch áp dụng nguyên tắc luật nơi sinh đồng thời cha mẹ đứa trẻ lại là công dân của nước có luật quốc tịch áp dụng nguyên tắc huyết thống."],["p","Ví dụ: A có cha mẹ là công dân của nước áp dụng nguyên tắc huyết thống (Việt Nam) sinh ra trên lãnh thổ của nước áp dụng nguyên tắc nơi sinh (Mỹ). Do vậy theo luật của Mỹ đứa trẻ sẽ mang quốc tịch Mỹ, theo luật của Việt Nam thì đứa trẻ cũng có quốc tịch của Việt Nam."],["p","Nhà nước theo tình trạng huyết thống mà cha mẹ mang hai quốc tịch khác nhau -> con có nhiều quốc tịch."],["p","Trường hợp nhận con nuôi của người nước ngoài: điều 37"],["p","Trường hợp kết hôn với người nước ngoài: Điều 9 LQT VN về việc giữ quốc tịch khi kết hôn với người nước ngoài"],["p","Vào quốc tịch mới nhưng chưa thôi quốc tịch cũ: phổ biến ở các kiều bào VN ở nước ngoài"],["p","Trường hợp quốc gia thưởng quốc tịch trong trường hợp quốc gia đó không buộc công dân phải thôi quốc tịch cũ. Ví dụ : Che Guevara là công dân Argentina đã được nhà nước Cuba tặng thưởng quốc tịch nước Cuba vì đã giữ nhiều trọng trách quan trọng trong chính phủ Cuba"],["p","Bất lợi của người nhiều quốc tịch:"],["p","Cùng lúc họ phải gánh vác quyền của và nghĩa vụ của qg mà họ là công dân"],["p","Cd không được bảo hộ đối với một quốc gia mà quốc gia đó cũng là quốc gia mà công dân mang quốc tịch"],["p","VD: Khi chiến tranh giữa VN và Mỹ -> việc xác lập việc bảo hộ đến từ sự thỏa thuận của 2 qg theo nguyên tắc hữu hiệu (cd đó cống hiến cho nước nào nhiều hơn), nếu không thỏa thuận được thì hai bên sẽ thỏa thuận xđ bên thứ 3 ( pháp, trọng tài quốc tế) giải quyết."],["p","2.6 Pháp luật Việt Nam có trường hợp nhiều quốc tịch không (thực trạng)? Nguyên nhân nào mà VN có nhiều quốc tịch? :"],["p","Pháp luật Việt Nam quy định thế nào về người có nhiều quốc tịch : Bảo Hân"],["p","Về mặt nguyên tắc, nước VN công nhận công dân VN có một quốc tịch là quốc tịch VN. (Theo điều 4 Luật quốc tịch VN). Tuy nhiên cũng có trường hợp Việt Nam cho phép công dân mang hai quốc tịch, song đó phải là những trường hợp đặc biệt và được Chủ tịch nước cho phép."],["p","Trường hợp được 2 quốc tịch"]]},{"h":"1. Trường hợp người Việt Nam định cư ở nước ngoài nhưng vẫn còn quốc tịch Việt Nam","b":[["p","Theo khoản 2 Điều 13 Luật Quốc tịch Việt Nam 2008 quy định:"],["p","Người Việt Nam định cư ở nước ngoài mà chưa mất quốc tịch Việt Nam theo quy định của pháp luật Việt Nam trước ngày 01/7/2009 thì vẫn còn quốc tịch Việt Nam."]]},{"h":"2. Trường hợp được nhập quốc tịch Việt Nam mà không phải thôi quốc tịch nước ngoài","b":[["p","- Theo khoản 3 Điều 19 Luật Quốc tịch Việt Nam 2008 quy định, người nhập quốc tịch Việt Nam nhưng không phải thôi quốc tịch nước ngoài trong các trường hợp:"],["p","+ Là vợ, chồng, cha đẻ, mẹ đẻ hoặc con đẻ của công dân Việt Nam;"],["p","+ Có công lao đặc biệt đóng góp cho sự nghiệp xây dựng và bảo vệ Tổ quốc Việt Nam;"],["p","+ Có lợi cho Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam."],["p","- Theo Điều 9 Nghị định 16/2020/NĐ-CP quy định, người xin nhập quốc tịch Việt Nam nhưng không phải thôi quốc tịch nước ngoài và trình Chủ tịch nước xem xét nếu đáp ứng đầy đủ các điều kiện sau đây:"],["p","+ Có đủ điều kiện nhập quốc tịch Việt Nam theo quy định của Luật Quốc tịch Việt Nam 2008."],["p","+ Có công lao đặc biệt đóng góp cho sự nghiệp xây dựng và bảo vệ tổ quốc Việt Nam và việc nhập quốc tịch đồng thời giữ quốc tịch nước ngoài là có lợi cho Nhà nước Cộng hòa xã hội Chủ nghĩa Việt Nam.``"],["p","+ Việc xin giữ quốc tịch nước ngoài của người đó khi nhập quốc tịch Việt Nam là phù hợp với pháp luật của nước ngoài đó."],["p","+ Việc thôi quốc tịch nước ngoài dẫn đến quyền lợi của người đó ở nước ngoài bị ảnh hưởng."],["p","+ Không sử dụng quốc tịch nước ngoài để gây phương hại đến quyền, lợi ích hợp pháp của cơ quan, tổ chức và cá nhân; xâm hại an ninh, lợi ích quốc gia, trật tự, an toàn xã hội của Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam."]]},{"h":"3. Trường hợp người xin trở lại quốc tịch Việt Nam nhưng không phải thôi quốc tịch nước ngoài","b":[["p","- Theo khoản 5 Điều 23 Luật Quốc tịch Việt Nam 2008 quy định, người được trở lại quốc tịch Việt Nam nhưng không phải thôi quốc tịch nước ngoài trong các trường hợp sau đây:"],["p","+ Là vợ, chồng, cha đẻ, mẹ đẻ hoặc con đẻ của công dân Việt Nam;"],["p","+ Có công lao đặc biệt đóng góp cho sự nghiệp xây dựng và bảo vệ Tổ quốc Việt Nam;"],["p","+ Có lợi cho Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam."],["p","- Theo Điều 14 Nghị định 16/2020/NĐ-CP quy định, người xin trở lại quốc tịch Việt Nam nhưng không phải thôi quốc tịch nước ngoài và trình Chủ tịch nước xem xét nếu đáp ứng đầy đủ các điều kiện sau đây:"],["p","+ Có đủ điều kiện trở lại quốc tịch Việt Nam theo quy định của Luật Quốc tịch Việt Nam 2008."],["p","+ Việc xin giữ quốc tịch nước ngoài của người đó khi trở lại quốc tịch Việt Nam là phù hợp với pháp luật của nước ngoài đó."],["p","+ Việc thôi quốc tịch nước ngoài dẫn đến quyền lợi của người đó ở nước có quốc tịch bị ảnh hưởng."],["p","+ Không sử dụng quốc tịch nước ngoài để gây phương hại đến quyền, lợi ích hợp pháp của cơ quan, tổ chức và cá nhân; xâm hại an ninh, lợi ích quốc gia, trật tự, an toàn xã hội của Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam."]]},{"h":"4. Trường hợp trẻ em Việt Nam được người nước ngoài nhận làm con nuôi","b":[["p","Theo Điều 37 Luật Quốc tịch Việt Nam 2008 quy định:"],["p","Trẻ em là công dân Việt Nam được người nước ngoài nhận làm con nuôi thì vẫn giữ quốc tịch Việt Nam."],["p","Như vậy trong trường hợp trẻ em là người mang quốc tịch Việt Nam được công dân nước ngoài nhận nuôi thì pháp luật Việt Nam vẫn cho phép trẻ em mang hai quốc tịch."],["p","Câu hỏi:"],["p","Tại sao VN không áp dụng triệt để tình trạng nhiều quốc tịch? : Đoàn"],["p","Bởi lẽ hệ quả việc áp dụng triệt để tình trạng nhiều quốc tịch này thường dẫn đến những tranh chấp rất phức tạp, khó giải quyết, nhiều khi gây ảnh hưởng không tốt tới quan hệ giữa các quốc gia liên quan. Thực tiễn thi hành pháp luật quốc tịch Việt Nam cũng như pháp luật và thông lệ quốc tế cho thấy, tranh chấp/xung đột quốc tế thường xảy ra xung quanh việc bảo hộ đối với người có hai và nhiều quốc tịch trở lên…"],["p","Kiếm CSPL, mục đích của việc này là gì -> cơ hội tạo đk cho người VN ở nước ngoài về,... như thế nào?"],["p","CSPL: điều 4 luật quốc tịch Việt Nam 2008 quy định:"],["p","Nhà nước Cộng hoà xã hội chủ nghĩa Việt Nam công nhận công dân Việt Nam có một quốc tịch là quốc tịch Việt Nam, trừ trường hợp Luật này có quy định khác."],["p","Mục đích:"],["p","tránh các hệ quả mà việc nhiều quốc tịch mang lại,nhưng vẫn mềm dẻo với một số trường hợp đặc biệt(k3 đ9;k5 đ23)"],["p","Tạo cơ hội cho người Việt ở nước ngoài như:tạo điều kiện cho Việt kiều hồi hương nhập quốc tịch(k1 đ23)"],["p","-> Nguyên tắc quốc tịch VN là 1 quốc tịch linh động và mềm dẻo được quy định ở điều 4 > k3đ19, k5 điều 23"]]},{"h":"2.5 Pháp luật VN quy định thế nào về trường hợp không quốc tịch? Thực trạng?","b":[["p","Một người đã mất quốc tịch cũ ( do được thôi quốc tịch, bị tước quốc tịch, tự động mất quốc tịch…) nhưng chưa được vào quốc tịch mới của quốc gia khác."],["p","CSPL: Điều 26 Luật Quốc tịch VN (VB hợp nhất)"],["p","Điều 26. Căn cứ mất quốc tịch Việt Nam"],["p","1. Được thôi quốc tịch Việt Nam."]]},{"h":"2. Bị tước quốc tịch Việt Nam. :được quy định tại điều 31","b":[]},{"h":"3.3 (được bãi bỏ)","b":[["p","4. Theo quy định tại khoản 2 Điều 18 và Điều 35 của Luật này. : Theo điều 18 trẻ em bị bỏ rơi được tìm thấy trên lãnh thổ VN sẽ có quốc tịch VN. Tuy nhiên, theo K2 điều 18 trẻ em chưa đủ 15t không còn quốc tịch VN vì tìm thấy cha mẹ mà cha mẹ/ cha hoặc mẹ chỉ có quốc tịch nước ngoài"],["p","5. Theo điều ước quốc tế mà Cộng hòa xã hội chủ nghĩa Việt Nam là thành viên."],["p","Do xung đột về cách thức hưởng quốc tịch của các nước."],["p","Một đứa trẻ sinh ra trên lãnh thổ của nước áp dụng nguyên tắc luật huyết thống mà cha mẹ của đứa trẻ lại là người không quốc tịch."],["p","VD: Ở nước Áo theo nguyên tắc huyết thống, cha mẹ đứa bé là người k có quốc tịch -> đứa bé không có quốc tịch"],["p","Điều 22, 17, 18 Hạn chế tình trạng không quốc tịch"],["p","-> Địa vị pháp lý thấp kém hơn người có quốc tịch và không quốc tịch rất nhiều"],["p","Thực trạng:"],["p","Di cư sang VN"],["p","Hộ dân sống ở những con sông -> không đăng kí cư trú nên nhà nước không thể kiểm soát"],["p","Ở Lào Cai, Lai Châu có rất nhiều tình trạng không quốc tịch do nạn xin con nuôi bất hợp pháp -> Nhà nước không thể kiểm soát."],["p","Có một số người lấy chồng Đài Loan và chồng họ yêu cầu thôi quốc tịch Việt Nam, nhưng chưa nhập quốc tịch Đài Loan vì thế dẫn tới tình trạng không có quốc tịch (Phụ nữ bị buôn bán bất hợp pháp sang nước ngoài làm vợ và trở về trong tình trạng không có quốc tịch)"],["p","Câu hỏi: Nhà nước ta có giải pháp gì cho nạn không quốc tịch đấy chưa? CSPL"],["p","- Nhà nước cần sớm tham gia Công ước về vị thế của người không quốc tịch 1954 nhằm cải thiện được vị trí pháp lý, nâng cao vị thế của người không quốc tịch và Công ước Liên hợp quốc năm 1961 về giảm thiểu tình trạng không quốc tịch."],["p","Công ước về vị thế của người không quốc tịch quy định: Mỗi người không quốc tịch đều có những nghĩa vụ đối với đất nước nơi người đó cư trú; không phân biệt đối xử ; quyền tự do tôn giáo; …."],["p","- Tiếp tục tăng cường hợp tác quốc tế với các nước láng giềng để giải quyết các vấn đề liên quan đến người không quốc tịch ở Việt Nam."],["p","- Cần sớm vận hành, đưa vào sử dụng phần mềm quốc tịch trong cả nước đảm bảo việc tra cứu, rà soát kịp thời, xác định đúng tình trạng quốc tịch của công dân, giảm tải thời gian giải quyết thủ tục hành chính."],["p","- Các cơ quan có thẩm quyền giải quyết việc quốc tịch chủ động nghiên cứu, rà soát các quy định còn bất cập để đề nghị cơ quan cấp trên xem xét sửa đổi, bổ sung các quy định về người không quốc tịch trong Luật Hộ tịch và Luật Quốc tịch bảo đảm phù hợp với thực tiễn."],["p","- Xây dựng kế hoạch rà soát tình trạng không quốc tịch trên cả nước nhằm đưa ra các giải pháp giải quyết phù hợp với từng trường hợp."]]},{"h":"2.7 Địa vị pháp lý của người nước ngoài : Huy, CSPL Huyền Cơ","b":[["p","Khái niệm “người nước ngoài” ( khái quát) :"],["p","-Người nước ngoài được xem là chủ thể đặc trưng và phổ biến nhất của tư pháp quốc tế."],["p","- Tại Việt Nam, khái niệm “người nước ngoài” lần đầu tiên được quy định tại Điều 1 Quyết định số 122/CP ngày 25/4/1977 của Hội đồng Chính phủ về chính sách đối với người nước ngoài cư trú, làm ăn, sinh sống tại Việt Nam: người nước ngoài gọi tắt là ngoại kiều nói trong Quyết định này là “những người cư trú, làm ăn, sinh sống tại Việt Nam, có quốc tịch nước khác hoặc không có quốc tịch”."],["p","- Căn cứ theo quy định tại khoản 1 Điều 3 Luật xuất cảnh, nhập cảnh, quá cảnh cư trú của người nước ngoài tại Việt nam 2014 thì ” Người nước ngoài là người mang giấy tờ xác định quốc tịch nước ngoài và người không quốc tịch nhập cảnh, xuất cảnh, quá cảnh, cư trú tại Việt Nam”"],["p","-Theo quy định tại khoản 2 Điều 3 Nghị định số 138/2006/NĐ-CP ngày 15/11/2006 của Chính phủ quy định chi tiết thi hành các quy định của Bộ luật dân sự về quan hệ dân sự có yếu tố nước ngoài thì: “người nước ngoài là người không có quốc tịch Việt Nam, bao gồm người có quốc tịch nước ngoài và người không quốc tịch ”."],["p","Theo Điều 3 Luật quốc tịch Việt Nam 2008 thì: “Người nước ngoài cư trú ở Việt Nam là công dân nước ngoài và người không quốc tịch thường trú hoặc tạm trú ở Việt Nam ”."],["p","Chế độ pháp lý dành cho người nước ngoài"],["p","Nguyên tắc đối xử như công dân"],["p","Là chế độ cho phép người nước ngoài có quyền và nghĩa vụ tương ứng như công dân nước sở tại trong các quan hệ xã hội nhất định."],["p","Người nước ngoài được hưởng các quyền dân sự và lao động, cũng như thực hiện các quyền và nghĩa vụ khác tương đương hoặc bằng với những quyền và nghĩa vụ mà công dân nước sở tại đang được hưởng và sẽ được hưởng trong tương lai. Ví dụ: trong giao kết hợp đồng."],["p","Người nước ngoài được hưởng quyền và nghĩa vụ như công dân nước sở tại không phải ở tất cả mọi mặt, người nước ngoài bị hạn chế ở một số quyền nhất đinh. Ví dụ: quyền bầu cử, quyền ứng cử, đề cử, quyền cư trú, quyền hành nghề, học tập trong lĩnh vực an ninh quốc phòng.."],["p","Người nước ngoài sống trên lãnh thổ VN sẽ được miễn nghĩa vụ quân sự; không phải trung thành với tổ quốc VN"],["p","-> Thể hiện sự công bằng giữa người nước ngoài và công dân của quốc gia"],["p","Nguyên tắc tối huệ quốc:"],["p","Chế độ tối huệ quốc là người nước ngoài và pháp nhân nước ngoài được hưởng một chế độ mà nước sở tại dành cho người nước ngoài và pháp nhân nước ngoài của bất kỳ nước thứ ba nào đang được hưởng và sẽ được hưởng trong tương lai."],["p","Chế độ tối huệ quốc thì người nước ngoài cũng như pháp nhân nước ngoài được hưởng đầy đủ và hoàn toàn các quyền hợp pháp mà một quốc gia đã dành và sẽ dành cho bất kỳ một nhóm người nước ngoài cũng như pháp nhân nước ngoài đang sinh sống hay hoạt động tại lãnh thổ của quốc gia đó."],["p","Phạm vi áp dụng chủ yếu của chế độ này nằm trong thương mại và hàng hải được ghi nhận trong các điều ước quốc tế và pháp luật quốc gia nhằm đưa lại những điều kiện và cơ hội như nhau cho công dân pháp nhân các nước khi tiến hành các hoạt động kinh doanh, thương mại trên lãnh thổ nước sở tại."],["p","-> Thể hiện sự công bằng giữa các thể nhân, pháp nhân giữa các quốc gia với nhau"],["p","Ví dụ : Thuế nhập khẩu linh kiện xe máy vào Việt nam được áp dụng ở mức 50%, sau đó Việt nam kí kết hiệp định thương mại song phương với Nhật bản, quy định mức thuế mới đối lới linh kiện xe máy nhập khẩu từ Nhật bản là 30%. Khi đó nếu trong hiệp định giữa Việt nam và Trung quốc có quy định về việc hai bên giành cho nhau chế độ tối huệ quốc thì lúc này mức thuế nhập khẩu đối với linh kiện xe máy từ Trung quốc vào Việt nam sẽ tự động và ngay lập tức được điều chỉnh xuống còn 30%."],["p","Nguyên tắc đối xử đặc biệt: đối tượng được hưởng bị giới hạn"],["p","Chế độ này là người nước ngoài được hưởng những quyền ưu tiên, ưu đãi đặc biệt hoặc quyền đặc hưởng mà nước sở tại dành cho họ thậm chí chính công dân nước sở tại cũng không được hưởng."],["p","Các ưu tiên, ưu đãi hoặc các đặc quyền này thường được quy định trong luật pháp của các quốc gia cũng như trong các điều ước quốc tế."],["p","Áp dụng đối với nhân viên ngoại giao, lãnh sự và nhân viên của các tổ chức quốc tế theo các quy định trong các cam kết quốc tế"],["p","VD: CUV 1961 và CUV 1963 về quan hệ lãnh sự"],["p","Cơ sở : người nước ngoài chỉ được hưởng chế độ đãi ngộ đặc biệt này trên cơ sở pháp luật quốc gia của nước sở tại hoặc điều ước quốc tế mà nước này tham gia. Trên thực tế các chế độ đãi ngộ đặc biệt này thường được áp dụng trong các quan hệ ngoại giao – quan hệ lãnh sự"],["p","Theo điều 29 Công ước viên năm 1961 về quan hệ ngoại giao thì nhân viên ngoại giao của nước ngoài ở nước sở tại được hưởng các chế độ đãi ngộ đặc biệt: “ thân thể của viên chức ngoại giao là bất khả xâm phạm. Họ không thể bị bắt hoặc bị giam giữ dưới bất kì hình thức nào. Nước tiếp nhận cần có sự đối xử trọng thị xứng đáng với họ và áp dụng mọi biện pháp thích đáng để ngăn chặn mọi hành vi xúc phạm đến thân thể, tự do hay phẩm cách của họ”"],["p","Có đi có lại:"],["p","Chế độ có đi có lại thể hiện ở việc một quốc gia dành một chế độ pháp lý nhất định cho cá nhân và pháp nhân nước ngoài tương ứng như trước đó đã dành và sẽ dành cho công dân và pháp nhân của mình ở đó trên cơ sở có đi có lại."],["p","Do các quốc gia có chế độ chính trị, nền kinh tế cũng như lịch sử khác nhau, cho nên trong thực tiễn chế độ có đi có lại được thể hiện dưới hai cách: có đi có lại thực chất và có đi có lại hình thức."],["p","Có đi có lại thực chất: là một nước dành cho cá nhân hoặc pháp nhân nước ngoài một số quyền và nghĩa vụ hoặc những ưu đãi nhất định đúng bằng những quyền và nghĩa vụ cũng như những ưu đãi thực tế mà các cá nhân và pháp nhân của nước đó đã được hưởng ở nước ngoài kia. Có đi có lại thực chất được áp dụng ở những nước có cùng chế độ kinh tế – chính trị – xã hội."],["p","Chế độ có đi có lại hình thức: Một nước dành cho cá nhân và pháp nhân nước ngoài một chế độ pháp lý nhất định như chế độ đãi ngộ như công dân hoặc chế độ đãi ngộ tội huệ quốc mà ở nước kia cũng đã dành cho công dân và pháp nhân nước mình một chế độ tương ứng như thế. Được áp dụng rất hữu hiệu trong quan hệ giữa các quốc gia có chế độ chính trị – xã hội khác nhau."],["p","Trả đũa:"],["p","Nếu một quốc gia nào đó đơn phương sử dụng những biện pháp hoặc có các hành vi gây thiệt hại hoặc tổn hại cho quốc gia hay công dân và pháp nhân của quốc gia khác thì chính quốc gia bị tổn hại đó hoặc công dân hay pháp nhân của nó được phép sử dụng các biện pháp trả đũa như hạn chế hoặc có hành động tương ứng đối phó hoặc đáp trả."]]},{"h":"2.8 Cư trú chính trị là gì? CSPL? ( chỉ áp dụng với tội phạm chính trị)","b":[["p","Cư trú chính trị ( tỵ nạn chính trị) có thể được định nghĩa là việc một quốc gia cho phép những người nước ngoài đang bị truy nã ngay trên đất nước họ (bị truy nã bởi quốc gia mà họ mang quốc tịch) do những quan điểm và hoạt động về chính trị, khoa học và tôn giáo… được nhập cảnh và cư trú ở ngay trên lãnh thổ nước mình."],["p","Như vậy, một người nước ngoài có thể được một quốc gia khác cho phép cư trú chính trị trên lãnh thổ mình nếu như theo quan điểm của quốc gia chấp nhận cư trú chính trị, họ có sự bất đồng về quan điểm hoặc có những hoạt động về chính trị, khoa học, tôn giáo ở ngay chính quốc gia mà họ đang là công dân và vì lý do này họ đang bị truy nã ở quốc gia đó hoặc có khả năng bị đe dọa bắt giữ hoặc áp dụng chế tài."],["p","CSPL: điều 49 hp2013: Người nước ngoài đấu tranh vì tự do và độc lập dân tộc, vì chủ nghĩa xã hội, dân chủ và hòa bình hoặc vì sự nghiệp khoa học mà bị bức hại thì được Nhà nước Cộng hòa xã hội chủ nghĩa Việt Nam xem xét cho cư trú."],["p","CSPL quốc tế: Tuyên bố LHQ về cư trú lãnh thổ 1967 : “Quyền cư trú chính trị cần được trao cho những người đấu tranh chống chủ nghĩa thực dân. Các nước cần phải giúp đỡ những người này để họ có thể nhập cảnh, không trục xuất, cưỡng bức họ trở về nước mà họ đang bị truy nã. Các nước không được trao quyền cư trú cho những kẻ phạm tội ác quốc tế, trước hết là tôi ác chống hoà bình và tội ác chiến tranh. Các nước phải đảm bảo an ninh cho người cư trú chính trị trên lãnh thổ nước mình\""],["p","CSPL quốc tế: k1 điều 14 tuyên ngôn quốc tế nhân quyền 1948: Khi bị đàn áp, ai cũng có quyền tìm nơi tị nạn và được hưởng quyền tị nạn tại các quốc gia khác."],["p","Đặc điểm của việc cho phép cư trú chính trị:"],["p","Việc cho phép một người nước ngoài được cư trú chính trị trên lãnh thổ của quốc gia mình thuộc thẩm quyền riêng biệt của mỗi quốc gia và đây cũng được coi như là công việc nội bộ của quốc gia đó. Pháp luật của các quốc gia thường chỉ rõ những đối tượng nào được phép cư trú chính trị trên lãnh thổ quốc gia mình. Đối với những người mà pháp luật của quốc gia họ đang mang quốc tịch coi là tội phạm chính trị, việc chấp nhận cho họ cư trú chính trị hay không phụ thuộc vào quyền của quốc gia cho phép cư trú."],["p","Điều 82 Hiến pháp 1992 của Việt Nam cũng quy định: \"Người nước ngoài đấu tranh vì tự do và độc lập dân tộc, chủ nghĩa xã hội, dân chủ và hòa bình hoặc vì sự nghiệp khoa học mà bị bức hại thì được nhà nước Cộng hòa xã hội chủ nghĩa Việt nam xem xét việc cho cư trú\"."],["p","Hiện nay, căn cứ vào các quy phạm luật quốc tế được thừa nhận chung dưới dạng tập quán và điều ước quốc tế, các quốc gia không dành quyền cư trú chính trị cho những đối tượng cụ thể và những cá nhân đã có hành vi vi phạm pháp luật quốc tế nghiêm trọng xâm phạm đến lợi ích chung của cả cộng đồng, cụ thể bao gồm:"],["p","+ Người phạm tội ác quốc tế: tội chống lại hòa bình, các tội phạm chiến tranh, tội phạm chống nhân loại, diệt chủng; vd: phát xít nhật, đức, ý; nạn diệt chủng ru an đa 1994"],["p","+ Người là tội phạm hình sự theo pháp luật của một quốc gia;"],["p","+ Người phạm các tội phạm hình sự quốc tế: không tặc, khủng bố, buôn bán ma tuý, buôn bán nô lệ ."],["p","+ Người là tội phạm hình sự mà việc dẫn độ được quy định trong các điều ước quốc tế song phương hoặc đa phương về dẫn độ;"],["p","+ Người có hành vi trái với mục đích và nguyên tắc của luật quốc tế"],["p","Người nước ngoài cư trú chính trị không bắt buộc phải nhập quốc tịch của quốc gia sở tại, được hưởng những quyền ngang với những người nước ngoài khác, được quốc gia cho phép mình cư trú chính trị bảo hộ ngoại giao, tức là bảo vệ quyền lợi trong khi họ đang cư trú tại một nước thứ ba, có quyền được đảm bảo về an ninh, tức là quyền được đảm bảo không bị dẫn độ và trục xuất theo yêu cầu của nước mà họ là công dân."],["p","Hiện nay, có hai dạng cư trú chính trị là cư trú chính trị trên lãnh thổ của một quốc gia khác hoặc cư trú chính trị tại các cơ quan đại diện ngoại giao, lãnh sự của một quốc gia khác tại quốc gia sở tại."]]},{"h":"2.8 Điều kiện xác định tội phạm chính trị là gì? CSPL ? Liên hệ pháp luật VN( 1,2 điều khoản )","b":[["p","Có quan điểm bất đồng về tôn giáo, chính trị với quốc gia họ nhưng mà họ lại đang đấu tranh về hòa bình, dân chủ ( xuất phát từ quyền con người được bảo vệ)"],["p","Họ bị quốc gia họ truy nã, bức hại"],["p","CSPL: điều 49 HP 2013"],["p","1. Tội phản bội Tổ quốc (Điều 78 – Bộ luật hình sự): là hành vi của công dân Việt Nam câu kết (là quan hệ qua lại chặt chẽ giữa người phạm tội với người nước ngoài) với nước ngoài nhằm gây nguy hại cho độc lập, chủ quyền, thống nhất và toàn vẹn lãnh thổ của Tổ quốc, lực lượng quốc phòng, chế độ XHCN và Nhà nước cộng hòa XHCN Việt Nam."],["p","2. Tội hoạt động nhằm lật đổ chính quyền nhân dân (Điều 79 – Bộ luật hình sự): là hành vi hoạt động thành lập hoặc tham gia tổ chức nhằm lật đổ chính quyền nhân dân các cấp từ Trung ương đến địa phương."]]},{"h":"2.9 Tội phạm chính trị khác gì với tội phạm hình sự, tội phạm hình sự quốc tế ? CSPL","b":[["p","Tội phạm chính trị"],["p","Là người hoạt động chính trị, chống lại chế độ chính trị, bị bắt giam, tù đày. Những người hoạt động phản cách mạng và phạm tội an ninh quốc gia khi bị kết án được gọi là người phạm tội xâm phạm an ninh quốc gia và là tội phạm chính trị."],["p","Tội phạm chính trị được quy định trong BLHS của từng quốc gia."],["p","Ở VN tội phạm chính trị được quy định trong Chương XIII Bộ luật hình sự 2015 sửa đổi bổ sung 2017 ( Các tội xâm phạm an ninh quốc gia )"],["p","Ví dụ:"],["p","Vào tháng 6 năm 2016, một số bài báo nước ngoài đã đưa tin về 1 công dân Mỹ (tên là Khưu Hiền Duyên) làm từ thiện ở Việt Nam bỗng dưng mất tích. Các bài báo trên cho rằng, bà Hiền Duyên được cho là mất tích vào đêm ngày 26/5/2016."],["p","Đáng chú ý, ngay sau khi bà về Mỹ, các báo đài đã phỏng vấn về việc bỗng dưng mất tích tại Việt Nam, từ đó suy diễn, bịa đặt nhiều nội dung tố cáo Công an Việt Nam bắt giữ công dân Hoa Kỳ."],["p","Nhưng sự thật đằng sau, “từ thiện” chỉ là cái cớ còn thực chất là Mã Tiểu Linh về Việt Nam thực hiện các hành vi chống phá, giúp sức cho Việt Tân lợi dụng sự bức xúc của người dân sau hiện tượng cá chết để kích động xuống đường biểu tình, gây rối, từ đó ý đồ gây bạo loạn."],["p","Bác sĩ Lê Nguyên Sang, thành viên lãnh đạo Đảng Dân chủ Nhân dân, trong phiên tòa xử sơ thẩm ngày 10/05/2007 của Tòa án nhân dân Sài Gòn bị phạt 5 năm tù và 2 năm quản chế tại gia về tội tuyên truyền chống Nhà nước."],["p","Bác sĩ Sang với các hành vi thành lập Đảng Dân chủ Nhân dân không xin phép, in khoảng 1600 tờ truyền đơn đòi tự do dân chủ. Vào năm 2007, chính vì những hành vi đó mà ông bị xem là một tội phạm chính trị."],["p","Tội phạm hình sự"],["p","Tội phạm hình sự là :"],["p","Những hành vi nguy hiểm cho xã hội được quy định trong BLHS của mỗi quốc gia"],["p","Do người có năng lực trách nhiệm hình sự hoặc pháp nhân thương mại thực hiện một cách cố ý hoặc vô ý"],["p","Xâm phạm độc lập, chủ quyền, thống nhất, toàn vẹn lãnh thổ Tổ quốc, xâm phạm chế độ chính trị, kinh tế,…, quyền, lợi ích hợp pháp của tổ chức, xâm phạm quyền con người, quyền, lợi ích hợp pháp của công dân, xâm phạm những lĩnh vực khác của trật tự pháp luật xã hội chủ nghĩa mà theo quy định của BLHS phải bị xử lý hình sự."],["p","Vd: tội giết người; trộm cắp; xâm phạm tính mạng, sức khoẻ;..v..v"],["p","CSPL: Điều 8 Bộ luật Hình sự năm 2015 (Sửa đổi bổ sung năm 2017) định nghĩa khái niệm “Tội phạm” hay cũng chính là “Tội phạm hình sự”"],["p","CSPL: điều 9 BLHS."],["p","-> Có Công ước quốc tế quy định vụ việc xảy ra trên đất nước nào thì dựa vào Luật của nước xảy ra vụ việc. Quốc gia dù muốn hay không cũng phải dẫn độ theo yêu cầu."],["p","Nếu không có Điều ước thì việc dẫn độ hay không là quyền của một quốc gia."],["p","Tội phạm hình sự quốc tế"],["p","Là người có năng lực trách nhiệm hình sự; thực hiện một cách cố ý hay vô ý các hành vi xâm phạm tới hoà bình an ninh quốc tế gây lo ngại cho toàn thể cộng đồng quốc tế"],["p","-> Gây nguy hiểm nhưng mức độ không bằng tội phạm quốc tế"],["p","- Bị truy nã một số quốc gia nhất định, một số quốc gia không truy nã."],["p","-> Chủ thể chịu trách nhiệm là cá nhân người tội phạm."],["p","Còn tội phạm quốc tế thì chính quốc gia mà cá nhân đó mang quốc tịch phải chịu trách nhiệm."],["p","Vd: tội buôn người; cướp biển; buôn bán ma tuý xuyên biên giới;…"],["p","Được quy định và xét xử theo cơ chế quốc tế, thông thường sẽ đưa ra trước toà án hình sự quốc tế."],["p","Nhóm tội phạm có tính chất quốc tế được chia thành 4 nhóm:"],["p","Các tội xâm phạm tới quan hệ hợp tác hữu nghị và sự tồn tại bình thường của các quan hệ giữa các nước. Vd: tội khủng bố, cướp máy bay,.."],["p","CSPL: điều 299 BLHS quy định về tội khủng bố và khung hình phạt của tội khủng bố"],["p","Các tội xâm hại môi trường sống của con người, di sản văn hoá dân tộc trên tg. Vd: buôn lậu, buôn bán trái phép chất ma tuý, làm và buôn bán tiền giả…"],["p","CSPL: Điều 188 BLHS có quy định về tội buôn lậu; điều 207 có quy định về tội làm, tàng trữ, vận chuyển, lưu hành tiền giả"],["p","Tội xâm phạm nhân phẩm danh dự con người. Vd: tội tuyên truyền các xuất bản phẩm đồi truỵ,.."],["p","CSPL: Điều 326 BLHS có quy định về tội truyền bá văn hoá phẩm đồi truỵ"],["p","Tội phạm có tính quốc tế khác. Vd: phá hoại các công trình ngầm dưới biển;…"],["p","Nhớ dẫn CSPL đó vào hoặc nêu khái quát nó nói về gì nha mn"],["p","Tội phạm quốc tế"],["p","Chủ thể chịu trách nhiệm quốc tế là các quốc gia mà các cá nhân mang quốc tịch"],["p","Có tội về diệt chủng,..."],["p","Bị truy nã trên toàn cầu"],["p","-> Mang tính chất nguy hiểm trên toàn cầu, cao hơn so với tội phạm hình sự quốc tế"]]}]},{"t":"LÃNH THỔ BIÊN GIỚI QUỐC GIA","n":4,"g":[{"h":"","b":[["p","CHƯƠNG IV: LÃNH THỔ & BIÊN GIỚI QUỐC GIA"],["p","I / Lãnh thổ quốc gia"],["p","lãnh thổ quốc gia là 1 phần của trái đất, bao gồm vùng đất, vùng nước, vùng trời trên chúng và vùng lòng đất dưới chúng thuộc chủ quyền hoàn toàn, riêng biệt và tuyệt đối của qgia"],["p","Lãnh thổ là một trong bốn yếu tố cơ bản tạo nên tư cách pháp lý của quốc gia - chủ thể cơ bản, chủ yếu của luật quốc tế."],["p","Đồng thời lãnh thổ quốc gia là không gian xác định chủ quyền quốc gia trong quan hệ quốc tế."],["p","ltqg cũng là bằng chứng pháp lý chứng minh sự hiện hữu của một quốc gia trên thực tế. Có nghĩa là nếu không có lãnh thổ sẽ không có quốc gia tồn tại trên thực tế. Tương tự nếu một quốc gia không còn lãnh thổ thì tư cách chủ thể của luật quốc tế của quốc gia cũng chấm dứt."],["p","Bốn yếu tố cấu thành lãnh thổ quốc gia; Chủ quyền hoàn toàn tuyệt đối ( chiếm hữu, sử dụng, định đoạt như thế nào ) ; Chủ quyền hoàn toàn đầy đủ hay nói cách khác là bị hạn chế ( đối với vùng lãnh thổ do nhiều Quốc Gia có chủ quyền )"],["p","Định nghĩa:Chủ quyền quốc gia là Quyền làm chủ đối với quốc gia, là thuộc tính chính trị - pháp lý không thể tách rời khỏi quốc gia. Chủ quyền quốc gia bao gồm nhiều nội dung, trong đó có các quyền cơ bản là quyền bất khả xâm phạm lãnh thổ, quyền tự quyết định những công việc của quốc gia, quyền độc lập trong quan hệ đối ngoại."],["p","CSPL: Điều 1 Luật Hiến pháp 2013 ghi rõ: Nước Cộng hòa xã hội chủ nghĩa Việt Nam là một nước độc lập, có chủ quyền, thống nhất và toàn vẹn lãnh thổ, bao gồm đất liền, hải đảo, vùng biển và vùng trời."],["p","=> Điều trên đã khẳng định nước cộng hòa xã hội chủ nghĩa Việt Nam là một đất nước thống nhất, có chủ quyền về phương diện lãnh thổ là toàn vẹn."],["p","Lãnh thổ bao gồm:"],["p","Vùng đất(chủ quyền hoàn toàn tuyệt đối): là quan trọng nhất vì đó là bộ phận chủ yếu để quốc gia thực hiện chủ quyền,đồng thời quyết định trực tiếp đến các vùng lãnh thổ khác.LÀ VÙNG CHỦ QUYỀN HOÀN TOÀN TUYỆT ĐỐI:là các vùng mà quốc gia có chủ quyền sẽ được chiếm hữu,sử dụng, định đoạt các vấn đề liên quan đến lãnh thổ của quốc gia đó"],["p","Phương diện pháp lý vùng chủ quyền hoàn toàn tuyệt đối: \"Quốc gia chủ nhà\" là chủ thể duy nhất có đầy đủ các quyền năng chiếm hữu, sử dụng, định đoạt các vấn đề pháp lý. Tuy nhiên vẫn phải dựa trên nền tảng của LQT và thực tiễn của QG đó"],["p","Luật quốc tế không quy định diện tích tối đa của một qgia là bao nhiêu km2. Nhưng về phương diện khoa học diện tích tối đa của một quốc gia phải đủ cho một cộng đồng người cùng tồn tại, cùng sinh sống, cùng phát triển và xây dựng một quốc gia độc lập."],["p","CSPL:điều 2 khoản 4 của Hiến chương LHQ Đã khẳng định:”Trong quan hệ quan hệ quốc tế ,các hội viên liên hợp quốc không được có hành động đe dọa bằng vũ lực hay sử dụng vũ lực để chống lại quyền bất khả xâm phạm về lãnh thổ hay nền độc lập chính trị của bất kỳ nước nào, hoặc bằng cách này hay cách khác làm trái với những mục đích của LHQ…”"],["p","-Lãnh thổ vùng đất của quốc gia là toàn bộ phần đất liền(đất lục địa) và các đảo, quần đảo thuộc chủ quyền của quốc gia kể cả các đảo và quần đảo gần bờ hoặc xa bờ."],["p","-Như vậy,chủ quyền của VN bao gồm toàn bộ lục địa hình chữ S và các đảo như Phú Quốc,Cồn Cỏ,Phú Quý,... và hai quần đảo Hoàng Sa và Trường Sa."],["p","-Riêng quốc gia quần đảo,lãnh thổ vùng đất bao gồm tất cả đảo thuộc chủ quyền quốc gia đó.ví dụ là Indonesia với 17.508 hòn đảo."],["p","Vùng nước"],["p","Lãnh thổ vùng nước của quốc gia là toàn bộ vùng nước nằm bên trong đường biên giới quốc gia bao gồm:"],["p","+Vùng nước nội địa (chủ quyền hoàn toàn tuyệt đối vì nó nằm trọn vẹn trong lục địa của một quốc gia). Về phương diện pháp lý ít hay nhiều thì mọi quốc gia đều sẽ tồn tại vùng nước nội địa vì đó là Điều kiện rất căn bản để con người có thể tồn tại trong một vùng lãnh thổ."],["p","Vd: nước ở sông, hồ, đầm eo, kênh rạch vân vân kể cả tự nhiên hay nhân tạo nhưng nếu nằm trong đất liền, trên các đảo và quần đảo thuộc chủ quyền của quốc gia thì đều là vùng nước nội địa"],["p","+Vùng nước biên giới là toàn bộ những vùng nước nằm trong khu vực biên giới tiếp giáp với các quốc gia. Vd: sông biên giới, trên biên giới, hồ biên giới nơi có đường biên giới được xác định giữa hai quốc gia."],["p","Chủ quyền hoàn toàn đầy đủ vì nó nằm trong khu vực sông ngòi nằm trong biên giới của qg"],["p","=> các quốc gia chung vùng nước biên giới sẽ phải chia sẻ những quyền quản lý, sử dụng, khai thác, bảo vệ và định đoạt các vấn đề pháp lý liên quan đến vùng nước này."],["p","VD: Sông Mê Kông. Hiệp định phát triển bền vững hạ nguồn sông Mê Kông"],["p","-> Nội địa và biên giới: Mặc dù nước biên giới cũng là nước ở sông, ở hồ nhưng vị trí nó nằm rất đặc biệt đó là nằm trong khu vực biên giới của các nước nên tính chất chủ quyền nó khác nhau. Phụ thuộc vào lợi ích chung của qg"],["p","+Vùng nước nội thuỷ(chủ quyền hoàn toàn tuyệt đối do gắn liền với lãnh thổ của một quốc gia): toàn bộ phần nước biển được xác định một bên là đất liền, một bên là đường cơ sở (UNCLOS khoản 1 điều 8) / Điều 9 Luật Biển VN 2012"],["p","-> Nội thủy và nội địa: khác nhau về vị trí địa lí -> Nhưng Tính chất giống nhau đều là chủ quyền hoàn toàn tuyệt đối"],["p","Đối với các quốc gia quần đảo thì vùng nước nội thủy là vùng nước nằm bên trong vùng nước quần đảo ( Điều 50 UNCLOS )"],["p","+Vùng nước lãnh hải (chủ quyền hoàn toàn đầy đủ): được xác định một bên là đường cơ sở và đường biên giới"],["p","CSPL: điều 17 công ước Luật biển 1982 quy định: \"Tàu thuyền của tất cả các quốc gia, có biển hay không có biển đều được hưởng quyền đi qua không gây hại trong lãnh hải\". Hướng đến bảo vệ lợi ích của các quốc gia có biển hay không có biển."],["p","-Qua lại không gây hại được giải thích ở điều 18"],["p","-Đi qua được xem là gây hại được ghi ở điều 19"],["p","-> Xác định Nội thủy và lãnh hải:"],["p","đầu tiên phải xác định ĐƯỜNG CƠ SỞ điều 5, 7 của công ước LHQ năm 1982. Có 2 cách xđ đường cơ sở: dựa vào mực thủy triều-đường cơ thông thường ( điều 5); đường cơ sở thẳng ( điều 7) do địa hình bờ biển ở mỗi qg khác nhau; điều 14 là kết hợp cả hai phương pháp ( bãi cạn lúc nổi lúc chìm quy định điều 13 UNCLOS )"],["p","-> Sẽ có những quốc gia không có biển nên sẽ k có nội thủy và lãnh hải. Nên tùy thuộc vào vị trí địa lí mà có qg sẽ có biển và không có biển"],["p","- hiện nay Vn chúng ta có tổng cộng 11 cột mốc để phân định đg cơ sở từ A1 tới A11 ( Hòn nhạn tới cồn cỏ )"],["p","-Vùng trời: khoảng không gian bao trùm lên vùng đất và vùng nước của quốc gia, thuộc chủ quyền hoàn toàn và tuyệt đối của quốc gia.Bên trên vùng trời gọi là khoảng không vũ trụ. Giới hạn bên ngoài vùng trời của một quốc gia được xác định bởi mặt phẳng thẳng đứng, vuông góc từ đường biên giới quốc gia trên đất liền, từ ranh giới phía ngoài vùng tiếp giáp lãnh hải của đất liền và các hải đảo hướng lên khoảng không vũ trụ."],["p","-Vùng lòng đất(chủ quyền hoàn toàn tuyệt đối): Là toàn bộ phần đất dưới vùng đất và vùng nước thuộc chủ quyền của quốc gia. Lãnh thổ vùng lòng đất của qg được xác định từ bề mặt trái đất đến tâm trái đất."],["p","Câu hỏi:"],["p","Các qg Bắc Cực có thêm một bộ phận lãnh thổ là gì? Cách xác định như thế nào"],["p","Bắc Cực là một bộ phận của TĐ, hiện nay có tám QG có lãnh thổ giáp Bắc Cực đó là: CH Liên Bang Nga, Mỹ, Na Uy, Canada, Đan Mạch, Thụy Điển, Phần Lan và Iceland. Những nước này có lãnh thổ ngoài vùng đất Á lục địa còn có thêm các đảo, quần đảo trong khu vực Bắc cực được xác định theo thuyết lãnh thổ kề cận ( phần đất hình rẻ quạt nằm trong khu vực Bắc Cực )"],["p","Xác định phần đất: Nối hai điểm tận cùng của đường biên giới QG nối liền với Bắc Cực."],["p","-Các nước Bắc cực không có quan điểm giống nhau về vấn đề xác lập chủ quyền và quyền lực ở Bắc cực. Việc nước này hoặc nước khác quy định khu vực Bắc cực không giải quyết vấn đề chế độ pháp lý của vùng biển nằm trong khu vực Bắc cực."],["p","-Chế độ pháp lý của từng vùng biển Bắc cực riêng biệt được đánh giá riêng, xuất phát từ thực tế hình thành trật tự pháp luật đã được công nhận từ lâu trên cơ sở các lợi ích quân sự, kinh tế, chính trị và các lợi ích khác của các nước Bắc cực."],["p","Lãnh thổ di động? Lãnh thổ kế cận ( lãnh thổ hình rẻ quạt) -> chỉ áp dụng đối với các quốc gia giáp vùng Bắc Cực thôi ; Lãnh thổ hải ngoại ? Lãnh thổ kín"],["p","Lãnh thổ di động: được hiểu là là khi máy bay, tàu biển, tàu vũ trụ, đường ống ngầm, cáp ngầm có mang cờ quốc gia hoặc dấu hiệu riêng biệt, hợp pháp của quốc gia đang nằm hoặc đang hoạt động ở vùng trời quốc tế, vùng biển quốc tế, khoảng không vũ trụ thì chúng được coi là một bộ phận lãnh thổ di động của quốc gia đó."],["p","Lãnh thổ kế cận: các QG tiếp giáp Bắc Cực được chiếm phần lãnh thổ thêm"],["p","vào lãnh thổ nước mình và được theo hình rẻ quạt với tâm là đỉnh Bắc Cực. Nhưng băng đang tan lộ ra tiềm năng lớn như dầu mỏ, tuyến đường hàng hải mới xảy ra tranh chấp. Nam Cực không có QG trực tiếp xác lập vì không tiếp giáp QG nào lãnh thổ chung của cộng đồng QT (mọi hoạt động vì mục đích hòa bình, nghiêm cấm các hành động vũ lực)"],["p","Lãnh thổ kín: phần lãnh thổ nằm gọn trong lòng QG khác, không có đường thông ra biển"],["p","vd: lào ( như Lavia, lãnh thổ của Tây Ban Nha nằm trong lãnh thổ Cộng hòa Pháp)"],["p","Lãnh thổ hải ngoại: một bộ phận lãnh thổ QG nằm tách xa các vùng còn lại, thâm chí ở các châu lục khác (lãnh thổ hải ngoại thuộc anh) ( Lãnh thổ hải ngoại của Pháp bao gồm các vùng lãnh thổ do Cộng hòa Pháp quản lý nằm bên ngoài ranh giới địa lý của Châu Âu)"],["p","Xác lập chủ quyền đối với lãnh thổ"],["p","-> Các Nguyên tắc xác lập chủ quyền? Tập trung Nguyên tắc chiếm hữu thực sự là gì? Tại sao Trung Quốc cũng công bố hai đảo này nhưng k được kết luận là lãnh thổ qg, có phải là nguyên tắc chiếm hữu thực sự hay ko hay nguyên tắc gì?"],["p","Trong quá trình phát triển của quốc gia, có 3 nguyên tắc xác lập chủ quyền quốc gia đối với lãnh thổ phổ biến và chủ yếu sau đây:"],["p","Xác lập chủ quyền bằng chiếm hữu"],["p","Xác lập chủ quyền bằng chuyển nhượng tự nguyện"],["p","Xác lập chủ quyền theo thời hiệu"],["p","Nguyên tắc xác lập chủ quyền bằng chiếm hữu"],["p","Xác lập chủ quyền quốc gia đối với lãnh thổ theo nguyên tắc chiếm hữu có nghĩa là hành động của một quốc gia tuyên bố xác lập chủ quyền đối với một vùng lãnh thổ vô chủ, không thuộc chủ quyền của bất kỳ quốc gia nào và thời điểm xác lập. Từ định nghĩa trên ta rút ra được các vấn đề trọng tâm như sau:"],["p","Chủ thể thực thi quyền chiếm hữu: Nhà nước (một quốc gia, nhà nước cụ thể). Trừ trường hợp các cá nhân, pháp nhân, tổ chức được nhà nước uỷ quyền; tuy nhiên khi nhà nước đã uỷ quyền cho các chủ thể trên thì việc xác lập chủ quyền lãnh thổ là hành vi nhân danh nhà nước."],["p","Lãnh thổ mà quốc gia chiếm hữu: Lãnh thổ vô chủ hoặc lãnh thổ bị bỏ rơi. ( Lãnh thổ vô chủ là lãnh thổ mà từ thời điểm phát hiện ra trở về trước thì chưa có quốc gia nào xác lập chủ quyền; lãnh thổ bỏ rơi là một vùng lãnh thổ mà một quốc gia đã xác lập chủ quyền nhưng sau đó từ bỏ quyền chiếm hữu của mình )"],["p","Nguyên tắc xác lập chủ quyền bằng chiếm hữu được chia thành 2 dạng: chiếm hữu tượng trưng và chiếm hữu thực sự."],["p","Các giai đoạn phát triển của nguyên tắc này:"],["p","Từ trước đến cuối thế kỷ XIX:"],["p","Nguyên tắc chiếm hữu tượng trưng: xuất phát từ học thuyết quyền khám phá trước tiên, các quốc gia chỉ cần phát hiện ra vùng lãnh thổ và thực hiện đủ 3 điều kiện sau để xác lập"],["p","Thứ nhất, vùng lãnh thổ vô chủ"],["p","Thứ hai, việc xác lập chủ quyền của quốc gia là hành động của các cá nhân: nhà thám hiểm,... và để lại trên đó các dấu tích: các cột mốc, các bia đá; không cần có sự duy trì của chính quyền nhà nước trên lãnh thổ đó. ( việc xác lập nhân danh cá nhân )"],["p","Thứ ba, nhà nước mà nhà thám hiểm là công dân phải đưa ra tuyên bố chính thức về việc xác lập chủ quyền của quốc gia đối với vùng lãnh thổ mới phát hiện."],["p","Tuy nhiên, nguyên tắc chiếm hữu tưởng chừng đã bộc lộ những thiếu sót và hạn chế:"],["p","Một là việc chiếm hữu theo cách này rất dễ dàng đối với vùng đất, đảo nhỏ nhưng ngược lại, đối với những vùng rộng lớn nếu chỉ được lưu lại bằng chứng tại một điểm nào đó thì thực chất nhà thám hiểm chưa khám phá hết vùng đất mới mà quốc gia đã xác lập chủ quyền hoàn toàn đối với vùng đất này => điểm chưa hợp lý của nguyên tắc."],["p","Vd: ngày 24/6/1497, John Cabot cùng thủy thủ đoàn chỉ mới đặt chân lên bờ biển Bonavista của Canada ngày nay và chỉ đi dọc từ vĩ tuyến 56 đến 38 Bắc mà nước Anh đã đòi xác lập chủ quyền đối với tất cả vùng Bắc Mỹ rộng lớn."],["p","Hai là do điều kiện thông tin lúc đó chưa phát triển nên đã dẫn tới tình trạng các quốc gia không được thông tin đầy đủ và kịp thời về một vùng lãnh thổ đã được một quốc gia khác phát hiện => Tái xác lập chủ quyền -> tranh chấp phát sinh"],["p","Ba là những dấu tích, chứng cứ như cờ, cây thập tự, cột gỗ được lưu lại trên các vùng lãnh thổ mới phát hiện không phải bao giờ cũng nguyên vẹn qua thời gian"],["p","=> Tái xác lập -> tranh chấp phát sinh"],["p","=> Từ các điểm hạn chế trên mà nguyên tắc chiếm hữu tượng trưng dần được thay thế bằng nguyên tắc chiếm hữu thực sự."],["p","Từ cuối thế kỷ XIX đến nay:"],["p","Nguyên tắc chiếm hữu thực sự được thừa nhận và thay thế thông qua sự kiện các quốc gia ở Châu Âu cùng với Hoa Kỳ tranh chấp nhau các vùng lãnh thổ ở Duyên hải miền Trung và Duyên hải Châu Phi. 13 quốc gia châu Âu và Hợp chủng quốc Hoa Kỳ để tổ chức một Hội nghị tại Berlin khi tranh chấp diễn ra quá căng thẳng"],["p","=> Định ước Berlin( VB PL Quốc tế )26/2/1885 ra đời và đặt ra các điều kiện chủ yếu mà các qg phải đáp ứng để khẳng định 1 vùng đất mới mà qg đó phát hiện và chiếm hữu thuộc chủ quyền của mình. Hai điều kiện đó được quy định lần lượt tại điều 34 ( quốc gia nào chiếm hữu một vùng lãnh thổ mới ở châu Phi đều phải thông báo cho các nước tham gia hội nghị biết ) và điều 35 ( các nước chiếm hữu phải đảm bảo sự tồn tại của một tổ chức chính quyền tại vùng lãnh thổ họ chiếm hữu để thi hành luật pháp, và khi cần thiết để bảo vệ tự do buôn bán và quá cảnh trong các điều kiện đã được quy định)"],["p","=> Định ước Berlin là nền tảng để tạo ra nguyên tắc chiếm hữu thực sự"],["p","=> Vậy nó khác với nguyên tắc chiếm hữu tượng trưng ở điểm:"],["p","Nguyên tắc chiếm hữu thực sự phải là hành động nhân danh nhà nước, có cspl vững chắc hơn (không phải hành động của cá nhân, cá nhân không phải chủ thể trong luật quốc tế)"],["p","Cần phải có sự hiện diện của chính quyền nhà nước; cần phải phát hiện, chiếm hữu và thực thi chủ quyền trên lãnh thổ đó một cách rõ ràng bằng bộ máy nhà nước."],["p","Nguyên tắc chiếm hữu thực sự bao gồm 4 điều kiện:"],["p","Những vùng đất, đảo đc quốc gia chiếm hữu phải là lãnh thổ vô chủ, không nằm hoặc không còn nằm trong hệ thống địa lý hành chính của một quốc gia nào."],["p","Vd: năm 1606, TBN đã chiếm hữu đảo Palmas và các đảo khác trong quần đảo Philippines nhưng việc chiếm hữu này chỉ mang tính chất tượng trưng, chưa có tổ chức hành chính và biện pháp cai trị nào, và cũng chưa có bất kỳ một văn bản nào của nhà nước chính thức xác lập chủ quyền đối với vùng đảo này. Đến cuối tk XVIII, TBN rút khỏi Palmas và sau đó từ bỏ chủ quyền của mình trên hòn đảo này. Hòn đảo này sau đó đã được Hà Lan chiếm hữu; nhưng cuộc chiến tranh Mỹ - Tây Ban Nha kết thúc và hành động nhượng quần đảo Palmas cho Mỹ của TBN đã gây ra tranh chấp lớn. (1)"],["p","Việc chiếm hữu đó phải là hành động của nhà nước."],["p","Nghĩa là việc chiếm hữu 1 vùng lãnh thổ phải được thực hiện bởi những viên chức đại diện cho nhà nước hoặc những người được nhà nước ủy quyền thì mới có giá trị pháp lý để thực hiện việc ktra, kiểm soát, quản lý, khai thác,… ở trên khu vực lãnh thổ đó. Khi nhà nước đã uỷ quyền cho các chủ thể thì việc xác lập chủ quyền lãnh thổ là hành vi nhân danh nhà nước. Hành động chỉ nhân danh cá nhân thì yếu"],["p","-> Nhân danh nhà nước sẽ vững chắc"],["p","Việc chiếm hữu phải thực sự."],["p","Việc chiếm hữu mang tính thực sự khi có sự hiện diện của chính quyền nhà nước trong việc thiết lập, kiểm soát, quản lý, thậm chí là tài phán,bảo vệ và thực hiện chủ quyền quốc gia trên vùng lãnh thổ một quốc gia đã chiếm hữu và xác lập chủ quyền."],["p","Việc chiếm hữu phải hoà bình (không dùng vũ lực), liên tục, được cộng đồng quốc tế công nhận."],["p","Nghĩa là việc chiếm hữu và xác lập chủ quyền quốc gia đối với vùng lãnh thổ không phải là kết quả của hành vi tước đoạt chủ quyền của một quốc gia khác bằng những hành vi sử dụng hoặc đe dọa sử dụng vũ lực."],["p","Đồng thời việc chiếm hữu và xác lập chủ quyền đối với vùng lãnh thủ mới phải được thực hiện công khai và được dư luận đương thời chấp nhận."],["p","Được cộng đồng quốc tế công nhận có 2 phương pháp:"],["p","Công nhận minh thị : các qg gửi công hàm,thông báo, thư chúc mừng, hay ra thông báo, quy tắc về qg này đã xác lập lãnh thổ đó"],["p","Công nhận mặc thị : im lặng, không phản đối -> mặc nhiên được hiểu là đồng ý"],["p","Vd: Trong vụ tranh chấp lãnh thổ Đông Greenland giữa Đan Mạch và Hà Lan, Toà án quốc tế ghi nhận sự không phản đối của Na Uy để cũng cố cho danh nghĩa Đạt được của Đan Mạch đối với vùng Đông Greenland."],["p","Nguyên tắc xác lập chủ quyền bằng sự chuyển nhượng tự nguyện."],["p","Chuyển nhượng lãnh thổ về sự chuyển giao một cách hòa bình chủ quyền quốc gia trên một lãnh thổ của một quốc gia này sang quốc gia khác bằng việc ký kết điều ước quốc tế."],["p","Tiền lệ :"],["p","Nga Hoàng II bán vùng lãnh thổ Alaska cho hợp chủng quốc Hoa Kỳ với giá 7.2 triệu USD"],["p","Pháp đã bán vùng đất Louisiane Cho Hợp chủng quốc Hoa Kỳ thông qua hiệp ước được ký ngày 30/4/1803."],["p","Liên hệ thực tiễn Việt Nam: Hiệp ước Nhâm Tuất 1862 nhà nước nhượng lãnh thổ Nam Kỳ gồm: Biên Hòa, Gia Định, Định Tường cho thực dân Pháp không phải chuyển nhượng tự nguyện do không xuất phát từ ý muốn của bên chuyển nhượng."],["p","Nguyên tắc xác lập chủ quyền theo thời hiệu."],["p","Nguyên tắc này xuất hiện từ thời kỳ “quyền chiến tranh”"],["p","Một quốc gia sẽ xác lập chủ quyền đối với một vùng lãnh thổ nếu họ đã chiếm hữu trong một thời gian dài mà không có sự tranh chấp với quốc gia khác."],["p","Về phương diện pháp lý, chủ quyền đối với vùng lãnh thổ này còn đang là đối tượng gây tranh cãi."],["p","Theo nguyên tắc này muốn xác lập chủ quyền lãnh thổ theo thời hiệu phải đáp ứng đồng thời hai điều kiện sau đây:"],["p","Là vùng lãnh thổ vô chủ, quốc gia có danh nghĩa chủ quyền nhưng đã từ bỏ => dẫn đến lãnh thổ bị từ bỏ."],["p","Quốc gia mới xác lập chủ quyền thật sự đối với vùng lãnh thổ bị từ bỏ đó một cách công khai, liên tục và hòa bình."],["p","LQT hiện đại không thừa nhận nguyên tắc này, trừ trường hợp quốc gia xác lập chủ quyền lãnh thổ đối với những vùng lãnh thổ mà họ chiếm hữu không thông qua hành vi xâm lược."],["p","=> Khác biệt so với nguyên tắc chiếm hữu thực sự: chỉ chiếm hữu trên thực tế đó chứ chưa có cơ sở pháp lý, công nhận rõ ràng, thực hiện quyền kiểm soát, quản lý tài phán trên lãnh thổ đó. Điểm khác nữa là vùng lãnh thổ xác lập theo nguyên tắc thời hiệu phải là vùng lãnh thổ đã có chủ nhưng chủ đã từ bỏ"],["p","-> Liên hệ thực tiễn Việt Nam trong việc xác lập chủ quyền đối với hai quần đảo Hoàng Sa và Trường Sa"],["p","- Chính quyền hai huyện đảo Hoàng Sa và Trường Sa của Việt Nam hiện đang thực hiện nhiệm vụ quản lý của mình. Nghị quyết của Quốc hội nước CHXHCN Việt Nam khóa IX, kỳ họp thứ 5 ngày 23-6-1994 phê chuẩn Công ước của LHQ về luật biển năm 1982 nêu: “Quốc hội một lần nữa khẳng định chủ quyền của Việt Nam đối với hai quần đảo Hoàng Sa và Trường Sa và chủ trương giải quyết các bất đồng liên quan đến biển Đông thông qua thương lượng hòa bình."],["p","Quốc hội nhấn mạnh: “Cần phân biệt vấn đề giải quyết tranh chấp quần đảo Hoàng Sa, quần đảo Trường Sa với các vấn đề bảo vệ các vùng biển và thềm lục địa thuộc chủ quyền, quyền chủ quyền và quyền tài phán của Việt Nam, căn cứ vào những nguyên tắc và những tiêu chuẩn của Công ước của Liên hợp quốc về luật biển năm 1982”."],["p","-CSPL khẳng định chủ quyền : Điều 1 về phạm vi điều chỉnh của Luật Biển Việt Nam được Quốc hội thông qua ngày 21/6/2012 cũng đã khẳng định “Luật này quy định về đường cơ sở, nội thủy, lãnh hải, vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế, thềm lục địa, các đảo quần đảo Hoàng Sa, quần đảo Trường Sa và quần đảo khác thuộc chủ quyền, quyền chủ quyền, quyền tài phán quốc gia của Việt Nam…"],["p","-Vậy Vn ta có đủ 4 điều kiện của LQT hiện đại về nguyên tắc chiếm hữu thật sự 2 quần đảo Trường Sa và Hoàng Sa ít nhất từ tk XVII khi nó chưa thuộc chủ quyền của bất kỳ quốc gia nào và Nhà nước VN đã thực hiện thật sự chủ quyền của mình một cách liên tục và hòa bình."],["p","Lí do Trung Quốc không được công nhận:"],["p","Tất cả tài liệu liên quan mà TQ đưa ra để chứng minh một số chủ quyền với đảo cũng chỉ xác nhận Trung Quốc biết sự hiện hữu của quần đảo Hoàng Sa, Trường Sa thôi chứ không minh chứng được sự chiếm hữu, bởi vì những tài liệu đó quá rời rạc, lẻ tẻ, hơn nữa rất mập mờ, nếu không nói là hoàn toàn thiếu cơ sở nghiêm túc."],["p","Tất cả các tài liệu do Trung Quốc đưa ra chỉ dẫn chứng sự phát hiện hải đảo."],["p","Thế nhưng, theo luật quốc tế, những phát hiện hoặc kiến thức về địa dư, kể cả sự lui tới của những dân chài lưới trên hải đảo, chưa phải là một yếu tố đủ để chứng minh quan hệ về chủ quyền trên đất đai khám phá ra."],["p","Muốn cho sự phát hiện có một hiệu quả pháp lý, nó phải được tiếp theo bằng một sự chiếm hữu thực sự (occupation effective) kèm theo một ý chí biểu hiện chủ quyền bằng những hành vi của một cơ quan quyền lực nhà nước tối cao chứ không chỉ đơn thuần là một hành động tư nhân."],["p","Và hành động của Trung Quốc Sử dụng vũ lực để xâm lược quần đảo Hoàng Sa năm 1974 và một số đảo trên quần đảo Trường Sa của CHXHCN VN năm 1988 Nhằm xác lập chủ quyền của Trung Quốc trên hai quần đảo này cũng được xem là trái với nguyên tắc chiếm hữu thực sự, trái Với luật quốc tế về xác lập chủ quyền của quốc gia đối với lãnh thổ. Hành vi xâm lược quần đảo Hoàng Sa và một số đảo trên quần đảo Trường Sa của Trung Quốc đã bị Việt Nam cũng như các quốc gia trên thế giới lên án và phản đối mạnh mẽ."]]},{"h":"II. Biên giới quốc gia","b":[["p","Biên giới quốc gia là gì? Ý nghĩa pháp lý của việc xác lập biên giới quốc gia"],["p","Về phương diện pháp lý và địa lý, bgqg chính là phần bao bọc bên ngoài lãnh thổ quốc gia, không có quốc gia nào có lãnh thổ xác định mà lại ko có biên giới quốc gia"],["p","Theo luật quốc tế hiện đại, Biên giới quốc gia là ranh giới phân định lãnh thổ của quốc gia này với lãnh thổ của quốc gia khác hoặc với các vùng mà quốc gia có quyền chủ quyền trên biển."],["p","Ranh giới này hoặc là đường ranh giới được ghi nhận trên bản đồ và được đánh dấu trên thực địa hoặc là mặt thẳng đứng đi qua đường ranh giới nói trên xác định giới hạn bên ngoài của lãnh thổ quốc gia. Đây chính là giới hạn không gian của quyền lực tối cao của quốc gia đối với lãnh thổ."],["p","VD: Trên bộ, VN tiếp giáp với các quốc gia như Lào, Campuchia, Trung Quốc. Một bên là chủ quyền của VN và chủ quyền của nước khác."],["p","Điều 1 Luật biên giới quốc gia năm 2003 của Việt Nam quy định:"],["p","\"Biên giới quốc gia của nước Cộng hoà xã hội chủ nghĩa Việt Nam là đường và mặt thẳng đứng theo đường đó để xác định giới hạn lãnh thổ đất liền, các đảo, các quần đảo trong đó có quần đảo Hoàng Sa và quần đảo Trường Sa, vùng biển, lòng đất, vùng trời của nước Cộng hoà xã hội chủ nghĩa Việt Nam\""],["p","Biên giới quốc gia gồm:"],["p","- Biên giới trên bộ: Là đường biên giới được xác định trên đất liền, trên đảo, trên sông, hồ, kênh, biển nội địa… Bgtb được thiết lập trên cơ sở thỏa thuận giữa các quốc gia có lãnh thổ tiếp giáp vs nhau. Biên giới trên bộ phổ biến được quy định trong các điều ước quốc tế giữa các nước hữu quan (trừ một số trường hợp ngoại lệ) và một số điều ước quốc tế đặc biệt hoặc các quyết định của các cơ quan tài phán quốc tế khi các bên hữu quan đồng ý."],["p","VD: Trên bộ, VN tiếp giáp với các quốc gia như Lào, Campuchia, Trung Quốc. Một bên là chủ quyền của VN và chủ quyền của nước khác. Được thể hiện qua các cột mốc mốc giới"],["p","Trong trường hợp đặc biệt, biên giới trên bộ có thể được thiết lập bằng các điều ước quốc tế đa phương, ví dụ VN và các nước trong khu vực phải hợp tác để xác định hai cột mốc biên giới tại các ‘ ngã ba’ biên giới là điểm tiếp giáp trên đất liền giữa ba nước VN, Lào, Campuchia và điểm tiếp giáp giữa 3 nước Vn, Lào, TQ."],["p","- Biên giới trên biển: Ranh giới phía ngoài của lãnh hải do quốc gia ven biển thiết lập phù hợp với công ước của LHQ về luật biển năm 1982. Là đường vạch ra để phân định vùng lãnh hải ( thuộc chủ quyền) của quốc gia với vùng biển tiếp liền mà quốc gia ven bờ có quyền chủ quyền ( TGLH, ĐQKT, thềm lục địa )hoặc với nội thủy, lãnh hải của quốc gia khác có bờ biển đối diện hay kề bên bờ biển của quốc gia này."],["p","Biên giới trên biển sẽ được xác định khi hai quốc gia đối diện hoặc tiếp giáp nhau và khi quốc gia không đối diện, không tiếp giáp với quốc gia nào trên biển:"],["p","trong trường hợp qg không đối diện hoặc tiếp giáp với quốc gia nào trên biển thì biên giới quốc gia trên biển chính là ranh giới để giới hạn nội thủy, lãnh hải của quốc gia với các vùng quốc gia có quyền chủ quyền trên biển ( vùng tiếp giáp lãnh hải, vùng đặc quyền kinh tế và thềm lục địa)"],["p","Biên giới trên biển được thể hiện trên các hải đảo hoặc bằng các tọa độ địa lý có ghi rõ hệ thống trắc địa ddc sử dụng"],["p","- Khi quốc gia có biển: —---đối diện"],["p","—------ tiếp giáp liền kề với quốc gia khác ( chồng lấn ở vùng biển chủ quyền) -> chồng lấn lên lãnh hải của hai bên. -> phân định đường biên giới trên biển"],["p","-> Đường biên giới trên biển là đường trung tuyến ( khoảng cách từ trung điểm đến đường cơ sở của qg bằng nhau) nhưng phải đảm bảo yếu tố công bằng về mặt lịch sử. CSPL: điều 15 Unclos"],["p","VD: Ở VN, ở phía bắc là Vịnh Bắc Bộ có hiệp định phân định Vịnh Bắc Bộ chính là đường phân định biên giới quốc gia trên biển với Trung Quốc."],["p","Khi qg k có biển đối diện liền kệ với quốc gia khác hoặc chỉ chồng lấn ở vùng biển thuộc quyền chủ quyền -> Cần xác định ranh giới biển chung để phân định quyền chủ quyền của mỗi quốc gia"],["p","- Biên giới vùng trời và biên giới lòng đất: Được luật quốc tế thừa nhận chung dưới dạng tập quán quốc tế trên cơ sở của đường biên giới trên bộ, trên biển. Tuân thủ những biên giới này là nghĩa vụ bắt buộc của tất cả các quốc gia."],["p","Biên giới lòng đất là mặt phẳng được xác định dựa trên đường biên giới trên bộ và biên giới trên biển của quốc gia kéo dài tới tận tâm của trái đất. Biên giới lòng đất được thừa nhận và quy định trong các điều ước quốc tế và cụ thể hóa trong pháp luật quốc gia."],["p","Biên giới vùng trời của quốc gia là ranh giới phân định vùng trời thuộc chủ quyền của quốc gia này với vùng trời thuộc chủ quyền của quốc gia khác hoặc vùng trời thuộc chủ quyền của quốc gia với vùng trời quốc tế. Biên giới vùng trời của quốc gia gồm hai bộ phận là biên giới sườn và biên giới trên cao."],["p","Biên giới sườn là mặt phẳng đứng được dựng qua các điểm nằm trên biên giới vùng đất, vùng nước của lãnh thổ quốc gia và có hướng chạy thẳng vào tâm của trái đất"],["p","Còn biên giới trên cao là ranh giới để phân định vùng trời thuộc chủ quyền của quốc gia và vùng trời quốc tế. Hiện nay luật quốc tế vẫn chưa có quy định đến định độ cao vùng trời thuộc chủ quyền quốc gia từ bề mặt của trái đất lên"],["p","CSPL : điều 5 luật biên giới quốc gia ( xác định được biên giới các vùng )"],["p","Biên giới trên không xác định từ mặt phẳng thẳng đứng từ biên giới trên đất liền,biên giới trên biển lên vùng trời VD: đường biên giới vùng trời trong trường hợp xác định mặt phẳng thẳng đứng từ biên giới trên biển đi lên là đường phân định lãnh thổ quốc gia với lãnh thổ quốc tế. Hay là vùng trời QG ( ptiện bay phải xin phép ) với vùng trời quốc tế ( ptiện bay được tự do di chuyển )"],["p","Ý nghĩa pháp lý của việc xác lập biên giới quốc gia:"],["p","Biên giới qg là cơ sở xác định ranh giới lãnh thổ qg này với QG khác"],["p","Biên giới qg là cơ sở pháp lý để giới hạn chủ quyền của mỗi qg đối với lãnh thổ của mình"],["p","Cụ thể:"],["p","Nó giúp khẳng định chủ quyền của quốc gia đó đối với vùng lãnh thổ bất khả xâm phạm của quốc gia. Việc xác định biên giới của các quốc gia phải tuân thủ quy tắc chung và là nghĩa vụ bắt buộc của các quốc gia."],["p","Trong quá trình xác lập thì việc xác lập biên giới trên đất liền và biển là quan trọng nhất. Nó là cơ sở cho việc xác lập đường biên giới trên không và trong lòng đất được PLQT chung thừa nhận dưới dạng TQQT"],["p","Vd: Đường biên giới trên biển nhằm mục đích phân định ranh giới giữa các vùng biển thuộc chủ quyền quốc gia với vùng biển thuộc quyền chủ quyền, quyền tài phán của các quốc gia"],["p","Quy trình xác định biên giới trên bộ, biển được xác định như thế nào?"],["p","Nguyên tắc của luật quốc tế về phân định đường biên giới"],["p","Tùy vào xác định đường biên giới cũ đã có từ trước hay xđ đường biên giới mới mà áp dụng nguyên tắc phù hợp cho những trường hợp cụ thể"],["p","Nguyên tắc thỏa thuận ( đường biên giới hoàn toàn mới): các vấn đề cơ bản về thời gian, địa điểm, cách thức tiến hành; thỏa thuận xác định nguyên tắc hoạch định biên giới; thỏa thuận xác định chiều hướng chung của đường biên giới, kiểu biên giới áp dụng để hoạch định,.."],["p","Nguyên tắc xđ thông qua con đường tài phán ( trường hợp thỏa thuận không được )"],["p","Nguyên tắc Uti possidetis ( xác định trên cơ sở đường biên giới cũ và có sửa đổi, bổ sung )"],["p","Quá trình hoạch định bgqg trên bộ: luôn đạt được sự thỏa thuận giữa các bên liên quan"],["p","Xác định biên giới trên bộ"],["p","Biên giới trên bộ được xác định thông qua các bước hoạch định, phân giới và cắm mốc biên giới."],["p","+ Hoạch định biên giới quốc gia:"],["p","Đây là giai đoạn cực kỳ quan trọng với những hoạt động pháp lý nhằm xác định vị trí, hướng đi của đường biên giới. Toàn bộ việc hoạch định phải được tiến hành trên cơ sở tôn trọng chủ quyền của nhau, bình đẳng, các bên cùng có lợi. Phương pháp hoạch định là thông qua đàm phán và các con đường hoà bình khác. Nếu có tranh chấp các bên không tự giải quyết được phải nhờ đến bên thứ ba, kể cả thông qua con đường đàm phán quốc tế. Yêu cầu của hoạch định biên giới là:"],["p","- Phải đưa ra được các nguyên tắc để làm cơ sở cho việc xác định đường biên giới;"],["p","- Các điểm được lựa chọn để xác định vị trí, hướng đi của đường biên giới phải rõ ràng, tránh mơ hồ hay gây khó dễ, gây tranh chấp cho quá trình phân giới, cắm mốc sau này. Yêu cầu việc lựa chọn phải vừa đạt độ chính xác cao, vừa phù hợp với các yếu tố địa hình thực tế."],["p","Hoạch định biên giới quốc gia là định ra những vấn đề cơ bản về biên giới nhằm quy định cụ thể phương, hướng, vị trí của từng đoạn và của toàn tuyến biên giới."],["p","Trong quá trình hoạch định, các bên phải có sự miêu tả chỉ tiết đường biên giới trên bản đồ, thường kết thúc bằng điều ước hoạch định biên giỏi được ký kết giữa các nước có chung đường biên giới: Để tiến hành hoạch định biên giới, các nước thường thành lập cơ quan được gọi là Uỷ ban liên hợp hoạch định biên giới. Điều ước hoạch định biên giới do chính cơ quan này dự thảo. Nhìn chung các điều ước này chỉ phát sinh hiệu lực sau khi được các bên phê chuẩn."],["p","VD: ngày 30/12/1999 tại Hà Nội, Chính phủ hai nước đã ký “Hiệp ước hoạch định biên giới trên đất liền giữa Cộng hòa Xã hội chủ nghĩa Việt Nam và Cộng hòa Nhân dân Trung Hoa”"],["p","+ Phân giới trên thực địa ( mang tính hình thức )"],["p","Phân giới là quá trình thực địa hóa đường biên giới trong hiệp định. Đây là công việc mang tính vật chất, cụ thể để đưa đường biên giới được hoạch định trong các văn bản và bản đồ ra thực địa, cố định nó bằng các mốc dấu quốc giới với các phương pháp kỹ thuật đo đạc chính xác."],["p","+ Cắm mốc thực địa:"],["p","Việc cắm mốc có thể tiến hành theo phương pháp cuốn chiếu (phân giới đến đâu cắm mốc đến đó) hoặc phân giới xong mới thực hiện cắm mốc. Các mốc dấu biên giới đóng vai trò là cơ sở để xác định vị trí, hướng đi của đường biên giới trên thực địa. Căn cứ vào địa hình cụ thể, cột mốc biên giới thường đặt tại:"],["p","- Mỗi cửa khẩu;"],["p","- Các điểm chuyển hướng trọng yếu của đường biên giới, ở đỉnh núi, chân núi hoặc các địa điểm quan trọng;"],["p","- Các điểm trên đường quốc lộ, đường sắt, sông, suối mà đường biên giới cắt ngang qua..."],["p","Đối với mỗi cột mốc được xây dựng, đều phải lập hồ sơ cột mốc. Mỗi khi cần sửa chữa, thay đổi, phục hồi hay hủy bỏ mốc dấu biên giới đều phải do hai bên thỏa thuận cùng tiến hành nhưng không được làm thay đổi hướng đi của đường biên giới đã được hoạch định, phân vạch và cắm mốc chính thức."],["p","Kết thúc quá trình cắm mốc trên thực địa, ủy ban hỗn hợp phải lập bản đồ về biên giới kèm theo hiệp định về biên giới để các quốc gia ký kết hay phê chuẩn."],["p","Đôi khi, có trường hợp đường biên giới quốc gia đã được hoạch định, phân giới nhưng do nguyên nhân nào đó, cần phải kiểm tra lại hoặc vạch lại cho phù hợp với địa hình thực tế đã thay đổi. Trường hợp này người ta chỉ phân giới lại từng đoạn, ít có trường hợp phân giới lại toàn tuyến."],["p","VD: Cách thức tiến hành cắm mốc: theo phương pháp song phương"],["p","Sau khi Hiệp ước 1999 có hiệu lực (tháng 7-2000), Việt Nam và Trung Quốc thành lập 12 nhóm liên hợp, tiến hành phân giới cắm mốc theo phương pháp song phương (cùng nhau phân giới cắm mốc trên thực địa)."],["p","Xác định biên giới quốc gia trên biển"],["p","Trường hợp một: khi hai quốc gia có toàn bộ hoặc phần bờ biển đối diện hoặc liền kề nhau. hoặc chồng lấn trong lãnh hải của cả hai quốc gia."],["p","Lưu ý : chồng lấn ở vùng thuộc chủ quyền của các QG thì xác định đường biên giới còn chồng lấn ở vùng thuộc quyền chủ quyền ( bên ngoài lãnh hải ) thì là xác định ranh giới trên biển"],["p","-> Việc xác định đường biên giới chung chính là đường trung tuyến hay đường cách đều mà các bên cùng thỏa thuận, dựa trên sự công bằng về yếu tố lịch sử. Được ghi nhận trong các cam kết, điều ước quốc tế"],["p","VD: Hiệp định phân định Vịnh Bắc Bộ giữa Trung Quốc và Việt Nam"],["p","- Trường hợp hai: quốc gia không có biển đối diện, tiếp giáp liền kề với quốc gia khác"],["p","-> Việc xác định đường biên giới trên biển do quốc gia được quyền đơn phương xác định. Đây chính là ranh giới phía ngoài của lãnh hải, phải phù hợp với công ước LHQ 1982 về luật biển."],["p","Trong 3 qg Lào, Campuchia, TQ có một qg chỉ qua 2 bước, đó là nước nào? Tại sao?"],["p","VN và Cam"],["p","Phân giới đến đâu, cắm đến đó."],["p","Theo e, VN TQ, VN L, VN CPC đã hoàn thành hết 3 giai đoạn chưa. Nước nào chưa xong"],["p","VD: Có bao nhiêu cột mốc, năm nào, 31/12/2008"],["p","Cả 3 nước đã hoàn thành 3 giai đoạn với Việt Nam:"],["p","Việt Nam - Trung Quốc:"],["p","Từ năm 1974 đến 1979, Việt Nam và Trung Quốc đã ba lần tiến hành đàm phán về biên giới lãnh thổ, nhưng không đạt được kết quả do hai bên có lập trường, quan điểm khác xa nhau. Sau khi bình thường hóa quan hệ, từ tháng 10 -1992, hai bên tiến hành đàm phán lần thứ tư về biên giới lãnh thổ. Tháng 10-1993, hai bên đã đạt được Thỏa thuận về những nguyên tắc cơ bản giải quyết vấn đề biên giới lãnh thổ giữa Việt Nam – Trung Quốc, đồng ý lấy các Công ước Pháp – Thanh 1887 và 1895 cùng các văn kiện, bản đồ hoạch định, cắm mốc biên giới kèm theo làm căn cứ để xác định lại đường biên giới Việt – Trung; các khu dân cư hai bên đã sinh sống lâu đời thì duy trì cuộc sống ổn định của dân cư; đối với những đoạn biên giới sông suối thì giải quyết theo nguyên tắc của luật pháp và thực tiễn quốc tế."],["p","Ngày 30-12-1999 tại Hà Nội, Hiệp ước về biên giới trên đất liền Việt Nam – Trung Quốc (gọi tắt là Hiệp ước 1999) được ký kết."],["p","Ngay sau khi ký Hiệp ước về biên giới trên đất liền Việt Nam – Trung Quốc năm 1999, hai bên đã thành lập Ủy ban liên hợp phân giới cắm mốc biên giới trên đất liền Việt Nam - Trung Quốc; tiến hành cắm cột mốc đầu tiên tại cửa khẩu Móng Cái – Đông Hưng (tháng 12-2001)."],["p","Trong 2 năm 2002 và 2003, hai bên thoả thuận tiến hành công tác phân giới cắm mốc theo hình thức \"cuốn chiếu\" từ Tây sang Đông, tức là làm đến đâu dứt điểm đến đó. Trong giai đoạn này, do hai bên còn có nhận thức khác nhau về cách thức triển khai nên công tác phân giới cắm mốc tiến triển rất chậm, chỉ cắm được 89 cột mốc."],["p","Từ năm 2004 đến 2006, hai bên thỏa thuận triển khai công tác phân giới cắm mốc theo phương châm “dễ trước, khó sau” Đến ngày 31-12-2008, hai bên đã giải quyết dứt điểm toàn bộ các vấn đề còn tồn tại, hoàn thành công tác phân giới cắm mốc trên toàn tuyến biên giới đất liền Việt Nam – Trung Quốc."],["p","Việt Nam - Lào:"],["p","Ngày 18-7-1977, CHXHCN Việt Nam và Cộng hòa dân chủ nhân dân Lào đã ký Hiệp ước hoạch định biên giới và ngày 24-1-1986 ký Hiệp ước bổ sung Hiệp ước hoạch định biên giới giữa hai nước. Các hiệp ước này đã phân định đường biên giới giữa hai nước dài khoảng 2.340 km, tiếp giáp giữa 10 tỉnh của Việt Nam là và 10 tỉnh của Lào"],["p","Trong giai đoạn từ năm 1978 đến năm 1987, hai bên đã cơ bản hoàn thành công tác phân giới cắm mốc trên thực địa, đã phân giới được khoảng 1.877 km đường biên giới."],["p","Từ năm 1996 đến năm 2003, hai bên đã hoàn thành bộ bản đồ điện tử đường biên giới quốc gia Việt Nam - Lào tỷ lệ 1/50.000, đồng thời đã tiến hành phân giới trên thực địa 192 đoạn biên giới còn tồn đọng và giải quyết toàn bộ các mâu thuẫn sai lệch về đường biên, mốc giới."],["p","Tuy nhiên, hệ thống mốc giới hai nước được xây dựng những năm trước không còn thích hợp với điều kiện phát triển, mật độ thưa, 40km mới có một cột mốc. Chính vì vậy, năm 2004, hai bên đã phối hợp xây dựng “Dự án tăng dày và tôn tạo hệ thống mốc quốc giới Việt Nam - Lào”. Đến năm 2007, dự án đã được hai Chính phủ thông qua với tổng số mốc tăng dày và tôn tạo là 792 vị trí (826 cột mốc). Dự án bắt đầu thực hiện từ năm 2008 và sẽ kết thúc vào năm 2014."],["p","Việt Nam - Campuchia:"],["p","Việt Nam và Campuchia có đường biên giới trên bộ dài 1.137km, đi qua 10 tỉnh biên giới của Việt Nam và 10 tỉnh biên giới Campuchia."],["p","Vào năm 1983, Việt Nam và Cambodia đã tiến hành đàm phán và ký kết Hiệp ước về nguyên tắc giải quyết vấn đề biên giới giữa nước CHXHCN Việt Nam và nước Cộng hòa nhân dân Cambodia. Trong Hiệp ước này, hai nước đã thỏa thuận. Thực chất, Việt Nam và Cambodia đã áp dụng nguyên tắc Uti possidetis de juris để phân định biên giới trên bộ giữa hai nước với tinh thần thừa nhận đường biên giới do thực dân Pháp thiết lập từ khi xâm lược ba nước Đông Dương."],["p","Trên cơ sở của Hiệp ước về nguyên tắc giải quyết vấn đề biên giới giữa hai nước, ngày 27/12/1985 Hiệp ước hoạch định biên giới quốc gia giữa CHXHCN Việt Nam và Cộng hòa nhân dân Cambodia đã được ký kết. Từ năm 1986 hai bên tiến hành phân giới cắm mốc trên thực địa. Trong thời gian 1986 -1988, hai bên đã phân giới được hơn 200/1.137 km đường biên giới và cắm được 72/322 cột mốc. Năm 1989, do nội bộ phía Cambodia có khó khăn nên công tác phân giới cắm mốc tạm dừng lại."],["p","Ngày 10-10-2005, nhân chuyến thăm chính thức Việt Nam của Thủ tướng Cambodia Hun Sen, hai nước đã ký Hiệp ước bổ sung Hiện ước hoạch đinh biên giới quốc gia năm 1985. Theo đó, hai bên dự kiến cắm trên toàn tuyến biên giới hai nước tổng số 314 vị trí mốc (373 cột mốc)"],["p","Ngày 27-9-2006, hai bên khánh thành cột mốc đầu tiên số 171 tại cửa khẩu quốc tế Mộc Bài - Ba Vẹt, chính thức khởi động lại tiến trình phân giới cắm mốc trên toàn tuyến. Chính phủ hai nước đã thỏa thuận sẽ hoàn thành toàn bộ công tác phân giới cắm mốc biên giới Việt Nam - Cambodia vào năm 2012. Cho đến 2012, trên toàn tuyến biên giới Việt Nam và Cambodia, hai bên đã xác định được 226 vị trí, xây dựng xong 211 vị trí với 254 cột mốc, phân giới được khoảng 333 km."],["p","-> Việt Nam chưa phân giới hoàn tất với Campuchia do chưa có Hiệp ước nào quy định về việc phân xong cả. Hai bên mới chỉ cắm xong 83%"],["p","Việt Nam có khoảng 3051 cột mốc với TQ (1971), Lào(826), Campuchia (254)"],["p","Ví dụ:"],["p","Cột mốc số 0 A Pa Chải: Nơi đây là ngã ba biên giới đặc biệt của ba nước Việt Nam – Lào – Trung Quốc và được hoàn thành việc cắm cột mốc vào 27/6/2005."],["p","Cột mốc Hữu Nghị - Lạng sơn: nằm trên biên giới Việt Nam - Trung Quốc."],["p","Cột mốc Thác Bản Giốc-Cao Bằng: 2001"],["p","Cột mốc ngã ba Đông Dương: mốc biên giới của 3 quốc gia Việt Nam-Lào- Campuchia. 2007"],["p","Cột mốc 314: Đây là cột mốc cuối cùng trên đường biên giới giữa Việt Nam và Campuchia. 2012"],["p","Cột mốc 3143 Fansipan:"],["p","Cột cờ Lũng Cú: được xây dựng lần đầu vào thời Lý Thường Kiệt bằng cây sa mộc đến năm 1887 thì được xây lại dưới thời Pháp thuộc. Cột cờ Lũng Cú được trùng tu nhiều lần từ 1992 đến 2010"],["p","Cột mốc 428 Hà Giang: cột mốc 428 chính là điểm đánh dấu phần lãnh thổ Việt Nam với nước bạn Trung Quốc. 2001"],["p","Cột mốc 171 của khẩu quốc tế Mộc Bài - Ba Vẹt: Cột mốc giữa VN - Campuchia.2006"],["p","Việc xd cột mốc thì nước nào nước đó xây cột mốc hay theo nguyên tắc nào ?"],["p","Theo đó, mốc quốc giới là một trong những nội dung trọng tâm và được quy định tại Điều 10 Nghị định 140/2004/NĐ-CP. Cụ thể như sau:"],["p","Mốc quốc giới được cắm theo quy định của pháp luật Việt Nam và Điều ước quốc tế về biên giới đã được ký kết với nước láng giềng để đánh dấu đường biên giới quốc gia trên thực địa và được giữ gìn, bảo vệ giữ đúng vị trí, hình dáng, kích thước, ký hiệu, chữ và màu sắc đã được quy định."],["p","VD: chẵn lẻ, liên hệ VN L, VN TQ, VN CPC."],["p","TQ xây dựng cột mốc lẻ, VN xây dựng cột mốc chẵn"]]}]},{"t":"LUẬT NGOẠI GIAO VÀ LÃNH SỰ","n":5,"g":[{"h":"","b":[["p","*Luật ngoại giao và lãnh sự là gì: Đoàn"],["p","Cơ quan quan hệ đối ngoại: trong nước và nước ngoài ( thường trực, lâm thời)"],["p","Trong nước: nguyên thủ quốc gia, quốc hội, chính phủ và người đứng đầu chính phủ, bộ ngoại giao và người đứng đầu bộ ngoại giao."],["p","Nước ngoài:"],["p","Thường trực: cơ quan đại diện ngoại giao, cơ quan lãnh sự, các phái đoàn đại diện thường trực cho quốc gia ở nước ngoài."],["p","Lâm thời: quốc gia thường cử các phái đoàn đại diện cho quốc gia ở nước ngoài chuyên tham gia các hội nghị, diễn đàn ( thời hạn ngắn)."],["p","- Khái niệm ngoại giao, lãnh sự, luật ngoại giao và lãnh sự:"],["p","Ngoại giao là hoạt động của cơ quan làm công tác đối ngoại và các đại diện có thẩm quyền nhằm thực hiện chính sách, bảo vệ lợi ích, quyền hạn của quốc gia, dân tộc ở trong nước và trên thế giới, góp phần giải quyết các vấn đề quốc tế chung, bằng con đường đàm phán và các hình thức hòa bình khác."],["p","Lãnh sự: Lãnh sự là viên chức ngoại giao đứng đầu đại diện lãnh sự của một quốc gia được giao nhiệm vụ tại một vùng nhất định ở quốc gia khác với sự đồng ý rõ ràng, cụ thể của quốc gia ấy, nhằm bảo vệ ở vùng đó lợi ích của quốc gia, pháp nhân và công dân của mình, thúc đẩy sự phát triển quan hệ chính trị, kinh tế, khoa học, văn hóa giữa quốc gia cử đại diện và quốc gia tiếp nhận, tìm hiểu và thông tin về tình hình kinh tế – xã hội trong vùng của quốc gia sở tại."],["p","Quan hệ lãnh sự cũng là quan hệ chính thức giữa các quốc gia, được thiết lập"],["p","chủ yếu để bảo vệ quyền lợi của nước cử lãnh sự, công dân của nước cử lãnh"],["p","sự cư trú trên lãnh thổ nước nhận đại diện, giải quyết và phát triển quan hệ"],["p","giữa hai nước, công dân, pháp nhân của hai nước trong các lĩnh vực pháp lý,"],["p","kinh tế, thương mại, văn hóa…"],["p","Quan hệ ngoại giao là quan hệ chính thức, toàn diện,Đầy đủ trên tất cả các lĩnh vực của luật quốc tế giữa các chủ thể của luật quốc tế mà trước tiên là chủ yếu là các quốc gia. được thiết lập Nhằm thực hiện chính sách đối ngoại của quốc gia, Phát triển quan hệ hòa bình hợp tác, bảo vệ quyền, lợi ích của quốc gia và công dân quốc gia"],["p","Luật Ngoại giao và lãnh sự: là một ngành luật độc lập trong hệ thống pháp"],["p","luật quốc tế, bao gồm tổng thể các nguyên tắc và quy phạm pháp luật quốc tế. Nhằm tổ chức và thực hiện quan hệ về ngoại giao và lãnh sự giữa các chủ thể của LQT và điều chỉnh các vấn đề về quyền ưu đãi và miễn trừ dành cho các cơ quan quan hệ đối ngoại của quốc gia ở nước ngoài và các thành viên của các cơ quan này tại lãnh thổ của các quốc gia."],["p","Hãy cho biết đối tượng điều chỉnh: Đạt"],["p","-Tổ chức và hoạt động của các cơ quan quan hệ đối ngoại của nhà nước cùng thành viên của nó."],["p","-Các quyền ưu đãi và miễn trừ dành cho các cơ quan quan hệ đối ngoại của các quốc gia ở nước ngoài và các nhân viên của các cơ quan đó."],["p","-Hoạt động của các phái đoàn đại diện của các quốc gia trong quá trình viếng thăm hoặc tham gia hội nghị quốc tế."],["p","-Hoạt động của các tổ chức liên chính phủ và các quyền ưu đãi, miễn trừ dành cho các tổ chức này cũng như các thành viên của tổ chức tại lãnh thổ của các quốc gia."],["p","Hãy trình bày các nguyên tắc của luật ngoại giao và lãnh sự ( 5 nguyên tắc)"],["p","Nguyên tắc bình đẳng không phân biệt đối xử"],["p","Bình đẳng về ý chí và chủ quyền, không phân biệt đối xử giữa các quốc gia là một trong các nguyên tắc cơ bản của luật quốc tế hiện đại"],["p","Xuất phát từ nguyên tắc bình đẳng, không phân biệt đối xử của LQT => quan hệ ngoại giao lãnh sự giữa các quốc gia cũng phải được thiết lập và thực hiện trên cơ sở tự nguyện và bình đẳng về chủ quyền, không phân biệt đối xử với các quốc gia có chế độ chính trị, kinh tế, văn hóa, xã hội khác nhau"],["p","Ghi nhận trong các điều ước quốc tế song phương và đa phương,"],["p","Xuất phát từ nguyên tắc này, công ước Viên năm 1961 về quan hệ ngoại giao (Điều 47) và công ước Viên năm 1963 về quan hệ lãnh sự (Điều 72) đã quy định:"],["p","Trong khi thi hành những điều khoản của các công ước này, nước nhận đại diện không được có sự phân biệt đối xử giữa các nước"],["p","tuy nhiên, không coi là phân biệt đối xử nếu: Điều 47 và 72"],["p","Nguyên tắc thỏa thuận"],["p","Xuất phát từ nguyên tắc bình đẳng không phân biệt đối xử, trong việc thiết lập và thực hiện quan hệ ngoại giao, lãnh sự, nguyên tắc thỏa thuận được các quốc gia tôn trọng và áp dụng một cách triệt để nhất. yêu cầu quốc gia cử đại diện và quốc gia nhận đại diện đều phải thông qua trao đổi, thỏa thuận để đi đến sự thống nhất trong các quyết định cuối cùng."],["p","Nguyên tắc thỏa thuận trong việc thiết lập và thực hiện quan hệ ngoại giao, lãnh sự CSPL: Điều 8 khoản 2 Cuv 1961: Viên chức ngoại giao có thể là công dân của nước thứ ba với đk là nước đó đồng ý, nếu không đồng ý thì phải cử công chức ngoại giao là công dân nước mình."],["p","Nguyên tắc tôn trọng quyền ưu đãi, miễn trừ của cơ quan đại diện ngoại giao, cơ quan lãnh sự và thành viên của các cơ quan này"],["p","Đặt ra nghĩa vụ pháp lý cho quốc gia đại diện"],["p","Trong quan hệ với cơ quan ngoại giao, lãnh sự nước ngoài, nước nhận đại diện cần phải:"],["p","tôn trọng tư cách đại diện chính thức của nhà nước cử đại diện của các cơ quan này."],["p","tôn trọng và cam kết dành cho cơ quan, thành viên của cơ quan đại diện ngoại giao, lãnh sự được hưởng đầy đủ quyền ưu đãi và miễn trừ theo đúng quy định của CUV1961, CUV1963 hoặc theo tập quán về thông lệ quốc tế trong lĩnh vực ngoại giao, lãnh sự"],["p","CSPL: điều 29 Luật NG&LS thành viên được tôn trọng về thân thể"],["p","tạo mọi điều kiện thuận lợi nhất trong khả năng để cơ quan và thành viên của các cơ quan này được hưởng một cách tốt nhất, đầy đủ các quyền ưu đãi và miễn trừ theo quy định của điều ước quốc tế, tập quán quốc tế đã được các quốc gia hữu quan thừa nhận."],["p","CSPL: điều 21, điều 25 CUV1961"],["p","Nguyên tắc tôn trọng pháp luật và phong tục tập quán của nước nhận đại diện"],["p","Nguyên tắc này đặt ra nghĩa vụ pháp lý cho các cơ quan và thành viên của cơ quan ngoại giao, lãnh sự khi đại diện cho nhà nước mình thực hiện chức năng ngoại giao, lãnh sự trên lãnh thổ nước nhận đại diện."],["p","Nội dung của nguyên tắc là việc được hưởng các quyền ưu đãi và miễn trừ khi thực hiện chức năng ngoại giao, lãnh sự thì các cơ quan và thành viên của các cơ quan này cũng cần có nghĩa vụ tuân thủ, tôn trọng pháp luật cũng như phong tục tập quán của nước nhận đại diện"],["p","CSPL: Khoản 1 Điều 41 CUV1961, Khoản 1 điều 55 CUV1963"],["p","Viên chức ngoại giao có thể mở văn phòng luật sự tại nước sở tại"],["p","Cơ quan đại diện ngoại giao và lãnh sự không được làm việc vượt quá thẩm quyền (nhân danh qg được cử đi) để thực hiện hành vi vi phạm tại quốc gia sở tại."],["p","nguyên tắc không làm dụng quyền ưu đãi và miễn trừ ngoại giao, lãnh sự."],["p","Cơ quan và thành viên của cơ quan đại diện ngoại giao, lãnh sự không được làm dụng các quyền ưu đãi, miễn trừ để thực hiện những công việc không phù hợp với chức năng của cơ quan, của thành viên cơ quan đại diện ngoại giao, cơ quan lãnh sự."],["p","Nguyên tắc này được thể hiện ở một số nội dung nhu: Viên chức ngoại giao và viên chức lãnh sự không được hoạt động bất hợp pháp, trái với luật pháp quốc tế và pháp luật nước sở tại"],["p","CSPL: Điều 26, 41, 42, khoản 2 điều 36, khoản 2 điều 27 CUV1961"],["p","Điều 55,57,34, khoản 3 điều 50, khoản 1 điều 35 CUV1963"],["p","Nguồn của LNG và LS"],["p","Tập quán quốc tế"],["p","Điều ước quốc tế:"],["p","Công ước Vienna 1961"],["p","Công ước Vienna 1963"],["p","Luật ngoại giao và lãnh sự được xd dựa trên nguyên tắc nào của LQT"],["p","Vì nằm trong hệ thống pháp luật nên dựa trên các nguyên tắc của LQT ( 7 nguyên tắc). tuy nhiên LNG và LS cũng có những có nguyên tắc cơ bản của Luật NG và LS ( 5 nguyên tắc)."],["p","Phân biệt chức năng của cơ quan đại diện ngoại giao và chức năng của cơ quan lãnh sự ( điều 3 CƯv năm 1961): Gia Hân"],["t",[["","CQ đại diện ngoại giao","CQ lãnh sự"],["Giống nhau","Là cơ quan đại diện mang tính chất thường trực của quốc gia ở nước ngoài do quốc gia cử đi nhằm bảo vệ quyền lợi của quốc gia, của công dân nước cử đi"],["Khái niệm","là cơ quan của một quốc gia đóng trên lãnh thổ của một quốc gia khác để thực hiện quan hệ ngoại giao với quốc gia sở tại và với các cơ quan đại diện ngoại giao của các quốc gia khác ở nước sở tại. Bổ sung thông tin: Tên gọi của CQĐD của VN: Đại sứ quán ( điều 4 luật cơ quan đại diện của VN2009) -> VN chỉ thành lập CQĐD ngoại giao là Đại sứ quán ở nước ngoài. -> Nguyên thủ quốc gia có thẩm quyền bổ nhiệm Đại sứ quán và Công sứ quán -> Bộ trưởng Bộ ngoại giao có thẩm quyền bổ nhiệm Đại biện quán ( Điều 19 Luật cơ quan đại diện). Ở nước ta tồn tại Đại biện là đại biện mang tính chất lâm thời trong trường hợp chưa bổ nhiệm Đại sứ. Bổ nhiệm xong thì vai trò của ông đại sứ này chấm hết.","là cơ quan quan hệ đối ngoại của một nước tại nước ngoài thực hiện các chức năng lãnh sự trong khu vực lãnh thổ nhất định trên cơ sở thỏa thuận giữa các quốc gia hữu quan"],["Chức năng","Mang tính vĩ mô (Điều 3 Công ước Viên 1961) - Đại diện cho Nước cử đi tại Nước tiếp nhận; - Bảo vệ quyền lợi của Nước cử đi và của công dân Nước cử đi tại Nước tiếp nhận trong phạm vi cho phép của luật quốc tế; - Đàm phán với Chính phủ Nước tiếp nhận; - Tìm hiểu bằng mọi cách hợp pháp các điều kiện và các sự kiện tại Nước tiếp nhận và báo cáo với Chính phủ của Nước cử đi; - Thúc đẩy quan hệ hữu nghị và phát triển quan hệ kinh tế, văn hoá và khoa học giữa Nước cử đi và Nước tiếp nhận. -> Thiên về các quan hệ về mặt chính trị trên toàn bộ diện rộng -> Chỉ có thể thiết lập 1 cơ quan duy nhất thường đặt bên cạnh thủ đô của nước thiết lập đại diện và các hoạt động đều thông qua chính quyền trung ương của cơ quan đại diện. -> Chức năng rộng hơn nhiều so với chức năng của cơ quan đại diện lãnh sự. Khoản 2 điều 3 Cuv 1961: Cơ quan ddng cũng có thể kiêm thêm việc thực hiện các chức năng lãnh sự.","Mang tính vi mô (Điều 5 Công ước Viên 1963) Cụ thể trong việc cấp visa, hộ chiếu, giấy thông hành, tài liệu văn bản, công chứng, chứng thực giấy tờ, thăm hỏi khi có công dân nước mình bị nước sở tại giam giữ…. ->Thiên về chức năng về tư pháp, giấy tờ, đăng ký kết hôn, bảo vệ quyền và lợi ích cho công dân ở nước cử đại diện. Mang tính vi mô. -> Phân bổ tại nhiều khu vực lãnh sự tại các địa phương khác nhau"]]],["p","Phân biệt cấp ngoại giao, hàm ngoại giao, chức vụ ngoại giao: Bảo Hân"],["t",[["","Cấp ngoại giao","Hàm ngoại giao","Chức vụ ngoại giao"],["Khái niệm","- Là cấp của người đứng đầu cơ quan đại diện ngoại giao. - Cấp ngoại giao được quy định trong luật quốc tế. CSPL: điều 14 Công ước Vienna 1961 về quan hệ ngoại giao: Các quốc gia là tv của công ước này có quyền thiết lập quan hệ ngoại giao ở 1 trong 3 cấp. Đứng đầu đại sứ quán là đại sứ đặc mệnh toàn quyền","- Là chức danh nhà nước phong cho công chức ngành ngoại giao để thực hiện công tác đối ngoại ở trong và ngoài nước. - Do luật quốc gia quy định. - Hàm ngoại giao gắn bó suốt đời CSPL: Điều 5 Theo Pháp lệnh về hàm, cấp ngoại giao ngày 31/5/1995 của nước CHXHCN Việt Nam, hệ thống cấp và hàm ngoại giao VN","Là chức năng, nhiệm vụ cụ thể được bổ nhiệm cho viên chức ngoại giao công tác trong các cơ quan quan hệ đối ngoại nước ngoại. Người được bổ nhiệm chức vụ ngoại giao không đồng nghĩa được phong hàm ngoại giao - Do luật trong nước quy định - Gắn bó với nhiệm vụ. Hết nhiệm kỳ là hết chức vụ CSPL: Khoản 1 điều 9 Pháp lệnh về hàm cấp ngoại giao năm 1995 - Hàm không đồng nghĩa với chức vụ tương đương tùy trường hợp trong thực tế. - Chức vụ ngoại giao có thể bổ nhiệm cho cơ quan khác"],["Cơ sở xác lập","Thỏa thuận giữa nước bổ nhiệm với nước tiếp nhận đại diện ngoại giao về việc thiết lập cơ quan đại diện ngoại giao cụ thể tương ứng với một trong ba mức độ khác nhau","Nhà nước phong cho công chức ngành ngoại giao. Hàm ngoại giao do pháp luật quốc gia quy định.","Được cử, triệu hồi. Người được bổ nhiệm vào chức vụ ngoại giao có thể là công chức ngành ngoại giao hoặc công chức của ngành khác. Những người giữ chức vụ ngoại giao có thể không có hàm ngoại giao. Những người này thường giữ chức vụ có liên quan đến hoạt động chuyên môn về thương mại, văn hoá, quân đội,…"],["Hệ thống","Theo Công ước Vienna năm 1961, người đứng đầu của cơ quan đại diện ngoại giao được chia thành 3 cấp ( Điều 14) -Cấp Đại sứ/ Đại sứ của Giáo hoàng sẽ do nguyên thủ quốc gia hoặc Giáo hoàng bổ nhiệm -Cấp Công sứ/ Công sứ của Giáo hoàng, do Nguyên thủ quốc gia hoặc Giáo hoàng bổ nhiệm -Cấp đại biện ( Đại biện sứ) do Bộ trưởng Bộ ngoại giao bổ nhiệm","Hàm ngoại giao gồm: hàm Đại sứ, hàm Công sứ, hàm Tham tán( cấp ngoại giao cao cấp), hàm Bí thư thứ nhất, hàm Bí thư thứ hai( cấp ngoại giao trung cấp), hàm Bí thư thứ ba và hàm Tuỳ Viên ( cấp ngoại giao sơ cấp). Theo Pháp lệnh về hàm, cấp ngoại giao ngày 31/5/1995 của nước CHXHCN Việt Nam, hệ thống cấp và hàm ngoại giao VN được quy định như sau ( điều 5 ) -Cấp ngoại giao cao cấp: hàm Đại sứ, hàm Công sứ, hàm Tham tán. -Cấp ngoại giao trung cấp: hàm Bí thư thứ nhất, hàm Bí thư thứ hai. -Cấp ngoại giao sơ cấp: hàm Bí thư thứ ba, Tuỳ viên.","Theo Luật Cơ quan đại diện nước CHXHCN VN ở nước ngoài năm 2009, chức vụ ngoại giao VN gồm có: Đại sứ đặc mệnh toàn quyền, Đại sứ, Công sứ, Tham tán Công sứ, Tham tán, Bí thư thứ nhất, Bí thư thứ hai, Bí thư thứ ba, Tuỳ viên. (Điều 18)"]]],["p","—-------------"],["p","NỘI DUNG BÀI HỌC"],["p","Cơ cấu tổ chức:"],["p","Người đứng đầu CQĐDNG"],["p","Thành viên của CQĐDNG gồm:"],["p","Viên chức ngoại giao"],["p","Nhân viên hành chính-kỹ thuật"],["p","Nhân viên phục vụ"],["p","CSPL: Điều 1 CUV 1961"],["p","-> CQĐ DNG chỉ có Viên chức ngoại giao mới là người có hàm hoặc chức vụ ngoại giao còn những người khác không có hàm/chức vụ"],["p","Các quyền ưu đãi và miễn trừ ngoại giao"],["p","-> So sánh quyền ưu đãi miễn trừ của cơ quan đại diện ngoại giao và cơ quan lãnh sự"],["p","-> Quyền ưu đãi đặc biệt là quyền ưu đãi mà chỉ có người nước ngoài được hưởng những quyền ưu tiên, ưu đãi đặc biệt hoặc quyền đặc hưởng mà nước sở tại dành cho họ thậm chí chính công dân nước sở tại cũng không được hưởng."],["p","VD: Điều 22 Cuv 1961 trụ sở ngoại giao là bất khả xâm phạm mà bất kì cơ quan nào cũng không được vào khám xét trừ khi có sự đồng ý"],["p","Điều 21 cuv 1961 được hưởng quyền miễn trừ tuyệt đối về tài phán về hình sự."],["p","=> Nhìn chung hầu hết các quốc gia tiếp nhận đại diện, hai cơ quan này đều được hưởng các quyền ưu đãi và miễn trừ sau"],["p","- Quyền bkxp về trụ sở"],["p","- Quyền bkxp về hồ sơ và tài liệu"],["p","- Quyền bkxp về thư tín và túi ngoại giao, vali ngoại giao"],["p","- Quyền tự do thông tin liên lạc"],["p","- Quyền miễn thuế, lệ phí"],["p","- Quyền được treo quốc kỳ và quốc huy của nước cử đại diện"],["p","Khác nhau:"],["t",[["","Cơ quan đại diện ngoại giao","Cơ quan lãnh sự"],["Về quyền bất khả xâm phạm về trụ sở: về mặt nguyên tắc thì chính phủ cũng không được phép vào hoặc có bất kì hành động gây phương hại.","Điều 22 Cuv 1961 Quyền bất khả xâm phạm một cách tuyệt đối","khoản 1 Điều 31 Cuv 1963 Tuy nhiên, trong trường hợp xảy ra hoả hoạn hoặc thiên tai khác cần có biện pháp bảo vệ gấp rút thì có thể giả định là người đứng đầu cơ quan lãnh sự đồng ý. -> Chỉ mang tính chất tương đối"],["Về hồ sơ và tài liệu","điều 22 cuv 1961, điều 24","CSPL: điều 31 khoảng 4 Cuv 1963 -> Mang tính tương đối Trụ sở, đồ đạc, tài sản và các phương tiện giao thông của cơ quan lãnh sự sẽ không bị trưng dụng dưới bất kỳ hình thức nào vào các mục đích quốc phòng hoặc lợi ích công cộng. Nếu Vì những mục đích đó việc trưng mua là cần thiết, thì phải áp dụng mọi biện pháp có thể để tránh cản trở việc thực hiện chức năng lãnh sự và phải bồi thường một cách nhanh chóng, thích đáng và có hiệu quả cho Nước cử."],["Về túi ngoại giao, Vali ngoại giao","CSPL: điều 27 Cuv 1961 -> Nhấn mạnh quyền BKXP một cách tuyệt đối. Trong mọi trường hợp cho dù chính quyền nghi ngờ trong vali ngoại giao có vật dụng gì thì cũng k được khám xét mà chỉ được trả nó về","CSPL: điều 35 Cuv 1963 -> Mang tính tương đối Nghi ngờ có chức bom mìn thì có quyền yêu cầu mở ra để ktra. Nếu viên chức không đồng ý thì cũng không được mở. Kiên quyết k mở thì trả nó về nơi xuất phát."],["Về quyền được treo quốc kỳ, quốc huy","Điều 20 Cuv 1961 Được áp dụng trong việc công và tư","Điều 28 cuv 1963 Chỉ áp dụng cho việc công không dùng cho việc tư. khi những phương tiện này được sử dụng cho công việc chính thức."]]],["p","8"],["i","qt_cp2_1.jpg",1400,843]]},{"h":"4. So sánh viên chức ngoại giao và viên chức lãnh sự","b":[["p","Về cơ bản được hưởng quyền ưu đãi và miễn trừ tương đối giống như nhau:"],["i","qt_cp2_2.jpg",1400,744],["t",[["Điểm khác","Viên chức ngoại giao","Viên chức lãnh sự"],["BKXP về thân thể","Điều 29 Cuv 1961 -> Được bảo vệ tuyệt đối khi phạm bất kì tội gì","điều 41 cuv 1963 -> Mang tính tương đối vì khi họ phạm tội hình sự đặc biệt nghiêm trọng có thể bị bắt."],["Miễn trừ về tài phán: nguyên tắc đều được hưởng quyền miễn trừ tài phán","Điều 31 Khoản 2 điều 31 - Hình sự: được hưởng quyền miễn trừ tài phán một cách tuyệt đối. - Dân sự và hành chính: thực hiện với tư cách cá nhân -> được hưởng quyền miễn trừ về tài phán trừ một số điều qui định trong điều 31","Điều 43 Khoản 1 điều 43 - Hình sự: Chỉ được hưởng quyền tài phán về hình sự khi thi hành việc công ngoại trừ trường hợp phạm tội nghiêm trọng. - Trường hợp nghĩa vụ phải ra làm chứng: viên chức lãnh sự là nghĩa vụ bắt buộc ( điều 44 )"],["Nghĩa vụ ra làm chứng","Nghĩa vụ phải ra làm chứng: không có nghĩa vụ CSPL: Điều 31","Trường hợp nghĩa vụ phải ra làm chứng: viên chức lãnh sự là nghĩa vụ bắt buộc ( điều 44 )"]]]]},{"h":"5. Mối quan hệ giữa quan hệ ngoại giao và quan hệ lãnh sự","b":[["p","Cấp lãnh sự:"],["i","qt_cp2_3.jpg",1400,1867]]},{"h":"6. Chức năng của cơ quan lãnh sự","b":[["p","Chức năng chung cqls với cqng"],["i","qt_cp2_4.jpg",1400,870],["p","Chức năng riêng so với cqng"],["i","qt_cp2_5.jpg",1400,1867],["p",", CSPL, cho vd về bảo vệ quyền công dân ở nước ngoài"]]}]},{"t":"TRANH CHẤP QUỐC TẾ VÀ GIẢI QUYẾT TRANH CHẤP QUỐC TẾ","n":6,"g":[{"h":"","b":[["p","Khái niệm và phân loại tranh chấp quốc tế; phân tích các đặc trưng của tranh chấp quốc tế: Huy"]]},{"h":"1.1 Khái niệm tranh chấp quốc tế","b":[["p","Tranh chấp quốc tế là hoàn cảnh thực tế mà trong đó các chủ thể của LQT có những quan điểm pháp lý và quyền lợi mâu thuẫn trái ngược nhau dẫn đến các yêu sách hay đòi hỏi cụ thể trái ngược nhau."],["p","VD: - Tranh chấp liên quan đến chương trình hạt nhân giữa Iran-Mỹ"],["p","Tranh chấp về biên giới giữa Lào-Campuchia"],["p","Giải thích sự kiện Mỹ và liên quân tấn công Iraq lần 2 ngày 20/3/2003"]]},{"h":"1.2. Đặc điểm của tranh chấp quốc tế","b":[["p","- Chủ thể: Là Chủ thể của LQT mà trước tiên và chủ yếu là các quốc gia. Ngoài ra còn có tranh chấp giữa các tổ chức liên quốc gia, những vùng lãnh thổ có quy chế đặc biệt được công nhận là chủ thể của luật quốc tế.Đối tượng: Đa dạng, phát sinh trong mọi LV của ĐSQT."],["p","- Đối tượng: lãnh thổ, biên giới, chủ quyền quốc gia, những vùng biển mà quốc gia có quyền chủ quyền và quyền tài phán…"],["p","- Khách thể: những lợi ích về vật chất, tinh thần mà các chủ thể mong muốn có được, đạt được -> tham gia vào tranh chấp với các chủ thể khác"],["p","- Luật áp dụng: luật pháp quốc tế"],["p","VD: vấn đề hạt nhân ở Iran. Mỹ cho rằng Iran làm giàu Uranium để sản xuất hạt nhân, nhưng Iran bác bỏ và nói rằng làm giàu uranium để sản xuất điện năng."],["p","Cơ chế giải quyết TC: Áp dụng các biện pháp hòa bình giải quyết TCQT. Các bên TC được hoàn toàn tự do thỏa thuận để lựa chọn một biện pháp giải quyết TC, tuy nhiên những biện pháp đó phải dựa trên các NT cơ bản của LQT như NT hòa bình giải quyết TCQT, NT không dùng vũ lực hay đe dọa dùng VL trong quan hệ QT."],["p","Luật áp dụng: Luật QT bao gồm các NT và QPPLQT. PL QG chỉ được sử dụng để giải quyết TCQT trong trường hợp giải quyết CT tại trọng tài QT và phải có sự thỏa thuận của các chủ thể => phù hợp với NT bình đẳng về chủ quyền giữa các QG."]]},{"h":"1.3. Phân loại tranh chấp quốc tế","b":[]},{"h":"1.3.1. Dựa vào Số lượng chủ thể tranh chấp:","b":[["p","+ Tranh chấp song phương (Thái Lan, Campuchia – đền Preah Vihear)."],["p","+ Tranh chấp đa phương (tranh chấp có tính chất khu vực: biển Đông – 5 nước 6 bên, tranh chấp có tinh chất toàn cầu)."]]},{"h":"1.3.2. Dựa vào chủ thể tranh chấp","b":[["p","+ Tranh chấp giữa các quốc gia (biển Đông)"],["p","+ Tranh chấp giữa các tổ chức quốc tế"],["p","+ Tranh chấp giữa QG với tổ chức QT (tranh chấp TM giữa Nga và EU về việc Moskva áp mức thuế cao đối với nông sản và hàng chế tạo xuất khẩu của EU)."]]},{"h":"1.3.3. Dựa vào đối tượng tranh chấp","b":[["p","+ Tranh chấp về kinh tế thương mại"],["p","Vào những năm 1995 đến nay, Việt Nam đã phải đối mặt với hơn 30 vụ kiện chống bán phá giá. Đáng chú ý nhất là vụ kiện cá tra – basa và tôm do quốc gia Hoa Kỳ khởi kiện năm 2002. Vụ kiện giày da do EU khởi xướng năm 2005 hay vụ điều tra chống bán phá giá với giày không thấm nước do Canada khởi kiện năm 2009. Trong tình thế đó, tiến trình tố tụng trong những vụ kiện được thực hiện dựa trên cơ sở song phương cũng như phán quyết của bên khởi kiện sẽ là quyết định cuối cùng. Phương thức giải quyết tranh chấp thương mại quốc tế như vậy đã gây rất nhiều thiệt hại với các ngành kinh tế xuất khẩu của nước ta."],["p","+ Tranh chấp về biên giới, lãnh thổ, các đảo, quần đảo;"],["p","VD: Về phân định ranh giới biển có các vụ như vụ kiện về thềm lục địa giữa Đức và Đan Mạch năm 1967, vụ giữa Hy Lạp và Thổ Nhĩ kỳ năm 1976, vụ giữa Mỹ và Canada năm 1981, vụ giữa Ukraine và Romania năm 2010; Liên quan tranh chấp biên giới trên đất liền có các vụ như vụ kiện về đền Preah Vihear giữa Campuchia và Thái Lan năm 1957, vụ kiện giữa Libya và CH Chad năm 1990, vụ kiện giữa Benin và Nigeria năm 2002."],["p","+ Các vùng biển thuộc chủ quyền/quyền tài phán quốc gia"],["p","+ Tư cách thành viên của quốc gia tại TCQTLCP"],["p","+ TC về bảo hộ công dân"]]},{"h":"1.3.4. Căn cứ vào tính chất tranh chấp","b":[["p","+ Tranh chấp chính trị"],["p","+ Tranh chấp pháp lý"]]},{"h":"1.3.5. Căn cứ vào điều 34 Hiến chương LHQ","b":[["p","+ Tranh chấp định danh"],["p","+ Tranh chấp thông thường"]]},{"h":"1.3.6 Căn cứ vào mức độ nguy hại","b":[["p","+ Tranh chấp quốc tế nguy hại: có nguy cơ phá hoại hòa bình và an ninh quốc tế"],["p","+ Tranh chấp quốc tế thông thường: không dẫn đến nguy cơ đe dọa hòa bình và an ninh quốc tế."],["p","Phân biệt tranh chấp quốc tế và tranh chấp dân sự trong nước: Đoàn"],["t",[["Phân biệt","T/c Quốc tế","T/c Dân sự trong nước"],["Khái niệm","-Là những hoàn cảnh thực tế, trong đó các chủ thể liên quan có những quan điểm, đòi hỏi trái ngược nhau về những vấn đề liên quan đến lợi ích của họ","-Hiểu theo nghĩa hẹp thì đây là những bất đồng, xung đột lợi ích pháp lý giữa 2 bên trong lĩnh vực dân sự. Tranh chấp dân sự được hiểu là những mâu thuẫn, xung đột xảy ra giữa các chủ thể trong các quan hệ về nhân thân hoặc tài sản được pháp luật dân sự quy định"],["Chủ thể","-Là chủ thể của LQT mà trước tiên và chủ yếu là các quốc gia ( vì quan hệ quốc tế chủ yếu là quan hệ giữa các quốc gia )","-Là chủ thể của LQG ( ở đây là LDS ) cụ thể ở đây sẽ là: cá nhân, pháp nhân, hộ gia đình và tổ hợp tác"],["Đối tượng điều chỉnh","-Phải là Q. hệ PL thuộc đối tượng điều chỉnh của LQT như: các QH xã hội phát sinh trên nhiều lĩnh vực trong QHQT vượt ngoài tầm QGia ( C.trị , K.tế, VH, AN-QP…)","-Phải là những QHXH cơ bản phát sinh trong lĩnh vực dân sự: Qh nhân thân, Qh tài sản -Cụ thể các tranh chấp thường gặp: quyền sở hữu tài sản thừa kế, tài sản ly hôn, tranh chấp về đất đai, tranh chấp dân sự liên quan đến hợp đồng, cơ chế quy định trong hợp đồng mua bán, vay tài sản, đầu tư, chuyển giao công nghệ, vận chuyển, bảo hiểm, dịch vụ, các tranh chấp lao động..."],["Thẩm quyền giải quyết","-Xuất phát từ bản chất pháp lý của LQT là sự thỏa thuận nên thẩm quyền giải quyết sẽ khác với tranh chấp giải quyết theo LQG. Cụ thể thẩm quyền giải quyết thuộc các chủ thể pháp lý sau: +Các bên trong tranh chấp( thường là các T/c song phương ) +Các cơ quan tài phán quốc tế: Do được các bên trong T/c trao thẩm quyền giải quyết. Cơ quan này do các chủ thể LQT thỏa thuận hình thành bao gồm: Tòa án QT và Trọng tài QT","-Theo điều 37 BLTTDS 2015, thì Tòa án nhân dân cấp tỉnh có thẩm quyền giải quyết các tranh chấp dân sự, hôn nhân và gia đình, kinh doanh thương mại, lao động thuộc thẩm quyền giải quyết của Tòa án theo loại việc trừ tranh chấp thuộc thẩm quyền giải quyết của Tòa án nhân dân cấp huyện."]]],["p","Nguồn luật/ Cơ chế giải quyết tranh chấp quốc tế: nguồn luật nội dung và nguồn luật tố tụng: Đạt"],["p","Nguồn nội dung là cơ sở pháp lý để các cơ quan tài phán quốc tế quyết định các vấn đề liên quan như:"],["p","Có hay không hành vi vi phạm pháp luật quốc tế"],["p","Hành vi của chủ thể đúng hay sai; được phép hay không được phép"],["p","Chủ thể có quyền và nghĩa vụ pháp lý hay không"],["p","Phải chịu trách nhiệm pháp lý quốc tế hay không"],["p","Nguồn tố tụng là nguồn luật quy định trình tự thủ tục tố tụng để giải quyết các tranh chấp quốc tế"],["p","Điều ước quốc tế đa phương toàn cầu:"],["p","Công ước về giải quyết hòa bình các xung đột quốc tế được thông quatại Hội nghị Lahay lần thứ nhất vào năm 1899 và được bổ sung vào năm 1907 tại Hội nghị Lahay lần thứ hai. (Tuy chủ yếu được ký kết giữa các nước lớn nhằm củng cố địa vị, nhưng cũng cho thấy sự tự giác của các quốc gia)"],["p","Tuyên bố chung về giải quyết hòa bình các tranh chấp quốc tế được Hội quốc liên thông qua ngày 26/9/1928, sau đó được LHQ chấp nhậnbằng một nghị quyết của Đại hội đồng ngày 28/4/1949 (có bổ sung, cấm hoàn toàn các biện pháp vũ lực)"],["p","Hiến chương LHQ"],["p","Các điều ước quốc tế về các lĩnh vực chuyên biệt cũng xây dựng đượccơ chế"],["p","Điều ước quốc tế đa phương khu vực:"],["p","Hiệp ước Liên Mỹ về giải quyết hòa bình các tranh chấp năm 1948 (Hiến chương Bogota)"],["p","Công ước Châu Âu về giải quyết hòa bình các tranh chấp được Hội đồng Châu Âu thông qua năm 1957."],["p","Công ước về hoà giải và trọng tài trong khuôn khổ tổ chức an ninh và hợp tác Châu Âu năm 1992."],["p","Hiến chương các tổ chức quốc tế khu vực"],["p","Giải quyết tranh chấp quốc tế theo Hiến chương Liên hợp quốc: Gia Hân"],["p","Trước hội đồng bảo an"],["p","Khái niệm:"],["p","Là cơ quan hạn chế, thường trực và đặc thù của LHQ. HĐBA gồm 15 thành viên"],["p","Chức năng và nhiệm vụ:"],["p","Chức năng và nhiệm vụ của HĐBA rất rộng và tập trung chủ yếu vào 2 lĩnh vực:"],["p","+ Giải quyết hòa bình các tranh chấp quốc tế (chương VI của Hiến chương)"],["p","+ Duy trì hòa bình và đấu tranh chống xâm lược (chương VII của Hiến chương)."],["p","Thẩm quyền giải quyết tranh chấp của HĐBA được ghi nhận tại chương VI của Hiến chương ( Điều 33 đến điều 38)."],["p","HĐBA có toàn quyền giải quyết các tranh chấp quốc tế phát sinh trong đời sống quốc tế."],["p","Tranh chấp nếu kéo dài có khả năng làm nguy hại hòa bình và an ninh quốc tế:"],["p","Theo Điều 34 Hiến chương LHQ, HĐBA là cơ quan duy nhất có quyền điều tra, xem xét tranh chấp nào là tranh chấp nếu kéo dài có khả năng làm nguy hại hòa bình và an ninh quốc tế. Bên cạnh đó, HĐBA còn có thẩm quyền nghiên cứu những tranh chấp hoặc tình thế nếu kéo dài có khả năng làm nguy hại hòa bình và an ninh quốc tế theo kiến nghị của Tổng thư ký LHQ, của ĐHĐ và của một quốc gia (hoặc các quốc gia) Điều cần lưu ý là không chỉ quốc gia thành viên LHQ mà cả quốc gia không phải là thành viên LHQ cũng có thể yêu cầu HĐBA lưu ý đến bất cứ tranh chấp nào thuộc loại trên mà họ là một bên tranh chấp với điều kiện quốc gia này phải thừa nhận nghĩa vụ giải quyết hòa bình các tranh chấp theo quy định của Hiến chương LHQ. Điều này nhằm đảm bảo không chỉ các cơ quan chức năng của LHQ mà tất cả các quốc gia luôn có ý thức đối với cộng đồng."],["p","Sau khi điều tra và HĐBA xác định đó là tranh chấp nếu kéo dài có khả năng làm nguy hại hòa bình và an ninh quốc tế, HĐBA sẽ mời các bên giải quyết tranh chấp bằng một trong những phương thức nêu ở khoản 1 Điều 33 Hiến chương, đó là đàm phán, điều tra, trung gian, hòa giải, trọng tài, tòa án, thông qua các tổ chức quốc tế hay các hiệp định khu vực, hoặc bằng các biện pháp hòa bình khác do họ tự chọn. Quyền hạn này của HĐBA còn được mở rộng và phát triển theo Điều 36 Hiến chương, theo đó trong bất kỳ giai đoạn nào của tranh chấp HĐBA có thể khuyến nghị các bên một trình tự và biện pháp giải quyết thích đáng. Bên cạnh đó, HĐBA cũng lưu ý đến biện pháp mà các bên tranh chấp đã tiến hành nhằm giải quyết các tranh chấp quốc tế (khoản 2 Điều 36 Hiến chương)"],["p","Tranh chấp thông thường:"],["p","Khác với tranh chấp nếu kéo dài có khả năng làm nguy hại hòa bình và an ninh quốc tế, tranh chấp thông thường là loại tranh chấp mà nếu như kéo dài thì cũng không có khả năng đe dọa hòa bình và an ninh quốc tế. Đây là tranh chấp phát sinh trong mọi lĩnh vực đời sống quốc tế của các quốc gia và không có nguy cơ đe dọa hòa bình, an ninh quốc tế."],["p","Điều 38 của Hiến chương quy định, trong bất kỳ vụ tranh chấp nào do các bên đệ trình, HĐBA có thể giải quyết hòa bình các tranh chấp quốc tế đó bằng cách đưa ra các khuyến nghị. Cần phải nhìn nhận rằng việc áp dụng quy định này chỉ có thể được thực hiện với điều kiện được sự đồng ý của các bên tranh chấp yêu cầu HĐBA. Khuyến nghị được HĐBA đưa ra trên cơ sở của Điều 38 Hiến chương không có hiệu lực ràng buộc, bởi vì HĐBA chỉ tham gia giải quyết tranh chấp với tư cách cơ quan hòa giải và đưa ra chỉ dẫn kiến nghị."],["p","Tóm lại, dựa trên cơ sở quy định tại chương VI của Hiến chương, có thể khẳng định rằng, HĐBA có thẩm quyền trong việc giải quyết tranh chấp quốc tế giữa các quốc gia với các vai trò khác nhau như điều tra, trung gian, hòa giải. Trong tất cả các trường hợp nói trên, HĐBA đưa ra các khuyến nghị phù hợp và các khuyến nghị này không có hiệu lực bắt buộc đối với các bên tranh chấp. Vì vậy, không nên nhầm lẫn giữa các quyết định của HĐBA đưa ra trên cơ sở của chương VI Hiến chương, chỉ mang ra trên cơ sở chương VII của Hiến chương trong trường hợp hòa bình bị đe dọa hoặc có hành vi xâm lược."],["p","Trước tòa công lý quốc tế"],["p","Khái niệm:"],["p","TACLQT LHQ là cơ quan tư pháp chính của LHQ, hoạt động trên cơ sở quy chế của mình. TACLQT là cơ quan chính của LHQ, còn Quy chế TACLQT là một bộ phận không thể tách rời của Hiến chương LHQ."],["p","Thành viên LHQ đương nhiên là thành viên của Quy chế TACLQT. Tuy nhiên, các quốc gia không phải thành viên của LHQ cũng có thể là thành viên của Quy chế TACLQT. Ví dụ, Thụy Sĩ, Nhật Bản, Nauru khi chưa là thành viên LHQ vẫn được thừa nhận là thành viên của Quy chế TACLQT."],["p","Cơ sở pháp lý xác định chức năng và hoạt động của TACLQT chủ yếu là Hiến chương LHQ,” Quy chế của TACLQT và nội quy của tòa."],["p","Thẩm quyền chính của Tòa án Công lý quốc tế của Liên hợp quốc:"],["p","Theo Điều 36 Quy chế TACLQT, tòa có thẩm quyền giải quyết tất cả các tranh chấp mà các bên đưa ra cũng như các vấn đề được quy định riêng biệt trong Hiến chương LHQ hoặc vận điều ước quốc tế có hiệu lực. Cụ thể, tòa án quốc tế có 2 thẩm quyền như sau:"],["p","+ Giải quyết các tranh chấp phát sinh giữa các quốc gia phù hợp với quy chế của mình. Tòa án không chỉ giới hạn thẩm quyền xét xử giữa các quốc gia thành viên LHQ Các quốc gia 43 không phải là thành viên LHQ có thể tham dự vào quá trình giải quyết tranh chấp tại tòa với tư cách bên nguyên đơn, bên bị đơn hoặc bên liên quan với điều kiện đáp ứng các đòi hỏi, yêu cầu do Đại hội đồng (ĐHĐ) đưa ra trong từng vụ cụ thể dựa trên cơ sở khuyến nghị của HĐBA."],["p","+ Tư vấn pháp luật, đưa ra các kết luận tư vấn về các vấn đề pháp lý mà ĐHĐ, HĐBA cũng như các cơ quan khác của LHQ, các tổ chức quốc tế chuyên môn được sự chấp nhận của ĐHĐ yêu cầu. Riêng đối với ĐHĐ và HĐBA có thể yêu cầu tòa kết luận tư vấn về bất cứ vấn đề pháp lý liên quan."],["p","Phương thức chấp nhận thẩm quyền giải quyết tranh chấp của Tòa án Công lý Liên hợp quốc:"],["p","Căn cứ vào điều 36 của Quy chế tòa, sự chấp nhận thẩm quyền của tòa được thể hiện theo ba phương thức sau:"],["p","+ Chấp nhận thẩm quyền của tòa án quốc tế theo từng vụ việc (được gọi là thỏa thuận thỉnh cầu). Đây là phương thức chấp nhận sau, tức là khi có tranh chấp đã xảy ra, các quốc gia tranh chấp sẽ ký một thỏa thuận, được gọi là thỏa thuận thỉnh cầu, đề nghị tòa giải quyết tranh chấp giữa họ. Hình thức này đã được các quốc gia tranh chấp áp dụng rộng rãi như trong vụ Các đảo Minquiers và Ecréhous giữa Pháp và Anh, vụ Thềm lục địa biển Bắc giữa Cộng hòa liên bang Đức và Đan Mạch, Cộng hòa Liên bang Đức và Hà Lan."],["p","+ Chấp nhận trước thẩm quyền của tòa án trong các điều ước quốc tế. Ở phương thức này, trong các điều ước quốc tế, các quốc gia dự liệu trong các điều khoản đặc biệt, theo đó khi có tranh chấp xảy ra về việc giải thích và thực hiện điều ước quốc tế, một bên có thể đưa tranh chấp ra TACLQT LHQ. Do đó, sau này khi có tranh chấp xảy ra, chỉ cần một bên (nguyên đơn) gửi đơn đến tòa, tòa sẽ có thẩm quyền giải quyết. Ví dụ như vụ nhân viên ngoại giao và lãnh sự Mỹ tại Tehran, Mỹ kiện Iran dựa trên Nghị định thư về thủ tục giải quyết bắt buộc các tranh chấp trước TACLQT mà cả hai nước đã ký và phê chuẩn."],["p","+ Chấp nhận trước thẩm quyền của tòa án bằng một tuyên bố đơn phương. Theo phương thức này, khi cả hai quốc gia tranh chấp đều có tuyên bố đơn phương chấp nhận trước thẩm quyền của tòa và các tuyên bố này đồng thời có cùng phạm vi hiệu lực đối với một tranh chấp thì tòa có thẩm quyền xét xử tranh chấp đó. Các quốc gia có toàn quyền thể hiện ý chí của mình bằng tuyên bố đơn phương vào bất cứ thời điểm nào, với những nội dung hoặc những điều kiện gì để chấp nhận thẩm quyền xét xử của tòa. Thủ tục đăng ký các tuyên bố đơn phương này được thực hiện bằng cách gửi cho Tổng thư ký LHQ, Tổng thư ký sẽ làm nhiệm vụ lưu chiểu."],["p","Cơ cấu tổ chức của Tòa án Công lý quốc tế của LHQ:"],["p","Các thẩm phán thường trực:"],["p","Theo Điều 2 Quy chế TACLQT, tòa có cơ cấu là một hội đồng các thẩm phán độc lập, được lựa chọn không căn cứ vào quốc tịch, trong số những người có phẩm chất đạo đức tốt, đáp ứng các yêu cầu đề ra ở quốc gia họ để chỉ định chức vụ xét xử cao nhất, hoặc là những luật gia có uy tín lớn trong lĩnh vực luật quốc tế.” Tòa án quốc tế gồm 15 thẩm phán và số thẩm phán cần 50 thiết để tiến hành xét xử là 9. Trong số 15 thẩm phán, được bầu chọn theo một trình tự thủ tục do luật quy định, không thể có hai thành viên cùng quốc tịch. Thành phần hội đồng thẩm phán phải đảm bảo được tính đại diện, tính công bằng giữa các hệ thống pháp luật cơ bản trên thế giới, giữa các khu vực địa lý cũng như giữa các hình thái văn hóa chủ yếu trên thế giới. Quy định này nhằm mục đích đảm bảo cho các quyết định của tòa có hiệu lực cao và thu hút đông đảo các nước khác nhau trên thế giới áp dụng biện pháp giải quyết tranh chấp giữa họ bằng con đường tòa án quốc tế LHQ."],["p","Các thẩm phán ad học:"],["p","Theo Điều 31 Quy chế TACLQT, một hoặc các bên tranh chấp có thể đề cử các thẩm phán ad học (vụ việc) nếu xét thấy trong thành phần xét xử của tòa không có thẩm phán nào mang quốc tịch nước mình. Quy định này giúp cân bằng tình thế trước tòa giữa các bên tranh chấp, tuân thủ nguyên tắc các bên bình đẳng trước tòa, đồng thời cũng phát huy ưu thế phương thức trọng tài. Khi lựa chọn các thẩm phán ad học, cũng phải dựa trên tiêu chuẩn của Điều 2 Quy chế tòa liên quan đến việc lựa chọn các thẩm phán thường trực. Cũng cần phải lưu ý rằng, các thẩm phán ad học không có nghĩa vụ phải bỏ phiếu để bảo vệ quyền lợi cho bên tranh chấp nào đã lựa chọn họ. Vị thế của các thẩm phán ad học ngang bằng với các thẩm phán thường trực trong quá trình xét xử."],["p","Các phụ thẩm:"],["p","Tòa có thể tự quyết hoặc theo yêu cầu của các bên tranh chấp đưa ra trước khi kết thúc thủ tục viết, các phụ thẩm được đề cử tham gia vào thành phần xét xử của tòa. Họ là những chuyên gia giỏi trong các lĩnh vực kỹ thuật liên quan Các phụ thẩm không có quyền biểu quyết.55 đến vụ tranh chấp."],["p","Thư ký tòa:"],["p","Thư ký tòa do tòa đề cử. Ban thư ký của TACLQT là 56 một ban thường trực và chỉ phụ thuộc vào tòa, khác với Ban thư ký của LHQ (một trong sáu cơ quan chính của LHQ). Nhân viên của ban thư ký được hưởng chế độ ưu đãi và miễn trừ ngoại giao như nhân viên LHQ."],["p","Lương của thư ký tòa do ĐHĐ ấn định theo đề xuất của tòa và cũng được miễn mọi khoản thuế theo tinh thần khoản 8 Điều 32 của quy chế TACLQT. Ban thư ký gồm chánh thư ký, phó chánh thư ký và các nhân viên. Chánh thư ký và phó chánh thư ký do tòa bầu theo phương thức bỏ phiếu kín với nhiệm kỳ 7 năm."],["p","Các tòa rút gọn:"],["p","Như đã trình bày, thông thường TACLQT tiến hành xét xử bởi hội đồng toàn thể. Tuy nhiên, trong khuôn khổ hoạt động của mình, TAQT còn có loại hình gọi là tòa rút gọn, được thành lập để giải quyết từng vụ việc cụ thể của tòa. Theo Điều 28 của Quy chế TAQT, tòa rút gọn có thể được điều hành và thực hiện nhiệm vụ xét xử ở ngoài La Haye, được thực hiện chức năng của mình theo lẽ công băng và chân lý, ngôn ngữ sử dụng do các bên tranh chấp lựa chọn. Các phán quyết của tòa rút gọn được coi như phán quyết của tòa toàn thể. Căn cứ vào Điều 26 và 29 Quy chế TAQT, có 3 loại tòa rút gọn có thể được thành lập theo ý chí của TACLQT hoặc theo yêu cầu của các bên tranh chấp, cụ thể:"],["p","+ Tòa rút gọn tạm thời (tòa ad hoc), ở trường hợp này, thành phần của tòa rút gọn do TACLQT quy định dựa trên sự nhất trí của các bên.” Thực tế cho thấy, các bên thường thỏa 57 thuận thành phần của tòa là 5 thẩm phán. Một số vụ tranh chấp đã được giải quyết bởi tòa rút gọn tạm thời là vụ Vịnh Maine (Canada/Mỹ) năm 1982; vụ tranh chấp biên giới giữa Burkina 58 Faso và Mali năm 1985.5"],["p","+ Tòa đặc biệt: theo khoản 1 Điều 26 quy chế của TACLQT, nếu thấy cần thiết TACLQT có thể thành lập tòa đặc biệt gồm 3 thẩm phán hoặc nhiều hơn, nhằm phân tích từng vụ việc nhất định như vụ việc về lao động, quá cảnh và liên lạc quốc tế. ng th ng ta"],["p","+ Tòa rút gọn - trình tự tố tụng: theo hình thức này, hàng năm TACLQT lập ra tòa rút gọn trình tự tố tụng, có thành phần gồm 5 thẩm phán (chánh án, phó chánh án và 3 thẩm phán khác của tòa toàn thể). Tòa này xem xét và giải quyết các vụ việc theo trình tự xét xử sơ bộ nhằm mục đích thúc đẩy việc giải quyết các vụ việc."],["p","Những quy định kể trên cho thấy tòa rút gọn là cơ quan tài hán kết hợp được những thế mạnh của cơ quan tài phán thường ực với thể thức xét xử trọng tài."],["p","Thủ tục giải quyết tranh chấp tại Tòa án Công lý quốc tế LHQ:"],["p","Theo quy định tại Điều 43 Quy chế tòa, thủ tục tố tụng của TAQT gồm 2 giai đoạn kế tiếp nhau: Thủ tục viết và thủ tục nói."],["p","Trình tự tư vấn:"],["p","Trình tự đưa ra kết luận tư vấn của TACLQT về cơ bản tương tự như trình tự giải quyết tranh chấp, gồm 2 giai đoạn chính: viết và nói. Quá trình xác lập nội dung kết luận tư vấn cũng giống như quá trình nghị án giải quyết tranh chấp quốc tế."],["p","Vai trò của Đại hội đồng Liên hiệp quốc ( bao gồm all các quốc gia thành viên 193 nước): Bảo Hân"],["p","ĐHĐ gồm tất cả các quốc gia thành viên của Liên hợp quốc. Mỗi thành viên có nhiều nhất là 5 đại biểu ở Đại hội đồng."],["p","Vị trí và chức năng của ĐHĐ LHQ được quy định trong chương IV của Hiến chương LHQ 1945 (chức năng và quyền hạn của ĐHĐ được quy định từ Điều 10 cho đến Điều 17)"],["p","ĐHĐ có 3 vai trò trong vấn đề giải quyết tranh chấp:"],["p","Thứ nhất: có thể lưu ý với Hội đồng bảo an LHQ về những tranh chấp hay những tình thế mà theo đánh giá của ĐHĐ là có khả năng làm nguy hại đến hòa bình và an ninh quốc tế ( Khoản 3 Điều 11 )"],["p","=> Vai trò này mang tính chủ động"],["p","Thứ hai: khi Hội đồng bảo an LHQ thực hiện những chức năng mà Hiến chương LHQ quy định đối với một vụ tranh chấp hay một tình thế nào đó ( những chức năng liên quan đến bảo vệ, duy trì, khôi phục hoà bình và an ninh quốc tế ). ĐHĐ không được đưa ra một kiến nghị nào về tranh chấp hay tình thế ấy nếu như việc đó đang được hội đồng bảo an thực hiện, trừ khi được Hội đồng bảo an yêu cầu ( Khoản 1 Điều 12 )"],["p","=> Vai trò thứ hai mang tính chất thụ động"],["p","Thứ ba: ĐHĐ có thể kiến nghị những biện pháp thích hợp để giải quyết hòa bình mọi tình thế nảy sinh bất kỳ từ nguồn gốc nào, mà theo sự nhận xét của ĐHĐ là làm phương hại đến lợi ích chung hoặc gây tổn hại cho các quan hệ hữu nghị giữa các dân tộc, kể cả những tình thế nảy sinh do vi phạm những quy định về các mục đích và nguyên tắc của liên hợp quốc ghi trong hiến chương. ( Điều 14 )"],["p","=> Đây là một vai trò chung chung, có thể kiến nghị những biện pháp thích hợp với mục đích cuối cùng là thế giới này tồn tại và phát triển 1 cách hoà bình trong khuôn khổ của Hiến chương LHQ."],["p","Tất cả các quốc gia là thành viên của LHQ (193 qg) đều có thể lưu ý với Hội đồng bảo an LHQ hoặc ĐHĐ giải quyết tranh chấp quốc tế mà bản thân quốc gia đó có liên quan. Tuy nhiên vụ tranh chấp đó cần phải có điều kiện là có thể xảy ra mà dẫn đến việc bất hòa quốc tế hoặc gây đe dọa đến việc duy trì hòa bình và an ninh quốc tế (Khoản 1 Điều 35 Hiến chương LHQ)"],["p","Đối với các qg không phải là thành viên của LHQ, họ vẫn có thể lưu ý với Hội đồng bảo an hoặc ĐHĐ về mọi tranh chấp mà trong đó họ là đương sự, với điều kiện là quốc gia này phải thừa nhận trước những nghĩa vụ giải quyết hòa bình các cuộc tranh chấp như Hiến chương quy định."],["p","Vd: nếu qg A có tranh chấp quốc tế với qg B, mà qg A không phải là thành viên của LHQ nhưng vẫn muốn nhờ tới Hội đồng bảo an LHQ giúp đỡ để giải quyết các tranh chấp đó thì họ cần phải đưa ra tuyên bố thừa nhận nghĩa vụ giải quyết hoà bình các cụ tranh chấp quốc tế theo như hiến chương."],["p","Vai trò của Hội đồng bảo an: Nhị Hoàng"],["p","HĐBA là cơ quan chính của LHQ để giữ gìn hòa bình và an ninh quốc tế. HĐBA có quyền điều tra các nguy cơ đe dọa nền hòa bình quốc tế, sắp xếp giải hòa các xung đột và yêu cầu các nước thành viên LHQ thi hành lệnh trừng phạt kinh tế, ngoại giao, quân sự. HĐBA tiến cử Tổng Thư ký cho Đại Hội đồng bầu ra và kiến nghị Đại Hội đồng kết nạp nước mới vào LHQ. HĐBA Là cơ quan thường trực của Liên hợp quốc chịu trách nhiệm chính trong việc duy trì hòa bình và an ninh quốc tế. Khi thực hiện các trách nhiệm và nghĩa vụ mà Hiến chương quy định, Hội đồng Bảo an phải hành động với tư cách thay mặt cho các thành viên của Liên hợp quốc."],["p","Giải quyết tranh chấp quốc tế ( chương 6 Hiến chương)"],["p","trong mỗi vụ tranh chấp, các bên đương sự trong các cuộc tranh chấp, mà việc kéo dài các cuộc tranh chấp ấy có thể đe dọa đến hoà bình và an ninh quốc tế, trước hết, phải cố gắng tìm cách giải quyết tranh chấp bằng con đường đàm phán, điều tra, trung gian, hoà giải, trọng tài, toà án, sử dụng những tổ chức hoặc những điều ước khu vực, hoặc bằng các biện pháp hoà bình khác tùy theo sự lựa chọn của mình. Hội đồng bảo an, nếu thấy cần thiết, sẽ yêu cầu các đương sự giải quyết tranh chấp của họ bằng các biện pháp nói trên."],["p","Hội đồng bảo an có thẩm quyền điều tra mọi tranh chấp hoặc mọi tình thế có thể xảy ra dẫn đến sự bất hoà quốc tế hoặc gây ra tranh chấp, xác định xem tranh chấp ấy hoặc tình thế ấy nếu kéo dài có thể đe dọa đến việc duy trì hòa bình và an ninh quốc tế hay không."],["p","Việc duy trì hòa bình và an ( chương 7 Hiến chương)"],["p","Hội đồng bảo an có thẩm quyền quyết định những biện pháp nào phải được áp dụng mà không sử dụng vũ lực để thực hiện các nghị quyết của Hội đồng, và có thể yêu cầu các thành viên của Liên hợp quốc áp dụng những biện pháp ấy. Các biện pháp này có thể là cắt đứt toàn bộ hay từng phần quan hệ kinh tế, đường sắt, đường biển, hàng không, bưu chính, điện tín, vô tuyến điện và các phương tiện thông tin khác, kể cả việc cắt đứt quan hệ ngoại giao."],["p","Nếu Hội đồng bảo an nhận thấy những biện pháp nói ở trên là không thích hợp, hoặc tỏ ra là không thích hợp, thì Hội đồng bảo an có quyền áp dụng mọi hành động của hải, lục, không quân mà Hội đồng bảo an xét thấy cần thiết cho việc duy trì hoặc khôi phục hoà bình và an ninh quốc tế. Những hành động này có thể là những cuộc biểu dương lực lượng, phong toả và những cuộc hành quân khác, do các lực lượng hải, lục, không quân của các quốc gia thành viên Liên hợp quốc thực hiện."],["p","CSPL: Điều 33, 34, 41, 42 Hiến chương LHQ 1945"],["p","Phân biệt tranh chấp quốc tế và tình thế quốc tế: Huyền Cơ"],["t",[["","Tình thế quốc tế","Tranh chấp quốc tế"],["Khái niệm","CSPL: Điều 1, điều 34 Hiến chương LHQ - Tình thế quốc tế là những sự kiện diễn ra trong quan hệ quốc tế có khả năng ảnh hưởng, đe dọa đến hòa bình và an ninh quốc tế. VD: 1. Sự kiện Thổ Nhĩ Kỳ bắn rơi máy bay SU 24 của Nga đang làm nhiệm vụ tại Syria ngày 24/11/2025 ( Vedeo) 2. Sự kiện Triều Tiên tuyên bố thử thành công bom Nhiệt Hạch vào ngày 6/1/2016.","CSPL: Điều 33 Hiến chương LHQ. - Tranh chấp quốc tế là hoàn cảnh thực tế mà trong đó các chủ thể của LQT có những quan điểm pháp lý và quyền lợi mâu thuẫn trái ngược nhau dẫn đến các yêu sách hay đòi hỏi cụ thể trái ngược nhau. - Hiến chương Liên hợp quốc và Công pháp quốc tế đã xác định các nguyên tắc giải quyết tranh chấp quốc tế là giải quyết bằng phương pháp hòa bình, thương lượng; không được sử dụng hoặc đe dọa sử dụng vũ lực; giữ nguyên hiện trạng cho đến khi đạt đến thỏa thuận cuối cùng; các bên tranh chấp phải tự kiềm chế không tiến hành bất cứ hoạt động nào làm cho tình hình trở nên xấu đi. VD: - Tranh chấp liên quan đến chương trình hạt nhân giữa Iran-Mỹ - Tranh chấp về biên giới giữa Lào và Campuchia - Giải thích sự kiện Mỹ và liên quân tấn công Iraq lần 2 ngày 20/3/2003"],["Đối tượng","Hẹp hơn. VD: Tình thế tranh chấp có thể xuất hiện do các vụ đụng độ biên giới, sự tập trung quân đội của quốc gia này tại khu vực biên giới.","Rộng hơn Tranh chấp quốc tế có thể xảy ra trong tất cả các lĩnh vực hoạt động quốc tế của các quốc gia, nhưng nổi cộm nhất, chủ yếu nhất là tranh chấp về chủ quyền lãnh thổ bao gồm chủ quyền trên đất liền, trên các hải đảo, trên biển, trên không..."]]]]}]}]};
